import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст Преображенню Господньому","e":"Akathist to the Transfiguration of the Lord","secs":[{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Царю́ сла́ви, Тебі́ небесі́ і землі́ Созда́теля, зря́щи на горі́ Фаво́рстій преобрази́вшася со сла́вою, вся твар удиви́ся, небеса́ вострепета́ша, і всі земноро́днії возра́довашася, ми же недосто́йнії Твоєму́ нас ра́ди Преображе́нію благода́рственно поклоне́ніє принося́ще, с Петро́м от душі́ вопіє́м Ті:","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Ікос 1","ps":["А́нгелом недові́домоє і челові́ком непристу́пноє Твоє́, Світода́вче Христе́, Божество́, незаходи́тельними мо́лніями і луча́ми Невече́рняго Сві́та Твоєго́, яви́л єси́ на горі́ Фаво́рстій нача́льнійшим ученико́м Твої́м, ті́ї же Боже́ственним ізміни́шася у́жасом, о́блаком осія́вшеся сві́тлим і глас Оте́чь сли́шавше, разумі́ша Твоєго́ вочелові́ченія та́їнство, вопію́ще Тебі́ такова́я:","Ісу́се, Си́не Бо́жий Безсме́ртний, просвіти́ нас сві́том Лиця́ Твоєго́ осія́ннаго;","Ісу́се, Благи́й Бо́же Всеси́льний, возбуди́ нас спя́щих із глубини́ тьми сна гріхо́внаго.","Ісу́се, во сві́ті живи́й непристу́пнім, із о́бласти те́мния ізведи́ нас;","Ісу́се, Сла́вою Твоє́ю іспо́лнивий весь мир, во оби́телі ра́йськия введи́ нас.","Ісу́се, Сві́те ми́ра, от ми́ра лука́ваго свободи́ нас во тьмі сідя́щих;","Ісу́се, Со́лнце Пра́вди, си́лою і пра́вдою облеци́ нас, в сі́ні сме́ртній спя́щих.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 2","ps":["Ви́дя, я́ко ученици́ Твої́, Человіколю́бче Го́споди, непросвіще́нни єще́ су́ще, не разумі́ють, я́ко подоба́єть Тебі́ ідти́ во Ієрусали́м і та́мо мно́го пострада́ти і убіє́ну би́ти, Ти отто́лі нача́л єси́ ска́зовати їм, я́ко вся сія́ належи́ть Тебі́ во́лею претерпі́ти на́шего ра́ди спасе́нія. Оба́че ті́ї не возмого́ша єще́ ми́слити, я́же суть Бо́жия, но я́же суть челові́чеськая, сего́ ра́ди по днех шести́х поя́л єси́ Петра́, Іа́кова і Іоа́нна і возве́л єси́ я на го́ру Фаво́рськую показа́ти їм пре́жде Креста́ Боже́ственную Сла́ву Твою́, да і во вре́м'я страда́ній Твої́х разу́мно воспою́ть Тебі́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зума неуразуме́нна во́льнаго Твоєго́ страда́нія не разумі́ша ученици́ Твої́, Го́споди. Сего́ ра́ди пре́жде Креста́ Твоєго́ но́щію глубо́кою возве́л єси́ на го́ру високу́ лу́чшія ученики́ Твоя́, да ви́дять чу́до стра́шнаго Преображе́нія Твоєго́ і нестерпи́моє Боже́ственнаго прише́ствія Твоєго́ іздале́ча присносу́щноє благолі́піє, да єгда́ Тя у́зрять распина́єма, страда́ніє у́бо Твоє́, да уразумі́ють во́льноє. Сего́ ра́ди вопіє́м Тебі́ си́це:","Ісу́се, от удо́лій на го́ру високу́ возведи́й Твоя́ ученики́, возведи́ і нас го́ре, да го́рніх научі́мся іска́ти наслажде́ній;","Ісу́се, от жите́йських попече́ній і мно́жества наро́днаго отлучи́вий Петра́ і Зеведе́ових, отлучи́ наш ум от благ земни́х, да до́льних нави́кнем ізбіга́ти пристра́стій.","Ісу́се, мно́гими труди́ на преве́лію висоту́ вознеси́й дру́ги своя́, і нас мно́гими труди́ і по́ти научи́ по вся дні подвиза́тися;","Ісу́се, в молча́нії нощни́я моли́тви Преображе́ніє Твоє́ ученико́м показа́вий, і ни́ні ві́рним Твої́м сподо́би сла́достію слове́с Твої́х в нощі́ просвіща́тися.","Ісу́се, трех то́чію свиді́телей сла́ви Твоєя́ в тишині́ Фаво́рстій яви́вий, і ни́ні безмо́лвним і пусти́нним даждь сла́ву Твою́ всегда́ созерца́ти;","Ісу́се, Фаво́р і Ермо́н о І́мені Твоє́м возвесели́вий, даждь нам призива́нієм сладча́йшаго І́мені Твоєго́ восхо́д го́ре соверша́ти.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 3","ps":["Си́лою сви́ше ізбра́нния Твоя́ Апо́столи облеки́й, Ісу́се, на Фаво́р возве́л єси́ я, да нави́кнуть ви́шніх іска́ти і го́рняя му́дрствовати, а не земна́я, облеци́ і нас, до́лу пони́кших і не́мощію пло́ті всегда́ побіжда́ємих, си́лою і сла́вою Твоє́ю, да си́ла Твоя́ в не́мощі на́шей соверши́ться, чесо́ ра́ди с любо́вію воспоє́м Тебі́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй пре́жде Креста́ і во́льнаго страда́нія Твоєго́ яви́ти ученико́м отча́сти Божества́ Сла́ву Твою́, Христе́ Спа́се наш, Ти трех то́чію от живу́щих на землі́ ізбира́єши, да зри́теліє Боже́ственния Твоєя́ сла́ви бу́дуть, і́бо ті́ї три пред очи́ма Твої́ма лу́чши бя́ху па́че всіх наро́дов і язи́к: Петр, я́ко па́че іни́х Тебі́ возлюби́вий, і я́ко пе́рвий от всіх Си́на Бо́жия Тебі́ іспові́давий, Іа́ков, я́ко пе́рвий во Апо́століх наде́жди ра́ди бу́дущих благ под меч главу́ свою́ преклони́вий і та́ко нача́ло му́чеником Твої́м положи́вий, Іоа́нн же, я́ко ді́вственник і па́че всіх чистоту́ пло́ті і ду́ха цілому́дренно сохрани́вий і сего́ ра́ди благода́ть осо́бную па́че іни́х получи́вий к зрі́нію неізрече́нних открове́ній і Боже́ственния Сла́ви Твоєя́. С ни́миже прийми́ і от нас похвали́ Тебі́ сицеви́я:","Ісу́се, от Петра́ пре́жде Преображе́нія Твоєго́ іспові́даніє ві́ри приє́мий, прийми́ і моє́ те́плоє іспові́даніє;","Ісу́се, тому́ же Петру́ на Фаво́рі дерзнове́ніє дарова́вий глаго́лати с Тобо́ю, возглаго́ли блага́я і ми́рная в се́рдці моє́м.","Ісу́се, сино́в Зеведе́ових за пла́мень любві́ їх сина́ми гро́мовими нареки́й, гро́мом гні́ва Твоєго́ не порази́ м'я;","Ісу́се, тім же ученико́м огнь с небесе́ на Самаря́н низвести́ не попусти́вий, огнь страсте́й угаси́ во мні.","Ісу́се, с ді́вственним Іоа́нном в чистоті́ пло́ті і ду́ха на Фаво́р го́рній возведи́ м'я;","Ісу́се, с му́жественним Іа́ковом, пе́рвіє ча́шу Твою́ іспи́вим, в рай введи́ м'я.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 4","ps":["Бу́ря Богоявле́нія Твоєго́ на горі́ Сина́йстій бисть, єгда́ во гро́міх і мо́лніях дарова́л єси́ зако́н уго́днику Твоєму́ Моїсе́йові, та́кожде і на горі́ Хори́ві бисть дух крі́пок, разоря́яй го́ри, трус і огнь, єгда́ Ілия́ проро́ко хотя́ше зрі́ти Тя, оба́че не во ви́хрі бу́рні, не в тру́сі і не во огні́ Госпо́дь, но во гла́сі хла́да то́нка Ти показа́л єси́ їм Лице́ Своє́ і сла́ву Божества́ Своєго́, єгда́ на горі́ Фаво́рстій Ти предста́л єси́ їм, с ра́достію вопію́щим Тебі́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше Моїсей і Ілия́ на Фаво́рі глаго́ли Твоя́ о ісхо́ді Твоє́м, єго́же хотя́ше сконча́ти во Ієрусали́мі, би́ша всему́ ми́ру свиді́теліє Твої́, Го́споди, я́ко Ти єси́ воі́стину Син Бо́жий на спасе́ніє люде́й от Бо́га Отця́ по́сланний і гла́сом с небесе́ Тім пока́занний. Мойсе́й у́бо от ме́ртвих при́зван бисть да свиді́тельствуєть во а́ді держи́мим Твоє́ в мир прише́ствіє. Ілия́ же от рая́ при́зван бисть, да ска́жеть Єно́ху Сла́ву Твою́ в Преображе́нії пречи́стия Пло́ті Твоєя́ ви́дінную. Ми же, чудя́щеся та́йні проро́к Твої́х на Фаво́рі явле́нія, со умиле́нієм зове́м Тебе́:","Ісу́се, Богови́дцю Моїсе́ю, Лице́ Твоє́ узрі́ти восхоті́вшему, на Фаво́рі Лице́м к лицю́ яви́вийся, яви́ нам в гряду́щем ві́ці Лиця́ Твоєго́ сла́дость превожделе́нную;","Ісу́се, в боговиді́нії за́дніх Твої́х дре́вле Моїсе́ю сія́ніє Сла́ви Твоєя́ Показа́вий, покажи́ нам во Ца́рствії Твоє́м лице́м к Лицю́ Зра́ка Твоєго́ добро́ту неізрече́нную.","Ісу́се, в тишині́ і гла́се хла́да то́нка Ілію́ открове́нієм Свої́м наста́вивий, наста́ви м'я чу́дно в тишині́ безстра́стія боже́ственнаго;","Ісу́се, на о́гненній колесни́це неопа́льнаго небоше́ственника Твоєго́ Ілію́ в рай возведи́й, возведи́ м'я ди́вно на висоту́ житія́ соверше́ннейшаго.","Ісу́се, дре́вле с проро́ки многообра́зно глаго́лавий, і на Фаво́рі ісхо́д Свой їм возвісти́вий, глаго́лами живота́ ві́чнаго напита́й а́лчущую ду́шу мою́;","Ісу́се, при усті́х двою́ свиді́телей Та́йну Преображе́нія ученико́м Твої́м откри́вий, воздиха́ньми неізглаго́ланними Свята́го Ду́ха воспламени́ хла́дную ві́ру мою́.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ в нощі́ возсія́вшей, уподо́бися, Світода́вче Го́споди, неізрече́нноє осія́ніє пречи́стия Пло́ті Твоєя́, єгда́ ученико́м спя́щим і но́щі, уже́ ко у́тру приближа́ющейся, Ти возноси́л єси́ Отцю́ Твоєму́ на висоті́ гори́ преми́рную моли́тву Свою́. Тогда́ просвіти́ся Лице́ Твоє́, я́ко со́лнце, і ри́зи Твоя́ би́ша блеща́щася, біли́ зіло́, я́ко сніг. Апо́столи же от наше́дшия Боже́ственний си́ли убуди́шеся, уви́діша Сла́ву Твою́, я́ко Єдиноро́днаго от Отця́, іспо́лнь благода́ті і і́стини, і стоя́ху тре́петни, пою́ще Тебі́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше Апо́столи Тя на Фаво́рі во о́бразі челові́честім су́щаго, сла́вою же Боже́ственною Преобрази́вшася і с Моїсе́ом і Іліє́ю о ісхо́ді Твоє́м бесі́дующа, разумі́ша присносу́щную си́лу Твою́ і Божество́ под покро́вом пло́ті сокрива́ємо, і ужа́сни би́ша, послу́шающе глаго́лемих і наслажда́ющеся зрі́нія Твоєя́ Боже́ственния сла́ви, ю́же толи́ко ви́діша, єли́ка тіле́сних оче́с зрі́ніє їх вмісти́ти можа́ше. С ни́миже і ми поє́м Тебі́ такова́я:","Ісу́се, возсія́вий ученико́м Твої́м неізрече́нную і Богосія́нную Сла́ву Твою́, возсія́й в душа́х на́ших Світ Твой присносу́щний;","Ісу́се, причасти́вий первостоя́телі зако́на і благода́ті преми́рнаго Сві́та Твоєго́, причаще́нієм Того́ собери́ ум наш приснозаблу́ждший.","Ісу́се, сокрове́нную во пло́ті мо́лнію Божества́ Твоєго́ на Фаво́рі ма́ло обнажи́вий, обнажи́ сокрове́нния гріхопаде́нія в убо́гой со́вісти моє́й;","Ісу́се, несозда́ннаго Сві́та Твоєго́ луча́ми із Пло́ті Твоєя́ Святу́ю го́ру озари́вий, озари́ світ за́повідей Твої́х во мра́чній душі́ моє́й.","Ісу́се, Преображе́нієм пречи́стия Пло́ті Твоєя́ просвіти́вий ми́ра конці́, просвіти́ і украси́ нас помраче́нних;","Ісу́се, блиста́нієм Фаво́рськаго Сві́та Твоєго́ очи́стивий, я́ко сніг, твоя́ ученики́, очи́сти і обнови́ нас потемне́нних.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 6","ps":["Ви́дівше пребла́гостноє і спаси́тельноє собесі́дованіє Твоє́, Христе́ Бо́же наш, со Моїсе́ом і Іліє́ю на горі́ Фаво́рстій, возра́довашеся зіло́ ученици́ Твоя́: Петр, Іа́ков і Іоа́нн. Петр же гла́сом любве́ боже́ственній іспо́лненним рече́: «Го́споди, добро́ єсть нам зді би́ти: а́ще хо́щеши, сотвори́м зді три сі́ні, Тебе́ єди́ну, і Моїсе́йові єди́ну, і єди́ну Ілії́». Ми же недосто́йнії, не дерза́єм пря́мо Тебі́ вопроша́ти, оба́че смире́нно о поми́лованії мо́лим Тя і гла́сом тре́петнім вопіє́м Ті: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ на Фаво́рі во зна́меніє всей вселе́нній о́блак сві́тел, Петру́ о сі́ніх вопроша́ющу, открове́ніє гла́са Оте́чеськаго возвеща́ющ і Ду́ха Свята́го прише́ствіє, і єгда́ осіни́ Апо́столи, верх гори́ окружа́юще, ті́ї па́че убоя́шася і во о́блак со стра́хом вступи́вше, ощути́ша Твоє́ непристу́пноє Божество́, і со дерзнове́нієм мно́гим возопи́ша к Тебі́ такова́я:","Ісу́се, Ізра́їля дре́вле столпо́м о́блачним в пусти́ні путеводи́вий, Сам і ни́ні путь во Ца́рствіє Твоє́ нам укажи́;","Ісу́се, Апо́столи Твоя́ во о́блаці сві́тлі на Фаво́рі осени́вий, росо́ю Ду́ха Твоєго́ Свята́го нас осіни́.","Ісу́се, во Хра́мі нерукотворе́ннім Живи́й на небесі́, храм світови́ден і сінь пречи́стую покажи́ мі Твоєго́ Божества́;","Ісу́се, ски́ній рукотворе́нних не восхоті́вий на землі́, вну́треннюю благообра́зную ски́нію Ду́ха Твоєго́ сотвори́ м'я, во є́же взи́ти на небеса́.","Ісу́се, одія́йся сві́том, я́ко ри́зою, облеци́ м'я обнаже́ннаго в боготка́нния ри́зи цілому́дрія і чистоти́;","Ісу́се, простира́яй не́бо, я́ко ко́жу, оде́ні м'я острупле́ннаго в снегосве́тлия оде́жди Твоєя́ небе́сния красоти́.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 7","ps":["Хотя́ откри́ти сокрове́нную от ві́ка та́йну Твоєго́, Христе́, Божества́, Оте́ць Твой Небе́сний па́ки я́коже пре́жде на Іорда́ні во вре́м'я Креще́нія Твоєго́, Богосино́вство Твоє́ возвісти́ і та́ко гла́сом із о́блака би́вшим свиді́тельствова, глаго́ля: «Сей єсть Син Мой Возлю́бленний, Того́ послу́шайте». Апо́столи же от вели́каго у́жаса крі́пости своєя́ лиши́вшися, падо́ша ниць на зе́млю, вопію́ще Тебі́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая ви́дівше і пресла́вная на Фаво́рі би́вшая, Словесе́ Твоєго́, Влади́ко Го́споди, самови́дці і слуги́, і глас Оте́чеський і шум із о́блака сли́шавше, ужа́сни би́ша і но́вим світоли́тієм внеза́пу освеща́хуся, друг дру́га зря́ху, удивля́ющеся і к землі́ па́дше ниць, Тебі́ Влади́ці вся́чеських поклони́шася, похвали́ Тебі́ возсила́я такови́я:","Ісу́се, О́бразе Пресві́тлия Іпоста́си О́тчія, преобрази́ мра́чноє і нечи́стоє житіє́ моє́;","Ісу́се, Сла́ви О́тчія Сія́ніє, просвіти́ па́дшую і во тьму воглу́бльшуюся ду́шу мою́.","Ісу́се ди́вний і стра́шний во сла́ві Боже́ственнаго зра́ка Твоєго́, тлі́нієм растлі́нний душе́вний наш зрак обнови́;","Ісу́се ти́хий, любві́ по́лний, неізрече́нною сві́тлостію Пло́ті Твоєя́ всю нечистоту́ пло́ті моєя́ па́че сні́га убіли́.","Ісу́се, Сві́те Безнача́льний, во сві́ті Твоє́м, на Фаво́рі явле́ннім, Світ покажи́ нам Отця́;","Ісу́се, Сві́те неізмі́нний, в незри́мем Сві́те Ца́рства Твоєго́, Світ покажи́ нам і Ду́ха.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 8","ps":["Ди́вно і стра́нно яви́стася Тебі́ Моїсей і Ілия́ на Фаво́рі, Влади́ко Го́споди, начерта́ніє Боже́ственния Іпоста́си ви́дівше, і глаго́ласта о во́льном страда́нії Твоє́м, священнолі́пно предстоя́ще Тебі́. Осіни́вшу же їх о́блаку сві́тлу і гла́су с небесе́ би́вшу, взя́ться Сла́ва Госпо́дня от виді́нія учени́к Твої́х, взя́шася же і проро́ци во своя́ мі́ста, пою́ще Тебі́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ от ви́шніх, Неісче́тний Сло́ве Бо́жий, єгда́ пречи́стая Плоть Твоя́ преобража́шася на Фаво́рі, но і от ни́жніх ніка́коже отступи́л єси́, єгда́ отше́дшим проро́ком і виді́нію уже́ сконча́вшуся, Ти приступи́л єси́ к лежа́щим стра́ха ра́ди на землі́ Твої́м ученико́м, і руко́ю косну́вся їх, глаго́лал єси́ їм: «воста́ніте, не бо́йтеся». Ученици́ же, возве́дше о́чі свої́ і нікого́же ви́дівше, то́чію Тебе́ Єди́наго с ни́ми су́щаго, возра́довахуся зіло́ і возблагодари́ша Бо́га, пою́ще Тебі́ такова́я:","Ісу́се, імі́яй глаго́ли Живота́ ві́чнаго, всегда́ пребу́ди с на́ми во стра́нствії земно́м;","Ісу́се, наси́тивий нас зра́ком Твоєго́ Божества́, не оста́ви нас си́рих на служе́нії Твоє́м.","Ісу́се, пре́жде Креста́ Твоєго́ Та́йну во́льнаго страда́нія уясни́вий, пода́ждь нам всегда́ па́м'ятовати Твоє́ нас ра́ди істоща́ніє;","Ісу́се, пре́жде є́же умре́ти, нам сла́ву Твою́ Показа́вий, пода́ждь нам всегда́ да разумі́ти Твоєя́ Пло́ті обоже́ніє.","Ісу́се, о́бразе непремі́нний Су́щаго, обнови́ в душі́ моє́й вожделі́ннаго зра́ка Твоєго́ о́браз і подо́біє;","Ісу́се, печа́те равнообра́зная Отця́, запечатлі́й во пло́ті моє́й неізрече́нния добро́ти Твоєя́ благообра́зіє.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 9","ps":["Все єстество́ см'яте́ся, зря Твоє́ пресла́вноє на Фаво́рі Преображе́ніє, Христе́ Спа́се: А́нгели, незри́мо предстоя́ще, со стра́хом і тре́петом служа́ху Тебі́, небеса́ убоя́шася, подви́жеся і тре́петна бисть вся земля́, ви́дящи сла́ву Го́спода, «гора́ Фаво́р, пре́жде мра́чна і ди́мна», сві́тлим о́блаком покрива́шеся, «на не́йже» пречи́стії «но́зі Твої́ стоя́сте», ученици́ же Твої́, Го́споди, не терп'я́ще зрі́ти нестерпи́маго зра́ка Твоєго́, поверго́ша себі́ до́лу на зе́млю, ли́ця покрива́юще, до́ндеже Ти Сам, виді́нію сконча́вшуся, воздви́гл єси́ я, Тебі́ вопію́щих: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї суєму́дреннії, благода́тією непросвіще́ннії, не мо́гуть разумі́ти Твоєго́ пресла́внаго Преображе́нія та́їнства, Го́споди. Сего́ ра́ди, єгда́ со ученики́ сходи́л єси́ с гори́, дню возсіява́ти начина́ющу, Ти запові́дал єси́ друго́м Твої́м, да нікому́же пові́дять виді́нія би́вшаго, до́ндеже по прия́тії страда́нія і сме́рті воскре́снеши в тре́тій день от гро́ба. І ті́ї умолча́ша, і нікому́же возвісти́ша в ти́я дні нічесо́же от тіх, я́же ви́діша і сли́шаша, оба́че то́чію в се́рдці своє́м вопія́ху Тебі́ си́це:","Ісу́се, во всего́ Ада́ма оболки́йся, очерні́вшеє дре́вле єстество́ челові́че просвіти́;","Ісу́се, во о́блаці, огні́ і мра́ці носи́мий, Твоє́ю сві́тлостію весь мрак душе́вний в нас потреби́.","Ісу́се, сія́нієм Боже́ственнаго шу́ма Апо́столи Твоя́ услади́вий, услажда́й нас всегда́ глаго́лами Боже́ственнаго Твоєго́ открове́нія;","Ісу́се, росода́тельним о́блаком ученики́ Твої́ Просвіти́вий, просвіща́й нас всегда́ заря́ми пресла́внаго Твоєго́ Преображе́нія.","Ісу́се, пречи́стими нога́ми Твої́ми го́ру Фаво́рськую освяти́вий, напра́ви но́зі на́ша на при́сноє служе́ніє Тебе́;","Ісу́се, с непови́нними рука́ми на го́ру Твою́ восходи́ти повелі́вий, возбуди́ ру́ці на́ші на моли́твенноє воздія́ніє го́ре.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й мир, на Фаво́рі преобрази́лся єси́ нас ра́ди, Го́споди, да сотвори́ши ни досто́йни угото́ванния ізбра́нним Твої́м небе́сния сла́ви і да преобрази́ши ті́ло смире́нія на́шего, я́ко би́ти єму́ сообра́зну ті́лу Сла́ви Твоєя́ во о́бщеє всіх воскресе́ніє і в безконе́чнім Твоє́м Ца́рствії, є́же угото́вал єси́ от сложе́нія ми́ра лю́б'ящим Тя, в не́мже да сподо́биши і нас, я́ко Мойсе́я і Ілію́ на Фаво́рі лице́м к лицю́ лицезре́ти Тя і со всі́ми святи́ми воспіва́ти Тебі́ ві́чную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Преві́чний! Вся твори́ши на́шего ра́ди спасе́нія. Мене́ ра́ди восприя́л єси́ плоть пречи́стую от Пресвяти́я Ді́ви Марі́ї і в зра́ці раба́ прише́л єси́ в мир сей. Та́кожде і преобрази́лся єси́ на святі́й горі́, не Себі́ угожда́я, не тре́буєть бо Світ просвіще́нія, но нас ра́ди осужде́нних, да на́шу просвіти́ши тьму і нас, во тьмі сідя́щих і среди́ сі́ні сме́ртния, от сино́в гні́ва во возлю́бленния ча́да Твоя́ да преобрази́ши. Сего́ ра́ди благода́рственно вопіє́м Тебі́ такова́я:","Ісу́се, зрак ра́бій на Фаво́рі преобрази́вий, да нас із рабо́в гріха́ ча́да Бо́жия сотвори́ши;","Ісу́се, да́же до пло́ті Себі́ істощи́вий, да на́ше па́дшеє єстество́ с Собо́ю преобрази́ши.","Ісу́се, неізрече́нноє благолі́піє Ца́рства Твоєго́ на Фаво́рі яви́вий, ра́дость, мир і пра́вду о Ду́сі Свя́те в нас утверди́;","Ісу́се, Боже́ственним блиста́нієм пло́ті Твоєя́ всю твар обожи́вий, обоже́нієм пло́ті во Второ́м прише́ствії Твоє́м нас обнови́.","Ісу́се, огнь Божества́ Твоєго́ на Фаво́рі яви́вий, огне́м невеще́ственним гріхи́ моя́ попали́;","Ісу́се, сладча́йшею бесі́дою Твоє́ю та́мо ученики́ Своя́ напита́вий, Святи́ми Та́йнами Твої́ми гла́дную ду́шу мою́ освяти́.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє приношу́ Ті недосто́йний, Твоєго́ Преображе́нія соверша́я сві́тлоє торжество́ і вопію́ Тебі́: висоту́ небе́снаго житія́ і сла́ви присносу́щния Боже́ственноє сія́ніє да́руй ни́ні рабо́м Твої́м, се́рдцем же чи́стим сподо́би нас ми́сленно взи́ти на го́ру святу́ю Твою́, ви́діти разу́мними очеси́ пресла́вноє Преображе́ніє Твоє́, да сві́тло воспоє́м Тебі́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ Сий Непристу́пен і Сві́та Пода́тель, Ісу́се, Безнача́льний і Присносу́щний Сві́те, Світ Твой в мир прине́сл єси́, єгда́ с пречи́стою пло́тію Твоє́ю вшел єси́ на го́ру Фаво́рськую і та́мо Несозда́нний і Боже́ственний Світ яви́л єси́ ученико́м Твої́м, Сла́ви О́тчія показу́я о́браз. Сего́ Сві́та Твоєго́ преєсте́ственнаго прича́стники би́ти жела́юще, із глубини́ душі́ вопіє́м Тебі́ такова́я:","Ісу́се Христе́ Сві́те І́стинний, по́мисли до́брими ду́шу мою́ живи́ во вся дні земна́го стра́нствія моєго́;","Ісу́се Царю́, Сві́те Безнача́льний, уга́сший світи́льник душі́ моєя́ па́ки возжзи́ до дне сконча́нія моєго́.","Ісу́се, Сві́те ти́хий, живо́т дая́й, світ і живо́т низпосли́ душі́ моє́й в час ужа́сний сме́рти моєя́;","Ісу́се, Сві́те Святи́й, світя́й і горя́й, із огня́ неугаси́маго і тьми кромі́шния ісхи́ти м'я тогда́.","Ісу́се, Сладча́йший і Святі́йший Сві́те, к сві́ту небе́снаго черто́га Твоєго́ среди́ го́рких мита́рств возду́шних проведи́ м'я;","Ісу́се, со́лнця вся́каго Світлі́йшій Сві́те, во сві́тлостіх святи́х Твої́х в невече́рнім дні Ца́рствія Твоєго́ просвіти́ м'я.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 12","ps":["Благода́ть Твою́ пода́ждь мні, Ісу́се Бо́же мой, ю́же на Фаво́рі дарова́л єси́ ізбра́нним ученико́м Твої́м Петру́, Іоа́нну і Іа́кову, і прийми́ нас, я́коже о́них, да облече́ннії си́лою Твоє́ю сви́ше і Ду́хом Святи́м просвіще́ннії, се́рдце же чи́сто іму́щи і дух обновле́н, взи́дем на ми́сленний Фаво́р, восходя́ще от си́ли в си́лу, найпа́че же в пості́ і моли́тві подвиза́ющеся, в цілому́дрії же і в чистоті́ пребива́юще, і та́мо да воспоє́м Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пречи́стия Пло́ті Твоєя́ пресла́вноє Преображе́ніє, прославля́єм Боже́ственную Сла́ву Твою́ на Фаво́рі явле́нную, покланя́ємся присносу́щній Си́лі Твоє́й і Божеству́, Єго́же зарю́ ма́лую та́мо обнажи́л єси́, Христе́, і ві́руєм с Петро́м, я́ко Ти єси́ воі́стину Христо́с, Син Бо́га Жива́го, прише́дий в мир грі́шния спасти́, тім же і вопіє́м с ним із глубини́ душі́: добро́ нам зді би́ти с Тобо́ю. Сего́ ра́ди не посрами́ нас в Тя пра́во ві́рующих, оба́че немощни́х і пло́тію обложе́нних і покри́й нас Сві́том Богосія́нния Пло́ті Твоєя́, с любо́вію зову́щих Тебі́ си́це:","Ісу́се, Со́лнце Незаходи́моє, на Фаво́рі возше́дшеє. Твої́м Боже́ственним сія́нієм осія́й м'я;","Ісу́се, Сві́те несокрива́ємий в Преображе́нії явле́нний, Твоєя́ благода́ті причаще́нієм согрі́й м'я.","Ісу́се, Хра́мі Предві́чний Небе́снаго Ієрусали́ма, в ски́нію Бо́жию с челові́ки всели́ м'я;","Ісу́се, Цві́те Благово́нний Рая́ Всесвята́го, небе́сними арома́ти святи́ні і чистоти́ облагоуха́й м'я.","Ісу́се, Огню́ чисти́тельний, не́бо і зе́млю от вся́кия скве́рни очи́стити хотя́й, от скве́рни пло́ті і ду́ха очи́сти м'я;","Ісу́се, Ка́меню вседраги́й, Го́рній Сіо́н вмі́сто со́лнця красото́ю Боже́ственною освіща́ти імі́яй, от зрі́нія іни́я красоти́ па́че Тебе́ ізба́ви м'я.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 13","ps":["О Пресла́дкий і Всеще́дрий Ісу́се, на Фаво́рі Боже́ственною сла́вою просія́вий! Прийми́ ни́ні ма́лоє моле́ніє сіє́ на́ше, і я́коже прия́л єси́ от учени́к Твої́х на святі́й горі́ поклоне́ніє, та́ко і нас сподо́би пресла́вному Преображе́нію Твоєму́ поклони́тися, во сві́ті до́брих діл сія́юще, да просвіти́ться Тобо́ю тьма гріхо́вная в нас живу́щая, і да яви́мся досто́йни би́ти наслі́дники безконе́чнаго Ца́рствія Твоєго́ на небесі́, іді́же со всі́ми святи́ми сподо́би і нам воспіва́ти Тебі́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом недові́домоє і челові́ком непристу́пноє Твоє́, Світода́вче Христе́, Божество́, незаходи́тельними мо́лніями і луча́ми Невече́рняго Сві́та Твоєго́, яви́л єси́ на горі́ Фаво́рстій нача́льнійшим ученико́м Твої́м, ті́ї же Боже́ственним ізміни́шася у́жасом, о́блаком осія́вшеся сві́тлим і глас Оте́чь сли́шавше, разумі́ша Твоєго́ вочелові́ченія та́їнство, вопію́ще Тебі́ такова́я:","Ісу́се, Си́не Бо́жий Безсме́ртний, просвіти́ нас сві́том Лиця́ Твоєго́ осія́ннаго;","Ісу́се, Благи́й Бо́же Всеси́льний, возбуди́ нас спя́щих із глубини́ тьми сна гріхо́внаго.","Ісу́се, во сві́ті живи́й непристу́пнім, із о́бласти те́мния ізведи́ нас;","Ісу́се, Сла́вою Твоє́ю іспо́лнивий весь мир, во оби́телі ра́йськия введи́ нас.","Ісу́се, Сві́те ми́ра, от ми́ра лука́ваго свободи́ нас во тьмі сідя́щих;","Ісу́се, Со́лнце Пра́вди, си́лою і пра́вдою облеци́ нас, в сі́ні сме́ртній спя́щих.","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Царю́ сла́ви, Тебі́ небесі́ і землі́ Созда́теля, зря́щи на горі́ Фаво́рстій преобрази́вшася со сла́вою, вся твар удиви́ся, небеса́ вострепета́ша, і всі земноро́днії возра́довашася, ми же недосто́йнії Твоєму́ нас ра́ди Преображе́нію благода́рственно поклоне́ніє принося́ще, с Петро́м от душі́ вопіє́м Ті:","Ісу́се, Преві́чний Бо́же, добро́ нам всегда́ би́ти под кро́вом благода́ті Твоєя́."]},{"h":"Молитва","ps":["Го́споди Ісу́се Христе́, Бо́же наш, во Сві́ті живи́й непристу́пнім, Сія́ніє сий Сла́ви О́тчія і О́браз Іпоста́си Єго́! Єгда́ при́йде ісполне́ніє време́н, Ти за милосе́рдіє неізрече́нноє к па́дшему ро́ду челові́чеському Себі́ ума́лил єси́, зрак раба́ прия́л єси́, смири́л єси́ Себе́, послу́шлив бисть да́же до сме́рти. Оба́че пре́жде Креста́ і во́льния стра́сті Твоєя́ на горі́ Фаво́рстій преобрази́лся єси́ в Боже́ственній Сла́ві Своє́й пред святи́ми Твої́ми ученики́ і Апо́столи, ма́ло скрив пло́ті восприя́тіє, да єгда́ Тя у́зрять распина́єма, і сме́рті предава́єма, уразумі́ють у́бо страда́ніє Твоє́ во́льноє і Божество́. Да́руй же і нам всім, пречи́стия Пло́ті Твоєя́ Преображе́ніє пра́зднующим, чи́стим се́рдцем і нескве́рними уми́ взи́ти на Святу́ю го́ру Твою́, в селе́нія святи́я сла́ви Твоєя́, іді́же глас чист пра́зднующих, глас несказа́ннаго ра́дованія, да та́мо ку́пно с ни́ми лице́м к лицю́ у́зрим Сла́ву Твою́ в невече́рнім дні Ца́рствія Твоєго́, і со всі́ми святи́ми, от ві́ка Тебі́ благоугоди́вшими просла́вим Всесвято́є і́м'я Твоє́ со Безнача́льним Твої́м Отце́м і Пресвяти́м і Благи́м і Животворя́щим Твої́м Ду́хом ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 7","ps":["Преобрази́лся єси́ на горі́, Христе́ Бо́же, / показа́вий ученико́м Твої́м сла́ву Твою́, / я́коже можа́ху, / да возсія́єть і нам, грі́шним, / світ Твой присносу́щний / моли́твами Богоро́диці, // Світода́вче, сла́ва Тебі́."]},{"h":"Кондак, глас 7","ps":["На горі́ преобрази́лся єси́, / і я́коже вміща́ху ученици́ Твої́, / сла́ву Твою́, Христе́ Бо́же, ви́діша, / да єгда́ Тя у́зрять распина́єма, / страда́ніє у́бо уразумі́ють во́льноє, / ми́рове же пропові́дять, // я́ко Ти єси́ воі́стину О́тчеє сія́ніє."]},{"h":"Величання","ps":["Велича́єм Тя, / Жизнода́вче Христе́, / і почита́єм пречи́стия пло́ті Твоєя́ // пресла́вноє преображе́ніє."]},{"h":"Задостойник","ps":["Велича́й, душе́ моя́, / на Фаво́рі преобрази́вшагося Го́спода.","Рождество́ Твоє́ нетлі́нно яви́ся: / Бог із боку́ Твоє́ю про́йде, / я́ко Плотоно́сець яви́ся на землі́ / і с челові́ки поживе́. // Тя, Богоро́дице, тім всі велича́єм."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці (Великий акафіст, що читається в Суботу Акафіста)","e":"Akathist to the Most Holy Theotokos (the Great Akathist, read on the Saturday of the Akathist)","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді побіди́тельная, я́ко ізба́вльшеся от злих, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице; но я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Ікос 1","ps":["А́нгел предста́тель с Небесе́ по́слан бисть рещи́ Богоро́дице: ра́дуйся, і со безпло́тним гла́сом воплоща́єма Тя зря, Го́споди, ужаса́шеся і стоя́ше, зови́й к Ней такова́я:","Ра́дуйся, Є́юже ра́дость возсія́єть;","ра́дуйся, Є́юже кля́тва ісче́знеть.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє;","ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, висото́ неудобовосходи́мая челові́чеськими по́мисли;","ра́дуйся, глубино́ неудобозри́мая і а́нгельськима очи́ма.","Ра́дуйся, я́ко єси́ Царе́во сіда́лище;","ра́дуйся, я́ко но́сиши Нося́щаго вся.","Ра́дуйся, Звіздо́, явля́ющая Со́лнце;","ра́дуйся, утро́бо Боже́ственнаго воплоще́нія.","Ра́дуйся, Є́юже обновля́ється твар;","ра́дуйся, Є́юже покланя́ємся Творцю́.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 2","ps":["Ви́дящи Свята́я Себе́ в чистоті́, глаго́леть Гавриї́лу де́рзостно: пресла́вноє твоєго́ гла́са неудобоприя́тельно душі́ Моє́й явля́ється: безсі́меннаго бо зача́тія рождество́ ка́ко глаго́леши, зови́й: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий разумі́ти Ді́ва і́щущи, возопи́ к служа́щему: із боку́ чи́сту, Си́ну ка́ко єсть роди́тися мо́щно, рци Мі? К Не́йже он рече́ со стра́хом, оба́че зови́й си́це:","Ра́дуйся, сові́та неізрече́ннаго Таї́ннице;","ра́дуйся, молча́нія прося́щих ві́ро.","Ра́дуйся, чуде́с Христо́вих нача́ло;","ра́дуйся, велі́ній Єго́ глави́зно.","Ра́дуйся, лі́ствице небе́сная, Є́юже сни́де Бог;","ра́дуйся, мо́сте, преводя́й су́щих от землі́ на не́бо.","Ра́дуйся, А́нгелов многослову́щеє чу́до;","ра́дуйся, бісо́в многоплаче́вноє пораже́ніє.","Ра́дуйся, Світ неізрече́нно роди́вшая;","ра́дуйся, є́же ка́ко, ні єди́наго же научи́вшая.","Ра́дуйся, прему́дрих превосходя́щая ра́зум;","ра́дуйся, ві́рних озаря́ющая сми́сли.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ тогда́ к зача́тію Браконеіску́сную, і благопло́дная Тоя́ ложесна́, я́ко село́ показа́ сла́дкоє, всім хотя́щим жа́ти спасе́ніє, внегда́ пі́ти си́це: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи Богоприя́тную Ді́ва утро́бу, востече́ ко Єлисаве́ті: младе́нець же о́ноя а́біє позна́в Сея́ цілова́ніє, ра́довашеся, і ігра́ньми я́ко пі́сньми вопія́ше к Богоро́диці:","Ра́дуйся, о́траслі неув'яда́ємия розго́;","ра́дуйся, Плода́ безсме́ртнаго стяжа́ніє.","Ра́дуйся, Ді́лателя ді́лающая Человіколю́бця;","ра́дуйся, Сади́теля жи́зні на́шея ро́ждшая.","Ра́дуйся, ни́во, растя́щая гобзова́ніє щедро́т;","ра́дуйся, трапе́зо, нося́щая оби́ліє очище́нія.","Ра́дуйся, я́ко рай пи́щний процвіта́єши;","ра́дуйся, я́ко приста́нище душа́м гото́виши.","Ра́дуйся, прия́тноє моли́тви кади́ло;","ра́дуйся, всего́ ми́ра очище́ніє.","Ра́дуйся, Бо́жиє к сме́ртним благоволе́ніє;","ра́дуйся, сме́ртних к Бо́гу дерзнове́ніє.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній сумни́тельних, цілому́дренний Іо́сиф см'яте́ся, к Тебі́ зря небра́чній, і бракоокра́дованную помишля́я, Непоро́чная; уві́дів же Твоє́ зача́тіє от Ду́ха Свя́та, рече́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша па́стиріє А́нгелов пою́щих плотсько́є Христо́во прише́ствіє, і те́кше я́ко к Па́стирю ви́дять Сего́ я́ко а́гнця непоро́чна, во чре́ві Марі́їні упа́сшася, Ю́же пою́ще рі́ша:","Ра́дуйся, А́гнця і Па́стиря Ма́ти;","ра́дуйся, дво́ре слове́сних ове́ць.","Ра́дуйся, неви́димих враго́в муче́ніє;","ра́дуйся, ра́йських две́рей отверзе́ніє.","Ра́дуйся, я́ко небе́сная сра́дуються земни́м;","ра́дуйся, я́ко земна́я сликовству́ють небе́сним.","Ра́дуйся, апо́столов немо́лчная уста́;","ра́дуйся, страстоте́рпцев непобіди́мая де́рзосте.","Ра́дуйся, тве́рдоє ві́ри утвержде́ніє;","ра́дуйся, сві́тлоє благода́ті позна́ніє.","Ра́дуйся, Є́юже обнажи́ся ад;","ра́дуйся, Є́юже облеко́хомся сла́вою.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ узрі́вше волсви́, тоя́ послі́доваша зарі́, і я́ко світи́льник держа́ще ю, то́ю іспита́ху крі́пкаго Царя́, і дости́гше Непостижи́маго, возра́довашася, Єму́ вопію́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша о́троци халде́йстії на руку́ Діви́чу Созда́вшаго рука́ми челові́ки, і Влади́ку разуміва́юще Єго́, а́ще і ра́бій прия́т зрак, потща́шася дарми́ послужи́ти Єму́, і возопи́ти Благослове́нній:","Ра́дуйся, Звізди́ незаходи́мия Ма́ти;","ра́дуйся, заре́ та́їнственнаго дне.","Ра́дуйся, пре́лести пещ угаси́вшая;","ра́дуйся, Тро́йці таї́нники просвіща́ющая.","Ра́дуйся, мучи́теля безчелові́чнаго ізмета́ющая от нача́льства;","ра́дуйся, Го́спода Человіколю́бця показа́вшая Христа́.","Ра́дуйся, ва́рварськаго ізбавля́ющая служе́нія;","ра́дуйся, тимі́нія ізима́ющая діл.","Ра́дуйся, огня́ поклоне́ніє угаси́вшая;","ра́дуйся, пла́мене страсте́й ізміня́ющая.","Ра́дуйся, ві́рних наста́внице цілому́дрія;","ра́дуйся, всіх родо́во весе́ліє.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 6","ps":["Пропові́дници богоно́снії, би́вше волсви́, возврати́шася во Вавило́н, сконча́вше Твоє́ проро́чество, і пропові́давше Тя Христа́ всім, оста́виша І́рода я́ко буєсло́вна, не ві́дуща пі́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вий во Єги́пті просвіще́ніє і́стини, отгна́л єси́ лжі тьму: і́доли бо єго́, Спа́се, не терп'я́ще Твоєя́ крі́пости, падо́ша, сих же ізба́вльшіїся вопія́ху к Богоро́диці:","Ра́дуйся, ісправле́ніє челові́ков;","ра́дуйся, низпаде́ніє бісо́в.","Ра́дуйся, пре́лести держа́ву попра́вшая;","ра́дуйся, і́дольськую лесть обличи́вшая.","Ра́дуйся, мо́ре, потопи́вшеє фарао́на ми́сленнаго;","ра́дуйся, ка́меню, напої́вший жа́ждущия жи́зні.","Ра́дуйся, о́гненний сто́лпе, наставля́яй су́щия во тьмі;","ра́дуйся, покро́ве ми́ру, ши́рший о́блака.","Ра́дуйся, пи́ще, ма́нни приє́мнице;","ра́дуйся, сла́дости святи́я служи́тельнице.","Ра́дуйся, земле́ обітова́нія;","ра́дуйся, із нея́же тече́ть мед і млеко́.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 7","ps":["Хотя́щу Симео́ну от ни́нішняго ві́ка преста́витися преле́стнаго, вда́лся єси́ я́ко младе́нець тому́, но позна́лся єси́ єму́ і Бог соверше́нний. Ті́мже удиви́ся Твоє́й неізрече́нній прему́дрості, зови́й: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ твар, я́влься Зижди́тель нам от Него́ би́вшим, із безсі́менния прозя́б утро́би, і сохрани́в Ю, я́коже бі, нетлі́нну, да чу́до ви́дяще, воспої́м Ю, вопію́ще:","Ра́дуйся, цві́те нетлі́нія;","ра́дуйся, ві́нче воздержа́нія.","Ра́дуйся, воскресе́нія о́браз облиста́ющая;","ра́дуйся, а́нгельськоє житіє́ явля́ющая.","Ра́дуйся, дре́во світлоплодови́тоє, от него́же пита́ються ві́рнії;","ра́дуйся, дре́во благосінноли́ственноє, і́мже покрива́ються мно́зі.","Ра́дуйся, во чре́ві нося́щая Ізба́вителя пліне́нним;","ра́дуйся, ро́ждшая Наста́вника заблу́ждшим.","Ра́дуйся, Судії́ пра́веднаго умоле́ніє;","ра́дуйся, мно́гих согріше́ній проще́ніє.","Ра́дуйся, оде́ждо наги́х дерзнове́нія;","ра́дуйся, люби́, вся́коє жела́ніє побіжда́ющая.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 8","ps":["Стра́нноє рождество́ ви́дівше, устрані́мся ми́ра, ум на небеса́ прело́жше: сего́ бо ра́ди висо́кий Бог на землі́ яви́ся смире́нний челові́к, хотя́й привлещи́ к висоті́ Тому́ вопію́щия: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бі в ни́жніх і ви́шніх ніка́коже отступи́ неопи́санноє Сло́во: снизхожде́ніє бо Боже́ственноє, не прехожде́ніє же мі́стноє бисть, і рождество́ от Ді́ви Богоприя́тния, сли́шащия сія́:","Ра́дуйся, Бо́га невмісти́маго вмісти́лище;","ра́дуйся, честна́го та́їнства две́рі.","Ра́дуйся, неві́рних сумни́тельноє сли́шаніє;","ра́дуйся, ві́рних ізві́стная похвало́.","Ра́дуйся, колесни́це пресвята́я Су́щаго на Херуви́міх;","ра́дуйся, селе́ніє пресла́вноє Су́щаго на Серафи́міх.","Ра́дуйся, проти́вная в то́жде собра́вшая;","ра́дуйся, ді́вство і рождество́ сочета́вшая.","Ра́дуйся, Є́юже разріши́ся преступле́ніє;","ра́дуйся, Є́юже отве́рзеся рай.","Ра́дуйся, ключу́ Ца́рствія Христо́ва;","ра́дуйся, наде́ждо благ ві́чних.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся вели́кому Твоєго́ вочелові́ченія ді́лу; непристу́пнаго бо я́ко Бо́га, зря́ше всім присту́пнаго Челові́ка, нам у́бо спребива́юща, сли́шаща же от всіх: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния, я́ко ри́би безгла́сния ви́дим о Тебі́, Богоро́дице, недоуміва́ють бо глаго́лати, є́же ка́ко і Ді́ва пребива́єши, і роди́ти возмогла́ єси́. Ми же, та́їнству див'я́щеся, ві́рно вопіє́м:","Ра́дуйся, прему́дрости Бо́жия прия́телище,","ра́дуйся, промишле́нія Єго́ сокро́вище.","Ра́дуйся, любому́дрия нему́дрия явля́ющая;","ра́дуйся, хитрослове́сния безслове́сния облича́ющая.","Ра́дуйся, я́ко обуя́ша лю́тії взиска́теле;","ра́дуйся, я́ко ув'ядо́ша баснотво́рці.","Ра́дуйся, афіне́йськая плете́нія растерза́ющая;","ра́дуйся, ри́барськія мре́жі ісполня́ющая.","Ра́дуйся, із глубини́ неві́дінія ізвлача́ющая;","ра́дуйся, мно́гі в ра́зумі просвіща́ющая.","Ра́дуйся, кораблю́ хотя́щих спасти́ся;","ра́дуйся, приста́нище жите́йських пла́ваній.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, І́же всіх Украси́тель, к сему́ самообітова́н при́йде, і Па́стир сий, я́ко Бог, нас ра́ди яви́ся по нам челові́к: подо́бним бо подо́бноє призва́в, я́ко Бог сли́шить: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Богоро́дице Ді́во, і всім к Тебі́ прибега́ющим: і́бо небесе́ і землі́ Творе́ць устро́ї Тя, Пречи́стая, все́лься во утро́бі Твоє́й, і вся приглаша́ти Тебі́ научи́в:","Ра́дуйся, сто́лпе ді́вства;","ра́дуйся, двер спасе́нія.","Ра́дуйся, нача́льнице ми́сленнаго назда́нія;","ра́дуйся, пода́тельнице Боже́ственния бла́гости.","Ра́дуйся, Ти бо обнови́ла єси́ зача́тия сту́дно;","ра́дуйся, Ти бо наказа́ла єси́ окра́денния умо́м.","Ра́дуйся, тли́теля сми́слов упражня́ющая;","ра́дуйся, Сі́ятеля чистоти́ ро́ждшая.","Ра́дуйся, черто́же безсі́меннаго уневі́щенія;","ра́дуйся, ві́рних Го́сподеві сочета́вшая.","Ра́дуйся, до́брая младопита́тельнице ді́вам;","ра́дуйся, невістокраси́тельнице душ святи́х.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє побіжда́ється, спростре́тися тща́щеєся ко мно́жеству мно́гих щедро́т Твої́х: равночи́сленния бо піска́ пі́сні а́ще прино́сим Ті, Царю́ Святи́й, нічто́же соверша́єм досто́йно, я́же дал єси́ нам, Тебе́ вопію́щим: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́, су́щим во тьмі я́вльшуюся, зрим Святу́ю Ді́ву, невеще́ственний бо вжига́ющи огнь, наставля́єть к ра́зуму Боже́ственному вся, заре́ю ум просвіща́ющая, зва́нієм же почита́ємая, си́ми:","Ра́дуйся, луче́ у́мнаго Со́лнця;","ра́дуйся, світи́ло незаходи́маго Сві́та.","Ра́дуйся, мо́лніє, ду́ші просвіща́ющая;","ра́дуйся, я́ко гром враги́ устраша́ющая.","Ра́дуйся, я́ко многосві́тлоє возсіява́єши просвіще́ніє;","ра́дуйся, я́ко многотеку́щую істоча́єши ріку́.","Ра́дуйся, купі́лі живопису́ющая о́браз;","ра́дуйся, гріхо́вную от'є́млющая скве́рну.","Ра́дуйся, ба́не, омива́ющая со́вість;","ра́дуйся, ча́ше, че́рплющая ра́дость.","Ра́дуйся, обоня́ніє Христо́ва благоуха́нія;","ра́дуйся, животе́ та́йнаго весе́лія.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 12","ps":["Благода́ть да́ти восхоті́в, долго́в дре́вніх, всіх долго́в Ріши́тель челові́ком, при́йде Собо́ю ко отше́дшим Того́ благода́ті, і раздра́в рукописа́ніє, сли́шить от всіх си́це: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ Рождество́, хва́лим Тя всі, я́ко одушевле́нний храм, Богоро́дице: во Твоє́й бо всели́вся утро́бі содержа́й вся руко́ю Госпо́дь, освяти́, просла́ви і научи́ вопи́ти Тебі́ всіх:","Ра́дуйся, селе́ніє Бо́га і Сло́ва;","ра́дуйся, свята́я святи́х бо́льшая.","Ра́дуйся, ковче́же, позлаще́нний Ду́хом;","ра́дуйся, сокро́вище живота́ неістощи́моє.","Ра́дуйся, честни́й ві́нче люде́й благочести́вих;","ра́дуйся, честна́я похвало́ ієре́єв благогові́йних.","Ра́дуйся, це́ркве непоколеби́мий сто́лпе;","ра́дуйся, Ца́рствія неруши́мая стіно́.","Ра́дуйся, Є́юже воздви́жуться побі́ди;","ра́дуйся, Є́юже низпа́дають вразі́.","Ра́дуйся, ті́ла моєго́ врачева́ніє;","ра́дуйся, душі́ моєя́ спасе́ніє.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти, ро́ждшая всіх святи́х Святі́йшеє Сло́во! Ни́нішнєє приє́мши приноше́ніє, от вся́кия ізба́ви напа́сти всіх, і бу́дущия ізми́ му́ки, о Тебі́ вопію́щих: Аллилу́я, аллилу́я, аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель с Небесе́ по́слан бисть рещи́ Богоро́дице: ра́дуйся, і со безпло́тним гла́сом воплоща́єма Тя зря, Го́споди, ужаса́шеся і стоя́ше, зови́й к Ней такова́я:","Ра́дуйся, Є́юже ра́дость возсія́єть;","ра́дуйся, Є́юже кля́тва ісче́знеть.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє;","ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, висото́ неудобовосходи́мая челові́чеськими по́мисли;","ра́дуйся, глубино́ неудобозри́мая і а́нгельськима очи́ма.","Ра́дуйся, я́ко єси́ Царе́во сіда́лище;","ра́дуйся, я́ко но́сиши Нося́щаго вся.","Ра́дуйся, Звіздо́, явля́ющая Со́лнце;","ра́дуйся, утро́бо Боже́ственнаго воплоще́нія.","Ра́дуйся, Є́юже обновля́ється твар;","ра́дуйся, Є́юже покланя́ємся Творцю́.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді побіди́тельная, я́ко ізба́вльшеся от злих, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице; но я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Молитва","ps":["Пресвята́я Влади́чице моя́ Богоро́дице, святи́ми Твої́ми і всеси́льними мольба́ми, отжени́ от мене́, смире́ннаго і окая́ннаго раба́ твоєго́, уни́ніє, забве́ніє, неразу́міє, нераді́ніє, і вся скве́рная, лука́вая і ху́льная помишле́нія от окая́ннаго моєго́ се́рдця ї от помраче́ннаго ума́ моєго́, і погаси́ пла́мень страсте́й мої́х, я́ко нищ єсьм і окая́нен: і ізба́ви м'я от мно́гих ї лю́тих воспомина́ній і предприя́тій, і от всіх дійств злих свободи́ м'я: я́ко благослове́нна єси́ от всіх родо́в, і сла́виться Пречестно́є і́м'я Твоє́ во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О, Пресвята́я Госпоже́ Влади́чице Богоро́дице, ви́шши єси́ всіх А́нгел і Арха́нгел, і всея́ тва́рі честні́йши, помо́щнице єси́ оби́димих, ненаді́ющихся наді́яніє, убо́гих засту́пнице, печа́льних утіше́ніє, а́лчущих корми́тельнице, наги́х одія́ніє, больни́х ісціле́ніє, грі́шних спасе́ніє, христия́н всіх поможе́ніє і заступле́ніє. О, Всеми́лостивая Госпоже́, Ді́во Богоро́дице Влади́чице, ми́лостію Твоє́ю спаси́ і поми́луй святі́йшия патріа́рхи правосла́вния, преосвяще́нния митрополи́ти, архієпи́скопи і єпи́скопи і весь свяще́нничеський і і́ночеський чин, і вся правосла́вния христия́ни ри́зою Твоє́ю честно́ю защити́; і умоли́, Госпоже́, із Тебе́ без сі́мене воплоти́вшагося Христа́ Бо́га на́шего, да препоя́шеть нас си́лою Своє́ю сви́ше, на неви́димия і ви́димия враги́ на́ша. О, Всеми́лостивая Госпоже́ Влади́чице Богоро́дице! Воздви́гни нас із глубини́ гріхо́вния і ізба́ви нас от гла́да, губи́тельства, от тру́са і пото́па, от огня́ і меча́, от нахожде́нія іноплеме́нних і междоусо́бния бра́ні, і от напра́сния сме́рти, і от нападе́нія вра́жия, і от тлітво́рних вітр, і от смертоно́сния я́зви, і от вся́каго зла. Пода́ждь, Госпоже́, мир і здра́віє рабо́м Твої́м, всім правосла́вним христия́ном, і просвіти́ їм ум, і о́чі серде́чнії, є́же ко спасе́нію; і сподо́би ни, грі́шния раби́ Твоя́, Ца́рствія Си́на Твоєго́, Христа́ Бо́га на́шего; я́ко держа́ва Єго́ благослове́нна і препросла́влена, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О, Пресвята́я Ді́во Ма́ти Го́спода, Цари́це Небесе́ і землі́! Воньми́ многоболі́зненному воздиха́нію душ на́ших, при́зри с висоти́ святи́я Твоєя́ на нас, с ві́рою і любо́вію покланя́ющихся пречи́стому о́бразу Твоєму́. Се бо гріхми́ погружа́ємії і скорбми́ обурева́ємії, взира́юще на Твой о́браз, я́ко живі́й Ті су́щей с на́ми, прино́сим смире́нния моле́нія на́ша. Не і́мами бо ні іни́я по́мощі, ні іна́го предста́тельства, ні утіше́нія, то́кмо Тебі́, о, Ма́ти всіх скорб'я́щих і обремене́нних. Помози́ нам немощни́м, утоли́ скорб на́шу, наста́ви на путь пра́вий нас, заблужда́ющих, уврачу́й і спаси́ безнаде́жних, да́руй нам про́чеє вре́м'я живота́ на́шего в ми́рі і тишині́ проводи́ти, пода́ждь христия́нськую кончи́ну, і на стра́шнім суді́ Си́на Твоєго́ яви́ся нам милосе́рдая Засту́пниця, да всегда́ поє́м, велича́єм і сла́вим Тя, я́ко благу́ю Засту́пницю ро́да христия́нськаго, со всі́ми угоди́вшими Бо́гу. Амі́нь."]}],"notes":[]},{"u":"Акафіст Пресвятій і Животворящій Тройці","e":"Akathist to the Most Holy and Life-giving Trinity","secs":[{"h":"Кондак 1","ps":["Предві́чний Царю́ віко́в і Го́споди, всея́ тва́рі ви́димия і неви́димия Соді́телю, Єму́же, в Тро́йці Святі́й сла́вимому Бо́гу, вся́ко колі́но покланя́ється небе́сних, земни́х і преіспо́дніх: ті́мже і ми, я́ко креще́ннії в Трисвято́є і́м'я Твоє́, а́ще і недосто́йнії, хвале́бноє сіє́ дерза́єм принести́ Тебі́ пі́ніє: Ти же, я́ко Творе́ць, Промисли́тель і Судія́ наш, воньми́ гла́су раб Твої́х, і не отста́ви ми́лости Твоєя́ от нас, да із глубини́ душі́ ви́ну зове́м Ті:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели, Нача́ла і Вла́сті, Престо́ли і Госпо́дствія, предстоя́ще самому́ Престо́лу Сла́ви Твоєя́, не довлі́ють ізрещи́ вели́чія соверше́нств Твої́х: многоочи́тії же Херуви́ми і шестокрила́тії Серафи́ми, закрива́юще ли́ця своя́, то́чію с тре́петом і любо́вію взива́ють друг ко дру́гу: Свят, Свят, Свят Госпо́дь Савао́ф! Нам у́бо, і́же прах і пе́пел єсьми́, кольми́ па́че удо́біє люби́ти молча́ніє: но, да не толи́ких щедро́т, в созда́нії і іскупле́нії на нас ізлія́нних, непа́м'ятливи яви́мся і неблагода́рни, подража́юще го́рнему славосло́вію, с ві́рою і любо́вію взива́єм:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, неісповіди́мая соверше́нств Висото́ і неізслі́димая та́їн Пучи́но!","Свят єси́ Го́споди Бо́же наш, везді́ сий і вся ісполня́яй, Єди́ний і То́йжде вчера́, днесь і во ві́ки!","Свят єси́ Го́споди Бо́же наш, вся моги́й, нариця́яй не су́щая я́ко су́щая, низводя́й да́же до а́да і па́ки возводя́й!","Свят єси́ Го́споди Бо́же наш, іспиту́яй сердця́ і утро́би челові́чеськія, ісчита́яй зві́зди і всім їм імена́ нариця́яй!","Свят єси́ Го́споди Бо́же наш, Єго́же всі путіє́ і́стинни і все судьби́ оправда́ни вку́пі і вожделі́нни!","Свят єси́ Го́споди Бо́же наш, отдая́ гріхи́ отце́в на ча́да, ми́луяй же і награжда́яй в ро́ди родо́в!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 2","ps":["Ви́дів Тя Іса́я на Престо́лі висо́ці і превознесе́нні, глаго́лаше: о окая́нний аз, я́ко челові́к сий і нечи́сти устні́ іми́й, і Го́спода Савао́фа ви́діх очи́ма мої́ма! Єгда́ же угль горя́щий, носи́мий от А́нгела, прикосну́ся усто́м єго́, чи́сті восхваля́ше Тебе́ Отця́, і Си́на, і Свята́го Ду́ха, Єди́наго Бо́га. Попали́ у́бо, о Пресвята́я Тро́йце, огне́м Божества́ Твоєго́ те́рніє і на́ших мно́гих беззако́ній, да чи́стим се́рдцем возопіє́м Тебі́: Аллилу́я!"]},{"h":"Ікос 2","ps":["Ра́зум неуразумі́нний разумі́ти іща́ вели́кий во проро́ціх Мойсе́й, глаго́лаше: яви́ мні лице́ Твоє́, да разу́мно ви́жду Тя! Ти же к нему́: за́дняя Моя́ у́зриши, лице́ же Моє́ не яви́ться тебі́: не бо у́зрить челові́к лице́ Моє́ і жив бу́деть. Нам же, а́ще і недосто́йним, благоволи́л єси́ яви́ти Себі́ в лиці́ Єдиноро́днаго Си́на Твоєго́: ті́мже благода́рні вопіє́м:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, Серафи́мов пламенногоря́щая люби́ і Херуви́мов ви́ну світя́щая прему́дросте!","Свят єси́ Го́споди Бо́же наш, Небе́сних Престо́лов преви́шній Царю́ і преми́рних Госпо́дствій всеї́стинний Го́споди!","Свят єси́ Го́споди Бо́же наш, Ви́шніх Сил непобіди́мая Крі́посте і Го́рніх Власте́й всемогу́щий Власти́телю!","Свят єси́ Го́споди Бо́же наш, Арха́нгелов всера́достноє благові́стіє і А́нгелов неумолка́ющая про́повідь!","Свят єси́ Го́споди Бо́же наш, разу́мних Нача́л верхо́вноє Всенача́ло, і всіх про́чих небе́сних чино́в держа́вний повели́телю;","Свят єси́ Го́споди Бо́же наш, Єди́н імі́яй безсме́ртіє і живи́й во Сві́ті Непристу́пнім, со ізбра́нними же Твої́ми, я́ко со дру́ги, лице́м к лицю́ бесі́дуяй!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 3","ps":["Си́лою неізрече́ннаго могу́щества Твоєго́ вся содержи́ши, Сло́вом неізслі́димия Прему́дрости Твоєя́ вся стро́їши, Ду́хом уст Твої́х вся живи́ши і ра́дуєши, о Трисо́лнечне Вседі́телю! Ізмі́рил єси́ не́бо дла́нію і зе́млю п'я́дію, но́сиши і пита́єши всю твар, вся по і́мені призива́єши, і ність моги́й утаї́тися власти́тельния десни́ці і взо́ра Твоєго́: сего́ ра́ди со всі́ми ви́шніми і ни́жніми си́лами, со умиле́нієм припа́дающе, зове́м Ті: Аллилу́я!"]},{"h":"Ікос 3","ps":["Імі́яй вся́коє созда́ніє рабо́тно повелі́нію Твоєму́, всю́ду явля́єши сліди́ Про́мисла і неізче́тних соверше́нств Твої́х: ті́мже неви́димая Твоя́ і присносу́щную Си́лу і Божество́, творе́ньми помишля́єма, ви́дяще, со удивле́нієм і ра́достію зове́м:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, власти́тельний Соді́телю ви́димих і неви́димих, і любвеоби́льний Строї́телю настоя́щих і гряду́щих!","Свят єси́ Го́споди Бо́же наш, от чети́ріх стихі́й соста́вивий твар і чети́рми времені́ круг лі́та вінча́вий!","Свят єси́ Го́споди Бо́же наш, повелі́вий со́лнцю світи́ти во дні, і луні́ со зві́здами просвіща́ти нощ!","Свят єси́ Го́споди Бо́же наш, ізводя́й ві́три от сокро́вищ, одіва́яй не́бо о́блаки, і посила́яй дождь і ро́су в прохлажде́ніє зно́я!","Свят єси́ Го́споди Бо́же наш, препоясу́яй хо́лми ра́достію і до́ли весе́лієм, украша́яй кри́ни се́льния і вінча́яй поля́ кла́сами!","Свят єси́ Го́споди Бо́же наш, посила́яй пи́щу птенце́м вра́новим, напая́яй вся зві́ри се́льния, і полага́яй щедро́ти Своя́ на всіх ді́ліх Свої́х!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я душепа́губния є́ресі, втори́й Іу́да, А́рій безу́мний, отве́ржеся Тебі́ Си́на Бо́жия, Єди́наго от Пребоже́ственния Тро́йці би́ти; ми же а́ще і і́но лице́ О́тчеє, і́но Сино́внєє, і́но Свята́го Ду́ха глаго́лем: но О́тчеє, Сино́внєє і Свята́го Ду́ха Єди́но Божество́, ра́вну си́лу, соприсносу́щно вели́чество, се́рдцем і устни́ іспові́дуєм, і я́ко Трисо́лнечним сві́том в купі́лі креще́нія озаре́ннії, Отцю́, і Си́ну, і Свято́му Ду́ху, Єди́ному Бо́гу покланя́ємся, зову́ще: Аллилу́я!"]},{"h":"Ікос 4","ps":["Сли́шавше па́стиріє і учи́теліє Святи́я Це́ркви А́рія, я́ко лю́таго зві́ря, вто́ргшася в слове́сноє Христо́во ста́до, і восхища́юща о́вці от і́стиннаго іспові́данія правосла́вния ві́ри, соше́дшеся в Нике́ї на собо́рі, Бо́га, а не твар, Христа́ іспові́даша, і ра́вна Отцю́ Си́на і Свята́го Ду́ха чту́ще, громогла́сне возгласи́ша:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, Бо́же О́тче, Бо́же Си́не, Бо́же Ду́ше Святи́й, Єди́ний І́стинний Бо́же, а не три бо́зі!","Свят єси́ Го́споди Бо́же наш, несозда́нний О́тче, несозда́нний Си́не, несозда́нний Ду́ше Святи́й, Єди́не вку́пі несозда́нне, а не три осо́б несозда́нни!","Свят єси́ Го́споди Бо́же наш, Оте́ць ражда́яй предві́чно Си́на, Син ражда́ємий безлі́тно от Отця́, Дух Святи́й із Него́ же от вік проісходя́й, но не ражда́яся!","Свят єси́ Го́споди Бо́же наш, Оте́ць, воззва́вий нас от небитія́, Син, іскупи́вий нас па́дших Кресто́м Свої́м, Дух Святи́й, освяща́яй і животворя́й всіх Своє́ю благода́тію!","Свят єси́ Го́споди Бо́же наш, в ду́хі, душе́ і ті́лі на́шем трехча́стную ски́нію на вселе́ніє Своє́ основа́ти благоволи́вий, і всеконе́чні гріхо́м разру́шитися єй в нас не попусти́вий!","Свят єси́ Го́споди Бо́же наш, зна́меніє Триіпоста́снаго Существа́ Своєго́ на всіх ді́ліх рук Свої́х, в ми́рі ви́димом і неви́димом, положи́вий!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 5","ps":["Пребезнача́льная і Вседі́тельная Тро́йце, созда́в нас по о́бразу і по подо́бію Твоєму́, запові́дала єси́ твори́ти уго́дная пред Тобо́ю: ми же, окая́ннії, злу́ю во́лю на́шу возлюби́вше, обі́ти креще́нія отверго́хом, о́браз Твой помрачи́хом; ни́ні же па́ки к Тебі́ прибіга́єм і мо́лимся, пода́ждь нам благода́ть Твою́, ісхи́ти нас із руки́ враг, ви́димих і неви́димих, і спаси́ ни, і́миже ві́си судьба́ми, да во ві́ки віко́в зове́м Тебі́: Аллилу́я!"]},{"h":"Ікос 5","ps":["Ви́дя ра́зум превосходя́щая соверше́нства Твоя́ і неізрече́нная благодія́нія к бі́дним сина́м Ада́млим (в Тя бо, Трієди́наго Бо́га і́стинно ві́руяй, ме́ртвий ду́хом оживля́ється, оскверне́нний со́вістію очища́ється, поги́бший спаса́ється), благода́рним умо́м, благода́рним се́рдцем, благода́рними усти́, от Тебе́ созда́нними, прекло́ньше колі́на, глаго́лем:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, в Тріїпоста́сном Сові́ті Твоє́м положи́вий сотвори́ти челові́ка, і в ті́ло єго́, от пе́рсти взя́тоє, диха́ніє жи́зней із уст Твої́х вдохну́вий!","Свят єси́ Го́споди Бо́же наш, о́бразом і подо́бієм Твої́м в лиці́ Ада́ма всіх нас почти́й, і рая́ сла́дости наслі́дники учини́вий!","Свят єси́ Го́споди Бо́же наш, ра́зумом преви́ше всего́ ви́димаго вознеси́й нас, і твар всю до́льнюю под но́зі на́ші покори́вий!","Свят єси́ Го́споди Бо́же наш, дре́во жи́зні в пи́щу нам дарова́вий і да́ром безсме́ртія ни обогати́вий!","Свят єси́ Го́споди Бо́же наш, преслу́шавших за́повідь прароди́телей на́ших і по гріхопаде́нії не оста́вивий, но на упова́нії спасе́нія пря́мо Еде́ма всели́вий!","Свят єси́ Го́споди Бо́же наш, ізведи́й і нас із чре́ва ма́тере на́шея і благода́тію Єва́нгелія, по рожде́нії, освяти́вий!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 6","ps":["Пропові́дник пра́вди і ревни́тель Свята́го і́мені Твоєго́, Ілія́ досточу́дний, воззва́н от А́нгела, ста в горі́ Хори́ві: бисть же дух крі́пок, низлага́яй го́ри, бисть трус ве́лій і огнь паля́щ, но не в сих Тя ви́ді, і по огні́ глас хла́да то́нка, і та́мо Госпо́дь; покри́в у́бо лице́ ми́лотію, с весе́лієм і стра́хом взива́ше: Аллилу́я!"]},{"h":"Ікос 6","ps":["Возсія́л єси́ в просвіще́ніє всему́ ми́ру сія́ніє Трисві́тлаго Божества́ Твоєго́, отгна́л єси́ вся і́дольськая заблужде́нія, Трийпоста́сний Бо́же і Го́споди; весь же род челові́чеський от до́лгия тьми язи́чества в чу́дний світ Єва́нгелія приве́л єси́, і́мже озаре́ннії, сла́вим вседержа́вний Про́мисл Твой о нас, зову́ще:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, до конця́ растлі́нную гріхо́м твар вода́ми пото́пними потреби́вий і в лиці́ Но́я обнови́вий весь род челові́ч!","Свят єси́ Го́споди Бо́же наш, отлучи́вий отця́ ві́рующих Авраа́ма от сміше́нія язи́к і в пото́мстві єго́ і́стинную Це́рков основа́вий!","Свят єси́ Го́споди Бо́же наш, ізведи́й лю́ди Своя́ із Єги́пта, препита́вий їх ма́нною в пусти́ні і введи́й в зе́млю, кип'я́щую ме́дом і мле́ком!","Свят єси́ Го́споди Бо́же наш, воздви́гий Дави́да, іспо́лнивий Ду́хом Свої́м проро́ки і ті́ми среди́ Ізра́їля ві́ру в обітова́ннаго Іскупи́теля сохрани́вий!","Свят єси́ Го́споди Бо́же наш, плі́ном Вавило́нським согрі́шшия лю́ди Своя́ наказа́вий і, по сконча́нії єго́, па́ки Ієрусали́му возгради́тися повелі́вий!","Свят єси́ Го́споди Бо́же наш, Маккаве́ї во ві́рі і преда́ніїх оте́чеських непоколеби́мими до сме́рти показа́вий, і Це́рков подзако́нную, я́ко неві́сту, до прише́ствія возлю́бленнаго Жениха́, ці́лу соблюди́й!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 7","ps":["Хотя́ прояви́ти вели́чіє любве́ і милосе́рдія Твоєго́ к па́дшему ро́ду челові́чеському, єгда́ приї́де кончи́на лі́та, посла́л єси́ Єдиноро́днаго Си́на Твоєго́, ражда́єма от Жени́, бива́єма под зако́ном, да подзако́нния іскупи́ть, І́же, пожи́в на землі́ я́ко челові́к і іскупи́в ни Кресто́м Свої́м, вознесе́ся на не́бо, отню́дуже, ісполня́яй обітова́ніє, низпосла́ нам Пресвята́го Ду́ха Своєго́, да зове́м всі: Аллилу́я!"]},{"h":"Ікос 7","ps":["Ди́вноє воі́стину і но́воє показа́л єси́ чу́до, ди́вний во висо́ких, Го́споди, єгда́ по низпосла́нії Пресвята́го Ду́ха на ізбра́нния ученики́ і апо́столи, ізве́л єси́ їх на про́повідь всему́ ми́ру, да возвістя́ть вели́коє і́м'я Пресвяти́я Тро́йці і пліня́ть вся язи́ки в послуша́ніє ві́ри: тім же, чудя́щеся си́лі і ді́йствію богодухнове́нних слове́с їх, с ра́достію зове́м:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, ізбра́вий немощна́я, худоро́дная і бу́їя ми́ра, да посрам'я́ть крі́пкия, сла́вния і прему́дрия!","Свят єси́ Го́споди Бо́же наш, воодушеви́вий безчи́сленния со́нми му́чеников, да тьма́ми муче́ній і смерте́й запечатле́ють і́стину Єва́нгелія і си́лу благода́ті Христо́вой!","Свят єси́ Го́споди Бо́же наш, се́рдце равноапо́стольнаго Константи́на зна́менієм Креста́ преклони́вий, і тім коне́ць лю́тим гоне́нієм на христия́н положи́вий!","Свят єси́ Го́споди Бо́же наш, седьмію́ Вселе́нськими Собо́ри богоно́сних оте́ць, я́ко седьмію́ столпи́, Це́рков огради́вши і єрети́чеським треволне́нієм непристу́пну сотвори́вий!","Свят єси́ Го́споди Бо́же наш, богому́дрим учи́телем і вели́ким подви́жником благоче́стія, я́ко пресві́тлим зві́здам на тве́рди Це́ркві, возсія́ти дарова́вий!","Свят єси́ Го́споди Бо́же наш, і влади́ку землі́ Россі́йськия Влади́мира к сві́ту і́стинния ві́ри наста́вивий, і тім всю страну́ на́шу от пре́лести многобо́жія свободи́вий!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 8","ps":["Стра́нно і чу́дно у ду́ба Мамврі́йська узрі́в Тя Авраа́м во о́бразі тріє́х муже́й, а́ки к єди́ному бесі́доваше, глаго́ля: Го́споди, а́ще обріто́х благода́ть пред Тобо́ю, не мини́ раба́ Твоєго́! Тріє́м у́бо, в Тріє́х я́вльшихся єму́ Ли́ціх, Отцю́, і Си́ну, і Свято́му Ду́ху, Єди́ному же в существі́ Бо́гу, до землі́ поклони́ся, зови́й: Аллилу́я!"]},{"h":"Ікос 8","ps":["Весь єси́ везді́ і всегда́, не то́чію могу́ществом неізче́тния си́ли Твоєя́, но і бога́тством вседі́тельнаго промишле́нія Твоєго́ о вся́цім созда́нії Твоє́м: нам же, я́коже рече́ Син Твой, і власи́ главні́ї всі ізочте́ні суть у Тебе́, да ні єди́н із них паде́ть без во́лі Твоєя́: ті́мже, упова́юще на Про́мисл Твой, со дерзнове́нієм і любо́вію зове́м:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, благоволи́вий всему́ ро́ду челові́чеському разділи́тися на племена́ і язи́ки, і коєму́ждо їх мі́сто і вре́м'я жи́тельства указа́вий!","Свят єси́ Го́споди Бо́же наш, І́мже ца́ріє ца́рствують і си́льнії пи́шуть пра́вду, соблюда́яй ізбра́нних Свої́х, я́ко зіни́цю о́ка!","Свят єси́ Го́споди Бо́же наш, от Него́же ісхо́дить вся́ка прему́дрость і ра́зум, вся́ка крі́пость і си́ла, вся́ко здра́віє і лі́пота!","Свят єси́ Го́споди Бо́же наш, наводя́й і от'є́мляй бра́ні, вінча́яй побі́дою пра́воє ору́жіє, непра́воє же, посреді́ са́мих побі́д, предопределя́яй к сокруше́нію!","Свят єси́ Го́споди Бо́же наш, дая́й зна́менія на небесі́ і на землі́, посила́яй огнь, я́зву і глад на лю́ди, да не до конця́ заблудя́ть от путе́й Твої́х!","Свят єси́ Го́споди Бо́же наш, вознося́й смире́нния от землі́, є́же посади́ти со кня́зі люде́й Свої́х, і низлага́яй го́рдия, я́ко не обрісти́ся мі́сту їх!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 9","ps":["Вся́коє єстество́, горе́ і ни́зу, непреста́нно сла́вить Тя, предві́чнаго Творця́ і Бо́га: на небесі́ єди́ни, Свят, Свят, Свят, день і нощ взива́ють, друзі́ї же вінці́ своя́ к подно́жію ног Твої́х полага́ють: на землі́ же со все́ю тва́рію ми, я́ко укра́шеннії о́бразом присносу́щния Твоєя́ сла́ви, к Тебі́ мо́лимся і от Тебе́ вели́кия і бога́тия ми́лости ча́єм, зову́ще: Аллилу́я!"]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния, а́ще і мно́го тружда́ються ми́слію во іспита́нії, о Та́їнстві Пресвяти́я Тро́йці, но не мо́гуть разумі́ти, ка́ко єстество́м Єди́н єсть Бог, в Тріє́х же соверше́нних Ли́ціх: ми же ві́руєм то́чію сему́ і іспові́дуєм, ка́коже, не іспиту́єм, і неізче́тная благодія́нія к нам коєго́ждо із Тріє́х Боже́ственних Лиць до́брі ві́дуще, с ві́рою і благодаре́нієм зове́м:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, пра́ведним судо́м Твої́м всім нам в зе́млю, от нея́же взя́ти єсьми́, возврати́тися, і па́ки в день воскресе́нія із нея́ воста́ти положи́вий!","Свят єси́ Го́споди Бо́же наш, со́лнцю, луні́ і зві́здам ні́когда поме́ркнути. Земле́ і всему́, є́же на ней, огне́м преобрази́тися предопреділи́вий, да вмі́сто їх яви́ться не́бо но́во і земля́ нова́, в ни́хже пра́вда живе́ть!","Свят єси́ Го́споди Бо́же наш, уста́вивий день, во́ньже предста́нуть на суд вся племена́ і язи́ци, да восприї́меть ки́йждо по діло́м свої́м!","Свят єси́ Го́споди Бо́же наш, імі́яй в день воздая́нія рещи́ пра́ведним: прийді́те благослове́ннії Отця́ Моєго́, і наслі́дуйте Ца́рствіє, угото́ванноє вам от сложе́нія ми́ра!","Свят єси́ Го́споди Бо́же наш, от Него́ же нераска́яннії грі́шници усли́шать тогда́ со стра́хом: отиді́те от Мене́ прокля́тії во огнь ві́чний, угото́ванний дия́волу і а́ггелом єго́!","Свят єси́ Го́споди Бо́же наш, обіща́вий Це́рков Свою́ до конця́ ми́ра непоколеби́му соблюсти́, во є́же неодоле́нней би́ти єй і от врат а́дових!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, яви́лася єси́ на Іорда́нстій ріці́, Пресвята́я і Пребоже́ственная Тро́йце: Оте́ць во гла́сі с не́ба, свиді́тельствуяй о возлю́бленнім Си́не, Син во о́бразі челові́честім, приє́мляй Креще́ніє от раба́, Дух Святи́й, сходя́й на Креща́ємаго во ви́ді голуби́ні: ті́мже во і́м'я Єди́наго Бо́га, в Три же Лиця́, Отця́, Си́на і Свята́го Ду́ха, научи́хомся просвіща́ти Креще́нієм вся́каго гряду́щаго в мир челові́ка, зову́ще: Аллилу́я!"]},{"h":"Ікос 10","ps":["Царю́ Преві́чний, сія́яй со́лнце Своє́ на благи́я і зли́я, пра́ведния люб'я́й, грі́шния же ми́луяй, скве́рну душе́вную і тіле́сную на́шу оми́й, оби́тель Свою́ в нас, а́ще і недосто́йних рабі́х Твої́х, сотвори́ти благоволи́, потреби́ нечи́стая на́ша помишле́нія, ізгла́ди неподо́бная дія́нія, напра́ви язи́ко глаго́лати благоуго́дная пред Тобо́ю, да чи́стим се́рдцем і устни́ со умиле́нієм зове́м:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, о Не́мже апо́стольський лик я́ві глаго́леть, к Нему́ же проро́чеський собо́р ви́ну взира́єть!","Свят єси́ Го́споди Бо́же наш, Єго́ же полк му́ченичеський боголі́пно іспові́дуєть, і преподо́бних во́їнство Пресвято́є і́м'я славосло́вить!","Свят єси́ Го́споди Бо́же наш, о Нем же пусти́нников мно́жество при́сно воздиха́єть, от Него́ же по́стников по́двиги вінча́ються!","Свят єси́ Го́споди Бо́же наш, Єму́ же святи́телі і па́стирі благода́рственноє прино́сять пі́ніє, І́мже вселе́нстії учи́тели во спасе́ніє на́ше богому́дрствують!","Свят єси́ Го́споди Бо́же наш, прийми́ мольбу́ о нас і предста́тельство всіх святи́х, па́че же простира́ющую к Тебі́ о нас ру́ці Своя́, Ді́ву Пречи́стую!","Свят єси́ Го́споди Бо́же наш, огради́ нас святи́ми Твої́ми А́нгели, і отжени́ от нас духо́в зло́би поднебе́сних!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє ізнемога́єть, тща́щеєся принести́ до́лжноє благодаре́ніє Тебі́ о всіх і за вся, в Тро́йці сла́вимому Бо́гу: не обріта́ється бо ні ра́зума, могу́ща сраспростре́тися ми́слію ко мно́жеству щедро́т Твої́х на нас, ні сло́ва, во є́же досто́йні ізрещи́ я: оба́че за вся, на́ми ви́димая і нам подає́мая, бу́ди Тебі́, Пресвята́я Тро́йце, благодаре́ніє от нас, честь і сла́ва, якови́ же Ти Сама́ Твоєго́ вели́чества досто́йни і Тебі́ уго́дни ві́си: ми же, покланя́ющеся Тебі́, со смире́нієм і любо́вію зове́м: Аллилу́я!"]},{"h":"Ікос 11","ps":["Я́ко світопода́тельна Тя во обітова́ніїх Твої́х світи́льника, су́щим нам во тьмі неві́дінія о бу́дущем жре́бії на́шем я́вльшася, благода́рні іспові́дующе і поне́ єди́наго із блаже́нств, Єдиноро́дним Си́ном Твої́м возвіще́нних, улучи́ти жела́юще, всеуми́льно с ві́рою вопіє́м:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, угото́вавий ізбра́нним Свої́м бла́га, ї́хже о́ко не ви́ді, у́хо не сли́ша, і я́же на се́рдці челові́ку не взидо́ша!","Свят єси́ Го́споди Бо́же наш, Єго́ же всі чи́стії се́рдцем у́зрять, я́коже єсть, і позна́ють, я́коже от Него́ са́мі позна́ні суть!","Свят єси́ Го́споди Бо́же наш, в Не́мже всі а́лчущії і жа́ждущії пра́вди обрету́ть, ніколи́же оскудева́ющеє насище́ніє!","Свят єси́ Го́споди Бо́же наш, от Него́ же миротво́рці, я́ко подража́телі вся умиротвори́вшаго Єдиноро́днаго Си́на Твоєго́, возлю́бленними сина́ми нареку́ться!","Свят єси́ Го́споди Бо́же наш, у Него́ же кро́тциє наслі́дять зе́млю, і ни́щії ду́хом улуча́ть неконча́ємоє Ца́рствіє!","Свят єси́ Го́споди Бо́же наш, обіща́вий ві́чноє поми́лованіє ми́лующим, і безконе́чноє ра́дованіє пла́чущим!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 12","ps":["Благода́ть Твою́ всеси́льную пода́ждь нам, Пресвята́я Тро́йце: прийми́ іспові́даніє гріхо́в на́ших пред вели́чеством сла́ви Твоєя́, при́зри на воздиха́нія на́ша, низпосли́ нам ду́ха умиле́нія і щедро́т, да, очище́ннії душе́ю і се́рдцем, сподо́бимся неосужде́нно зва́ти к Тебі́ на землі́, я́коже взива́ють А́нгели на небесі́: Аллилу́я!"]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ всечеловеколю́бноє смотре́ніє, сла́вим Тя всі, Пребезнача́льная Тро́йце, ві́руєм во Єди́наго Бо́га Отця́, Бо́га Си́на і Бо́га Ду́ха Свята́го, іно́го, ра́зві Тебе́, Го́спода не ві́ми, к Тебі́ припа́даєм і Тебі́ мо́лимся, вопію́ще:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, бу́ди нам во спасе́ніє, да не убої́мся нікоєго́же зла, і в защище́ніє живота́ на́шего, да не устраші́мся нікоєго́же врага́!","Свят єси́ Го́споди Бо́же наш, грі́шния ка́ющияся спаса́яй, спаси́ у́бо і нас многогрі́шних!","Свят єси́ Го́споди Бо́же наш, умножа́яй всім ми́лость Твою́, умно́жи ю і на нас, і поми́луй ни, я́ко не́мощни єсьми́!","Свят єси́ Го́споди Бо́же наш, продолжи́ нам вік к покая́нію і не осуди́ нас на посіче́ніє с смоко́вницею безпло́дною!","Свят єси́ Го́споди Бо́же наш, ізба́ви ни іскуше́ній, от ми́ра, пло́ті і дия́вола находя́щих, і укріпи́ во ві́рі і любві́ к Тебі́!","Свят єси́ Го́споди Бо́же наш, сподо́би ни лице́м к лицю́ узрі́ти Тя, і вни́ти в сві́тлий черто́г Твой на брак А́гнчий!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 13","ps":["О Пресвята́я, Животворя́щая, Неразділи́мая і Вседі́тельная Тро́йце, О́тче, Си́не і Ду́ше Святи́й, Єди́не і́стинний Бо́же і Тво́рче наш! Ни́нішнєє на́ше приє́мши благодаре́ніє, низпосли́ нам благода́ть і си́лу от висоти́ Свята́го Престо́ла Твоєго́, да, попра́вше вся плотські́я по́хоті, во вся́ком благоче́стії і чистоті́ поживе́м до конця́ дній на́ших, ви́ну восхваля́юще Пресвято́є І́м'я Твоє́ і зову́ще: Аллилу́я!","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели, Нача́ла і Вла́сті, Престо́ли і Госпо́дствія, предстоя́ще самому́ Престо́лу Сла́ви Твоєя́, не довлі́ють ізрещи́ вели́чія соверше́нств Твої́х: многоочи́тії же Херуви́ми і шестокрила́тії Серафи́ми, закрива́юще ли́ця своя́, то́чію с тре́петом і любо́вію взива́ють друг ко дру́гу: Свят, Свят, Свят Госпо́дь Савао́ф! Нам у́бо, і́же прах і пе́пел єсьми́, кольми́ па́че удо́біє люби́ти молча́ніє: но, да не толи́ких щедро́т, в созда́нії і іскупле́нії на нас ізлія́нних, непа́м'ятливи яви́мся і неблагода́рни, подража́юще го́рнему славосло́вію, с ві́рою і любо́вію взива́єм:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, неісповіди́мая соверше́нств Висото́ і неізслі́димая та́їн Пучи́но!","Свят єси́ Го́споди Бо́же наш, везді́ сий і вся ісполня́яй, Єди́ний і То́йжде вчера́, днесь і во ві́ки!","Свят єси́ Го́споди Бо́же наш, вся моги́й, нариця́яй не су́щая я́ко су́щая, низводя́й да́же до а́да і па́ки возводя́й!","Свят єси́ Го́споди Бо́же наш, іспиту́яй сердця́ і утро́би челові́чеськія, ісчита́яй зві́зди і всім їм імена́ нариця́яй!","Свят єси́ Го́споди Бо́же наш, Єго́же всі путіє́ і́стинни і все судьби́ оправда́ни вку́пі і вожделі́нни!","Свят єси́ Го́споди Бо́же наш, отдая́ гріхи́ отце́в на ча́да, ми́луяй же і награжда́яй в ро́ди родо́в!","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Кондак 1","ps":["Предві́чний Царю́ віко́в і Го́споди, всея́ тва́рі ви́димия і неви́димия Соді́телю, Єму́же, в Тро́йці Святі́й сла́вимому Бо́гу, вся́ко колі́но покланя́ється небе́сних, земни́х і преіспо́дніх: ті́мже і ми, я́ко креще́ннії в Трисвято́є і́м'я Твоє́, а́ще і недосто́йнії, хвале́бноє сіє́ дерза́єм принести́ Тебі́ пі́ніє: Ти же, я́ко Творе́ць, Промисли́тель і Судія́ наш, воньми́ гла́су раб Твої́х, і не отста́ви ми́лости Твоєя́ от нас, да із глубини́ душі́ ви́ну зове́м Ті:","Свят, Свят, Свят єси́ Го́споди Бо́же наш, поми́луй ни, па́дшеє созда́ніє Твоє́, І́мене ра́ди Свята́го Твоєго́!"]},{"h":"Молитва до Пресвятої Тройці","ps":["Пресвята́я Тро́йце, Єдиносу́щная Держа́во, всіх благи́х Вина́, что воздади́м Тебі́ за вся, я́же воздала́ єси́ нам, грі́шним і недосто́йним, пре́жде, не́же на світ проізидо́хом, за вся, я́же воздає́ши коєму́ждо нас по вся дні і я́же угото́вала єси́ нам во ві́ці гряду́щем? Подоба́ше у́бо за толи́кия благодія́нія і щедро́ти благодари́ти Тя не словеси́ то́чію, но па́че ді́ли, храня́ще і ісполня́юще за́повіді Твоя́: ми же, страсте́м на́шим і злим оби́чаєм вне́мше, в безчи́сленния от ю́ности низверго́хомся гріхи́ і беззако́нія. Сего́ ра́ди, я́ко нечи́стим і оскверне́нним, не то́чію пред трисві́тлоє Лице́ Твоє́ безсту́дно яви́тися, но ніже́ І́мене Твоєго́ Пресвята́го ізрещи́ довлі́яше нам, а́ще би не Ти Сама́ благоізво́лила, во отра́ду на́шу возвісти́ти, я́ко чи́стия і пра́ведния лю́биши, грі́шники ка́ющіяся ми́луєши і благоутро́бне приє́млеши. При́зри у́бо, о Пребоже́ственная Тро́йце, с висоти́ Святи́я Сла́ви Твоєя́ на нас, многогрі́шних, і благо́є проізволе́ніє на́ше вмі́сто благи́х діл прийми́: і пода́ждь нам ду́ха і́стиннаго покая́нія, да возненави́дівше вся́кий гріх, в чистоті́ і пра́вді, до конця́ дній на́ших поживе́м, творя́ще пресвяту́ю во́лю Твою́ і сла́в'яще чи́стими по́мисли і благи́ми дія́ньми сладча́йшеє і великолі́поє І́м'я Твоє́. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Благослове́н єси́, Христе́ Бо́же наш, / І́же прему́дри ловці́ явле́й, / низпосла́в їм Ду́ха Свята́го, // і ті́ми уловле́й вселе́нную, Человіколю́бче, сла́ва Тебі́."]},{"h":"Кондак, глас 8","ps":["Єгда́ снизше́л язи́ки слія́, / разділя́ше язи́ки Ви́шній, / єгда́ же о́гненния язи́ки раздая́ше, / в соєдине́ніє вся призва́, // і согла́сно сла́вим Всесвята́го Ду́ха."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / і чтим Всесвята́го Ду́ха Твоєго́, / Єго́же от Отця́ посла́л єси́ // Боже́ственним ученико́м Твої́м."]},{"h":"Задостойник, глас 4","ps":["Апо́столи, соше́ствіє Уті́шителя зря́ще, удиви́шася, // ка́ко во ви́ді о́гнених язи́к яви́ся Дух Святи́й.","Ра́дуйся, Цари́це, / матероді́вственная сла́во: / вся́ка бо удобообраща́тельная благоглаго́ливая уста́ вити́йствовати не мо́гуть / Тебі́ пі́ти досто́йно; / ізуміва́єть же ум всяк твоє́ Рождество́ разумі́ти. // Ті́мже Тя согла́сно сла́вим."]}],"notes":[]},{"u":"Акафіст Різдву Пресвятої Богородиці","e":"Akathist to the Nativity of the Most Holy Theotokos","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от челові́чеськаго ро́да і ро́ждшейся от непло́дове, Пречи́стій Ді́ві Марі́ї соста́вим похвалу́, я́ко рождество́м Єя́ нача́ло спасе́нія на́шего бисть і прише́ствіє в мир Ізба́вителя возвісти́ся. Ті́мже ра́достно Єй возопії́м:","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Ікос 1","ps":["А́нгел небе́сний предстоя́й пред Бо́гом, по́слан бисть к пра́ведним Іоаки́му і А́нні возвісти́ти їм ра́дость ве́лію, я́ко по непло́дствії своє́м і́муть роди́ти Дщер Преблагослове́нную, от Нея́же всему́ ми́ру ра́дость проізи́деть. Ті́мже і ми, ра́дости сея́ прича́стници, похва́льная пі́сні Ді́ві воспоє́м:","Ра́дуйся, в Тро́їчном Сові́ті Ма́терію Си́на Бо́жия от ві́ка предизбра́нная;","ра́дуйся, дре́вніми проро́ками с патріа́рхи многообра́зні в о́бразіх і сі́ніх прообразова́нная.","Ра́дуйся, вя́щшіє п'яти́ ти́сящ літ от созда́нія ми́ра ві́рними Бо́жиїми раби́, я́ко Ма́тер Ізба́вителя ожида́нная;","ра́дуйся, лі́ствицею Іа́ковом ви́денною, Бо́жиє к челові́ком снизше́ствіє прообразова́вшаго предука́занная.","Ра́дуйся, неопали́мою купино́ю в пусти́ні Сина́йстій Моїсе́ом ви́денною, предвозвіще́нная;","ра́дуйся, Чермни́м мо́рем Ізра́їлю сух путь да́вшему, фарао́на же потопи́вшему, о́бразні преднапи́санная.","Ра́дуйся, написа́тися нам в кни́зі Живота́ Ві́чнаго посо́бствующая;","ра́дуйся, Ца́рствія Небе́снаго невозбра́нний вход нам хода́тайствующая.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 2","ps":["Ви́дяще пра́веднії Іоаки́м і А́нна я́вльшагося їм А́нгела, возвіща́юща рождество́ Твоє́, Пресвята́я Ді́во, возблагодари́ша Бо́га, призрі́вшаго от'я́ти поноше́ніє безча́дія їх, і всім се́рдцем те́плі возопи́ша: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственнаго строї́тельства і на зе́млю снизше́ствія Своєго́ Всеблаги́й Госпо́дь іспо́лнити начина́я, посла́нієм А́нгела Своєго́ возвісти́ти Іоаки́му і А́нні о рождестві́ Твоє́м, Пресвята́я Ді́во. Ті́мже вопіє́м Ті хвале́бно:","Ра́дуйся, ра́зума Боже́ственнаго проявле́ніє;","ра́дуйся, ди́внаго смотре́нія Єго́ ісполне́ніє.","Ра́дуйся, дре́вле предуста́вленная послужи́ти воплоще́нію Си́на Бо́жия;","ра́дуйся, от всіх родо́во в жили́ще всіх Царя́ предизбра́нная.","Ра́дуйся, єще́ в рай ізрече́нієм іскуси́телю змі́ю о положе́нії вражди́ между́ тім і Жено́ю і Сі́менем Єя́ предука́занная;","ра́дуйся, по ісполне́нії време́н от непло́дове ізволе́нієм Бо́жиїм сла́вне проізше́дшая.","Ра́дуйся, род челові́чеський рождество́м Свої́м возвесели́вшая;","ра́дуйся, сі́тованіє ча́явших уті́хи Ізра́їлеви преложи́вшая.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго разріши́ непло́дство заматоре́вшия во днех свої́х пра́ведния А́нни: зача́т бо Тя, Пречи́стая, і, ча́я Твоєго́ рожде́нія, ра́достно поя́ше Бо́гу Ізра́їлеву хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щая безму́жно роди́ти Спаси́теля душ і тіле́с на́ших, Ти і Сама́, я́ко чу́до пред ве́ліїм і непостижи́мим чудесе́м, от непло́дних роди́телей сла́вно роди́ся, Пресвята́я Ді́во. Ті́мже воспіва́єм Ті си́це:","Ра́дуйся, от ко́рене Ієссе́ова і Дави́дова проізше́дшая;","ра́дуйся, от непло́дних ложе́сн пра́ведния А́нни ди́вно прозя́бшая.","Ра́дуйся, проро́чеством Іса́її пре́жде літ дре́вніх Ді́ва-Ма́тер проявле́нная;","ра́дуйся, по обітова́нію А́нгела рожде́нная.","Ра́дуйся, ски́нією свиді́нія і Ковче́гом заві́та прообразова́нная;","ра́дуйся, процві́тшим жезло́м Ааро́новим обра́зні прознаменова́нная.","Ра́дуйся, пре́жде рождества́ Твоєго́ в Ма́тер Бо́гу-Сло́ву освяще́нная і предугото́ванная;","ра́дуйся, рожде́нієм Твої́м мир освіти́вшая.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 4","ps":["Бу́ри поноше́ній челові́чеських о непло́дствії своє́м ізба́вльшеся в зача́тії Твоє́м, Пресвята́я Ді́во, пра́веднії роди́теліє Твої́ ра́довахуся, і в честь рождества́ Твоєго́ учрежде́ніє ве́ліє творя́ху сро́дником і зна́ємим, і ті́ї сра́довахуся їм, вопію́ща Бо́гу, сотво́ршему ми́лость Свою́, хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше окре́стниє лю́діє, я́ко дщи Іоаки́ма і А́нни нарече́на бисть Марі́я, сі́єсть Госпожа́, проразуміва́ху, Пречи́стая, вели́ку і сла́вну Тя би́ти не то́кмо в лю́діх, но і у Бо́га. Ми же сбитіє́ сего́ до́брі ві́дуще, велича́єм Тя си́це:","Ра́дуйся, Пресвята́я Ді́во, не от челові́ка, но от А́нгела і́м'я Себі́ єще́ пре́жде зача́тія прия́вшая;","ра́дуйся, по і́мені сему́ Госпоже́ю всея́ тва́рі би́ти сподо́бльшаяся.","Ра́дуйся, я́ко пра́веднії роди́теліє Твої́ воздаю́ще Бо́гу благодаре́ніє за рожде́ніє Твоє́, вели́кия да́ри в же́ртву Тому́ принесо́ша;","ра́дуйся, я́ко сро́дником і зна́ємим, ку́пно же і убо́гим ве́черю любве́ сотвори́ша.","Ра́дуйся, я́ко от свяще́нников, в дом роди́телей Твої́х на торжество́ позва́нних, благослове́нна єси́;","ра́дуйся, я́ко от всіх на весе́ліє о́но собра́вшихся, похвале́на і просла́влена била́ єси́.","Ра́дуйся, ви́ше вся́кия че́сти і похвали́ я́вльшаяся;","ра́дуйся, Ма́терію Бо́га-Сло́ва би́ти сподо́бльшаяся.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́, возвіща́ющая прише́ствіє Со́лнця Пра́вди, Христа́ Бо́га на́шего, в рождестві́ Твоє́м яви́ся, о, Пресвята́я Ді́во; ті́мже лю́діє Бо́жії, прише́ствія Ізба́вителя ві́рою ча́явшії, ви́дяще Тя чу́дно от непло́дове ро́ждшуюся, та́їнственно возвесели́шася і возопи́ша: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши пра́веднії Іоаки́м і А́нна ро́ждшуюся от них Богоотрокови́цю Марі́ю, о Не́йже А́нгел Бо́жий ні́кая чу́дная і ди́вная тім провозвісти́, я́ко киво́ту Бо́жию, Той послужи́ша, воспитава́юще і храня́ще Ю, я́коже зі́ницю о́ка. Ті́мже і ми похваля́юще Богоотце́в, сподо́бившихся роди́тельми би́ти такови́я Дще́ри, Ді́ві Марі́ї ра́достно воспіва́єм:","Ра́дуйся, Пречи́стая Ді́во, я́ко по рождестві́ Твоє́м роди́теліє Твої́ вельми́ возликова́ху;","ра́дуйся, я́ко в явле́нії Твоє́м в мир А́нгели і челові́ци согла́сно возра́довахуся.","Ра́дуйся, я́ко о Тебі́ всі проро́ци многообра́зні предглаго́лаху;","ра́дуйся, я́ко єди́н от них Врата́ми затворе́нними, ін же Горо́ю преосене́нною Тя іменова́ху.","Ра́дуйся, я́ко вся пресла́вная дре́вле та́їнственно о Тебі́ предглаго́лано би́ша;","ра́дуйся, я́ко Градо́м і Селе́нієм Бо́жиїм псало́мськая уста́ Тя найменова́ша.","Ра́дуйся, седьмосве́щним світи́льником, я́ко седьмію́ дара́ми Свята́го Ду́ха іспо́лнена би́ти імі́вшая, предука́занная;","ра́дуйся, позлаще́нною трапе́зою с хлі́бами предложе́нія, я́ко Хліб Жи́зні, Христа́, роди́ти імі́вшая, предука́занная.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 6","ps":["Пропові́дник богоно́сних віща́нія і глаго́ли ісполня́я, ізволе́нієм Зижди́теля тва́рі на землі́ яви́лася єси́, Пресвята́я Ді́во, єстества́ на́шего цві́те, Ада́ма же і Є́ви воззва́ніє і на пе́рвую добро́ту возведе́ніє. Ті́мже всі ві́рнії в рождестві́ Твоє́м ра́дость обрі́тши, духо́вно торжеству́ющим, пою́ще ди́вному в Сові́ті Своє́м Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в рождестві́ Твоє́м, Пречи́стая, заря́ спасе́нія на́шего, во ісполне́ніє Боже́ственнаго смотре́нія, і́мже єди́на Ти от всіх родо́в досто́йна яви́лася єси́ плоть заімода́ти Зижди́телю Твоєму́, прише́дшему спасти́ род наш от дре́внія пра́отечеськия кля́тви. Сего́ ра́ди взива́єм Ті си́це:","Ра́дуйся, Ада́ма і Є́ви воззва́ніє;","ра́дуйся, дре́внія кля́тви разріше́ніє.","Ра́дуйся, сіно́внаго зако́на коне́ць і но́вия благода́ті нача́ло;","ра́дуйся, промишле́нія Боже́ственнаго Таї́нниця і на ді́ланія блага́я нас при́сно наставля́ющая.","Ра́дуйся, єди́на во всіх ро́діх досто́йно обрі́тшаяся би́ти Ма́терію Бо́га-Сло́ва;","ра́дуйся, і нам но́вим во Христі́ лю́дем духо́вная Ма́ти я́вльшаяся.","Ра́дуйся, Ма́терним Твої́м попече́нієм ніколи́же нас оставля́ющая;","ра́дуйся, в си́ни і дще́рі Си́ну Твоєму́ досто́йни і благоуго́дни нас приуготовля́ющая.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 7","ps":["Хотя́ще обі́ти своя́ Го́сподеві возда́ти, пра́веднії роди́теліє Твої́, Пресвята́я Ді́во, трилі́тствующую Тя отрокови́цю приведо́ша в храм Госпо́день со сла́вою і ра́достію мно́гою, первосвяще́нник же (Заха́рія), Ду́хом Бо́жиїм об'я́тий, введе́ Тя во Свята́я Святи́х, я́же проо́бразом то́кмо би́ша Твоєя́ Святи́ні. Ти бо вмісти́ла в Себі́ не киво́т Заві́та, но святи́х Святі́йшаго Си́на Бо́жия, во утро́бі Твоє́й ді́вственній плоть восприя́вшаго. Єму́же Ти с ли́ки діви́чеськими ви́ну воспіва́ла єси́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє і пресла́вноє промишле́ніє Боже́ственноє бисть о Тебі́, Ді́во Марі́є. В хра́мі бо Бо́жиєм жи́тельствующи пи́щу от рук А́нгельських принима́ла єси́, Пресвята́я. Ті́мже мо́лим Тя: напита́й нас пи́щею благода́тною, да возрасте́м духо́вно в му́жа соверше́нна і Тебі́, Всецари́це, похва́льная возопіє́м:","Ра́дуйся, преукраше́нная доброді́тельми, Отрокови́це, в хра́мі Бо́жиєм жи́ти і А́нгелом Собесі́днице би́ти сподо́бльшаяся;","ра́дуйся, посила́вшуюся Тебі́ Бо́гом пи́щу от А́нгелов во Свята́я Святи́х принима́вшая.","Ра́дуйся, небе́сним хлі́бом во хра́мі чуде́сно воспита́нная;","ра́дуйся, к вели́кому та́їнству воплоще́нія Си́на Бо́жия та́мо предугото́ванная.","Ра́дуйся, я́ко повелі́нієм Бо́жиїм А́нгели на землі́ Тебі́ усе́рдно служа́ху;","ра́дуйся, я́ко ті́ї ни́ні на Небесі́х, я́ко Цари́це, благогові́йно Тебі́ слу́жать.","Ра́дуйся, я́ко і ми недосто́йнії пі́сньми хвале́бними при́сно Тя велича́єм;","ра́дуйся, я́ко і ро́ждших Тя Богоотце́во всегда́ ублажа́єм і в моли́твах їх призива́єм.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 8","ps":["Стра́нноє рождество́ Пречи́стия Ді́ви ви́дівше, устрані́мся су́єтнаго ми́ра, ум на Небеса́ прело́жше, іді́же Богома́тер во сла́ві предстої́ть Си́ну Своєму́ і Бо́гу, хода́тайствующи пред Ним о всіх ві́рних, всесла́вноє рождество́ Єя́ (і в храм введе́ніє) любо́вію пра́зднующих і вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся твар в рождестві́ Твоє́м, Пречи́стая, обрі́те ра́дость, печа́ль праоте́чеськую потребля́ющую: проізше́дшим бо от Тебе́ Христо́м Бо́гом, па́дшеє во гріх преслуша́нія єстество́ на́ше от паде́нія воста́ і па́ки любе́зно Зижди́телю сотвори́ся. Ті́мже уми́льно Ті взива́єм:","Ра́дуйся, всеми́рния ра́дости предвозвіще́ніє;","ра́дуйся, та́їнство от ві́ка сокрове́ннаго явле́ніє.","Ра́дуйся, Є́юже паде́нія воста́хом;","ра́дуйся, Є́юже пре́жде отринове́нноє єстество́ на́ше і́стіє Бо́гу присво́їся.","Ра́дуйся, Є́юже Іоаки́м і А́нна поноше́нія безча́дія свободи́шася;","ра́дуйся, Є́юже безпло́діє серде́ць на́ших в благопло́діє приміни́ся.","Ра́дуйся, Є́юже оби́ліє благ ві́чних ві́рним от Го́спода подає́ться.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 9","ps":["Всі А́нгели Бо́жії не ві́дівшії та́йни Боговочелові́ченія в Сові́ті Триіпоста́снаго Божества́ от ві́ка сокрове́нния і напослі́док Ді́вою Марі́єю явле́нния, вельми́ удивле́ни би́ша, зря́ще, ка́ко Дщи Іоаки́ма і А́нни необи́чно єстеству́ же́нському, во Свята́я Святи́х введе́ся. Ті́мже недоумі́нієм об'я́ти би́вше, благогові́йно вопія́ху: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я дре́внійший, всему́дрий в царі́х Ізра́їлевих Соломо́н, прови́дя рождество́ Твоє́, Пречи́стая, в Пі́сніх Пі́сней со удивле́нієм возглаша́ша: “Кто Сія́, прониця́ющая, а́ки у́тро, добра́, я́ко луна́, ізбра́нна, я́ко со́лнце”. Ті́мже Це́рков ликовству́ющи в пра́здниці Твоє́м, ве́село Тебі́ вопіє́ть:","Ра́дуйся, невече́рняго дне Богові́дінія у́тро світлі́йшеє, в зако́нній сі́ні, я́ко во мра́ці, возсія́вшеє;","ра́дуйся, солнцеобра́зная Ді́во, і́стинноє Со́лнце — Христа́, ді́вственним воплоще́нієм в мир вве́дшая і тім вся просвіти́вшая.","Ра́дуйся, світови́дная стихи́я, су́щественно прия́вшая Бо́га, живу́щаго во сві́ті непристу́пнім;","ра́дуйся, Свої́м ма́лим чре́вом об'я́вшая Безпреді́льнаго, вся конці́ вселе́нния об'є́млющаго.","Ра́дуйся, по́лная луно́, світ боже́ственний непосре́дственно восприє́млющая і нас тім озаря́ющая;","ра́дуйся, чисті́йшеє зерца́ло, в не́мже мно́гая соверше́нства Бо́жия чу́дно і ві́рно ізобража́ються.","Ра́дуйся, соверше́нством Твої́х доброді́телей і нас к тому́ же подвиза́ющая;","ра́дуйся, немощни́я на́ші си́ли к творе́нію до́брих діл подкрепля́ющая.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ род челові́чеський от перворо́дния кля́тви, ди́вноє смотре́нія Своєго́ та́їнство сотвори́ Госпо́дь: ізбра́ бо Тя, Пречи́стая, от ро́да Авраа́мля і Дави́дова, і от Тебе́ безсі́менно воплоти́тися благоізво́ли, преше́д уста́ви єстества́, но і тя проізведе́ от заматорі́вша і непло́дна ко́рене Іоаки́ма і А́нни пра́ведников. Ті́мже рождество́ Твоє́ (і в храм вхожде́ніє) днесь пра́зднующи і ро́ждших Тя пі́сньми восхваля́ющи, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Небе́сний, спасе́нія на́шего ра́ди хотя́ на землі́ яви́тися і с челові́ки пожи́ти, черто́г свят воплоще́нія Своєго́, Тя, Пречи́стая, предугото́ва, пода́в плод безча́дной А́нні, сле́зно с супру́жником Свої́м, моли́вшимся о разріше́нії своєго́ непло́дства. Ті́мже мо́лим Тя, Богома́ти: разріши́ непло́діє душ на́ших, да возмо́жем принести́ Бо́гу плод благи́х діл доброді́телі, взива́юще Ті си́це:","Ра́дуйся, пресві́тлий Черто́же безсі́меннаго Бо́жия воплоще́нія;","ра́дуйся, одушевле́нная Пала́то, в жили́ще всіх Царя́ предугото́ванная.","Ра́дуйся, світлі́йшій о́блаче, і́мже Сідя́щий на престо́лі Божества́ к нам сни́де;","ра́дуйся, Посре́днице зако́на і благода́ті, запечатлі́ніє Ве́тхаго і Но́ваго Заві́тов.","Ра́дуйся, неув'яда́ємая Лозо́, прекра́сний цвіт — Спаси́теля ми́ра, проізрасти́вшая;","ра́дуйся, благово́нноє я́блоко, от непло́дове проізра́стшеє і Христу́ благоуго́дно я́вльшеєся.","Ра́дуйся, і нас, півце́в Твої́х, благоуго́дни Христу́ предста́вити тща́щаяся;","ра́дуйся, я́ко і нас, безпло́дни су́щих ді́ли благи́ми, не лиша́єши духо́внаго утіше́нія.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 11","ps":["Піснь хвале́бную рождеству́ Твоєму́ (і в храм введе́нію) принося́щих не отри́ни, Влади́чице Блага́я, но ро́ждших Тя ра́ди, благоцве́тлива нам бу́ди, моля́щи о нас Си́на Твоєго́ і Бо́га на́шего, да пода́сть гріхо́в проще́ніє і житія́ ісправле́ніє, є́же в покая́нії сле́зном ви́ну благода́рно воспіва́єм Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная і преми́рная Боже́ственнаго сві́та Свіща́, єдиноро́дная Дщер Іоаки́ма і А́нни, предизбра́нная в Ма́тер Єдиноро́дному Си́ну Бо́жию, днесь от непло́дове пресла́вно проізи́де, і просвіща́єть всіх рождество́ Єя́ (і в храм вхожде́ніє) ві́рно пра́зднующих і благогові́йно взива́ющих:","Ра́дуйся, світоза́рная Свіще́, Боже́ственним пла́менем возжже́нная;","ра́дуйся, і нас тім благода́тно просвіща́ющая і согріва́ющая.","Ра́дуйся, та́їнственная Клеще́, Угль Боже́ственний Христа́ Го́спода во утро́бі і на рука́х Твої́х носи́вшая;","ра́дуйся, і нас в Та́їнстві Причаще́нія прийма́ти Того́ сподобля́ющая.","Ра́дуйся, живи́й і преукраше́нний Храм Госпо́день, о Не́мже поє́ть Дави́д: “Свят Храм Твой, ди́вен в пра́вді”;","ра́дуйся, Кади́льнице Свята́я, не фимія́м, во возду́хі разлива́ющийся, но Христа́, ві́чноє благово́ніє в Себі́ вмісти́вшая, і всю твар тім облагоуха́вшая.","Ра́дуйся, Престо́ле, превознесе́нний со сла́вою, одушевле́нноє сіда́лище Вели́каго Царя́, на́шего же Спаси́теля і Го́спода;","ра́дуйся, Цари́це Небесе́ і землі́, с Сино́м Твої́м і Бо́гом ві́чно ца́рствующая і нас, убо́гих, не забива́ющая.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 12","ps":["Благода́ті па́че, не́же єстества́ ді́йство прояви́ся в рождестві́ Твоє́м, Пречи́стая; моли́тву бо безча́дних роди́телей Твої́х, Госпо́дь усли́шав, подаде́ Тя їм в утіше́ніє, я́коже Авраа́му і Са́ррі Ісаа́ка, восхоті́во вку́пі і Своєго́ смотре́нія та́їнство на Тебі́ соверши́ти і угото́вати Тя в Ма́тер Єдиноро́дному Си́ну Своєму́, обетова́нному на́шему Іскупи́телю. Єму́же благода́рно поє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще сла́вноє Твоє́ от непло́дове рожде́ніє (і в храм Госпо́день введе́ніє), хва́лим Тя Пречи́стая, я́ко Таї́нницю Бо́жия о нас спаси́тельнаго смотре́нія, воплоще́нієм от Тебе́ Бо́га-Сло́ва явле́ннаго, і вопіє́м Ті си́це:","Ра́дуйся, чи́стая Но́єва Голуби́це, рождество́м Твої́м преста́тіє пото́ка сме́ртнаго возвісти́вшая;","ра́дуйся, вітв благові́стія Христа́ Спаси́теля погиба́вшему гріхо́м ро́ду челові́чеському прине́сшая.","Ра́дуйся, єди́на блаже́нная в жена́х, послуша́нієм Твої́м Бо́гу преслуша́ніє прама́тері Є́ви іспра́вившая;","ра́дуйся, печа́ль Ада́ма і про́чих пра́отцев, (істоми́вшихся ожида́нієм прише́ствія Ізба́вителя) рождество́м Твої́м в ра́дость преложи́вшая.","Ра́дуйся, я́ко рождество́ Твоє́ ра́дость возвісти́ всей вселе́нной;","ра́дуйся, я́ко в рождестві́ Твоє́м ма́тері ра́дуються і непло́ди веселя́ться (ві́дуще, я́ко і Ти от непло́дове проізошла́ єси́).","Ра́дуйся, я́ко і всіх рождество́ Твоє́ (і в храм вхожде́ніє) ві́рно і благоче́стно пра́зднующих сподобля́єши благода́тнаго весе́лія;","ра́дуйся, с Сино́м Твої́м, одесну́ю Отця́ во сла́ві Єго́, спосади́ти нас, Єго́ мно́го умоля́ющая.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 13","ps":["О, Всепі́тая і Пречи́стая Ма́ти Ді́во, прийми́ сіє́ на́ше хвале́бноє пі́ніє в честь пресла́внаго рождества́ Твоєго́ (і в храм введе́нія) приноси́моє, і возроди́ в нас жела́ніє благ ві́чних, вку́пі же і ізба́ви нас, Це́рков Твою́ Святу́ю, Оте́чество на́ше і оби́телі і́ночеськия от вся́ких бід і напа́стей, от враго́во ви́димих і неви́димих, і бу́дущия ізми́ му́ки і Небе́снаго Ца́рствія нас сподо́би, да во ві́ки віко́в о Тебі́ вопіє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел небе́сний предстоя́й пред Бо́гом, по́слан бисть к пра́ведним Іоаки́му і А́нні возвісти́ти їм ра́дость ве́лію, я́ко по непло́дствії своє́м і́муть роди́ти Дщер Преблагослове́нную, от Нея́же всему́ ми́ру ра́дость проізи́деть. Ті́мже і ми, ра́дости сея́ прича́стници, похва́льная пі́сні Ді́ві воспоє́м:","Ра́дуйся, в Тро́їчном Сові́ті Ма́терію Си́на Бо́жия от ві́ка предизбра́нная;","ра́дуйся, дре́вніми проро́ками с патріа́рхи многообра́зні в о́бразіх і сі́ніх прообразова́нная.","Ра́дуйся, вя́щшіє п'яти́ ти́сящ літ от созда́нія ми́ра ві́рними Бо́жиїми раби́, я́ко Ма́тер Ізба́вителя ожида́нная;","ра́дуйся, лі́ствицею Іа́ковом ви́денною, Бо́жиє к челові́ком снизше́ствіє прообразова́вшаго предука́занная.","Ра́дуйся, неопали́мою купино́ю в пусти́ні Сина́йстій Моїсе́ом ви́денною, предвозвіще́нная;","ра́дуйся, Чермни́м мо́рем Ізра́їлю сух путь да́вшему, фарао́на же потопи́вшему, о́бразні преднапи́санная.","Ра́дуйся, написа́тися нам в кни́зі Живота́ Ві́чнаго посо́бствующая;","ра́дуйся, Ца́рствія Небе́снаго невозбра́нний вход нам хода́тайствующая.","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Кондак 1","ps":["Ізбра́нній от челові́чеськаго ро́да і ро́ждшейся от непло́дове, Пречи́стій Ді́ві Марі́ї соста́вим похвалу́, я́ко рождество́м Єя́ нача́ло спасе́нія на́шего бисть і прише́ствіє в мир Ізба́вителя возвісти́ся. Ті́мже ра́достно Єй возопії́м:","Ра́дуйся, Пречи́стая Ді́во, Ма́терію Спаси́теля ми́ра от ві́ка предизбра́нная."]},{"h":"Молитва перша","ps":["О, Пресвята́я Влади́чице, Христа́ Спаси́теля на́шего Богоізбра́нная Ма́ти, у Бо́га святи́ми моли́твами іспро́шенная, Бо́гу посвяще́нная і Бо́гом возлю́бленная! Кто Тебі́ не ублажи́ть іли́ кто не воспоє́ть, Твоєго́ пресла́внаго рождества́. Рождество́ бо Твоє́ бисть нача́лом спасе́нія челові́ков, і ми, сідя́щії во тьмі согріше́ній, зрим Тя, Непристу́пнаго Сві́та жили́ще. Сего́ ра́ди вити́йствующий язи́к не мо́жеть пісносло́вити Тя по достоя́нію. Па́че бо серафи́м возви́силась єси́, Пречи́стая. Оба́че прийми́ от недосто́йних раб Твої́х ни́нішнєє похвале́ніє і не отри́ни мольби́ на́шея. Твоє́ вели́чіє іспові́дуєм, Тебі́ во умиле́нії припа́даєм і ско́рую в заступле́нії чадолюби́вую і благосе́рдую Ма́тер дерзнове́нно про́сим: умоли́ Си́на Твоєго́ і Бо́га на́шего дарова́ти нам, мно́го согреша́ющим, і́скреннєє покая́ніє і благоче́стноє житіє́, да возмо́жем твори́ти вся Бо́гу уго́дная і душа́м на́шим поле́зная. Возненави́дим вся зла́я, укріпля́ємі Боже́ственною благода́тію во благо́м проізволе́нії на́шем. Ти непости́дная наде́жда на́ша в час сме́рти, да́руй нам христия́нськую кончи́ну, безбі́дноє ше́ствіє на стра́шних мита́рствах возду́шних і наслі́діє ві́чних і неізрече́нних благ Ца́рствія Небе́снаго, да со всі́ми святи́ми немо́лчно іспові́дуєм Твоє́ о нас заступле́ніє і да сла́вим єди́наго І́стиннаго Бо́га, во Святі́й Тро́йці покланя́ємаго, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва друга","ps":["Преблагослове́нная Ді́во Марі́є, Цари́це небесе́ і землі́, Твоєму́ чудотво́рному о́бразу припа́дающе, умиле́нно глаго́лем: при́зри ми́лостиво на раби́ Твоя́ і Твої́м всеси́льним хода́тайством ниспосли́ коєму́ждо потре́бная. Вся ві́рния ча́да Святи́я Це́ркви спаси́, неві́рния обрати́, заблу́ждших на путь пра́вий наста́ви, ста́рость і сла́бость сил поддержи́, ю́них во ві́рі свято́й возрасти́, му́жество ко бла́гу напра́ви, грі́шников к покая́нію приведи́ і всіх христия́н мольби́ усли́ши, боля́щих уврачу́й, ско́рби утоли́, путеше́ствующим спутеше́ствуй. Ти ві́си, Всеми́лостивая, я́ко не́мощни, я́ко грі́шнії, я́ко озлобля́ємі і недосто́йни проще́нія Бо́жия, оба́че бу́ди нам в по́мощ, да ні ко́їм гріхо́м самолю́бія, собла́зна і дия́вольськаго прельще́нія прогнівля́єм Бо́га: Тя і́мами Предста́тельницю, І́же не отри́неть Госпо́дь. А́ще бо восхо́щеши, вся дарова́ти нам мо́жеши я́ко благода́тний істо́чник, ві́рно пою́щим Ті і превознося́щим пресла́вноє Твоє́ рождество́. Ізба́ви, Влади́чице, гріхопаде́ній і бід всіх, благоче́стно призива́ющих свято́є і́м'я Твоє́ і покланя́ющихся честно́му о́бразу Твоєму́. Ти бо моли́твами беззако́нія на́ша ту́не очища́єши, ті́мже Тебе́ припа́даєм і па́ки вопіє́м: отжени́ от нас вся́каго врага́ і супоста́та, вся́кия напа́сти і губи́тельнаго неві́рія; моли́твами Твої́ми, подаю́щи дожди́ благовре́менни і земле́ оби́льноє плодоно́сіє, вложи́ в сердця́ на́ша страх Боже́ственний к ісполне́нію за́повідей Госпо́дніх, да всі ти́хо і ми́рно поживе́м во спасе́ніє душ на́ших, во бла́го бли́жніх і во сла́ву Го́спода, Єму́ бо, я́ко Творцю́, Промисли́телю і Спаси́телю на́шему вся́кая подоба́єть сла́ва, честь і поклоне́ніє, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, Пречи́стая і Преблагослове́нная Ді́во, Влади́чице Богоро́дице, от непло́дове по обітова́нію ро́ждшаяся і чистоти́ ра́ди душі́ і ті́ла Твоєго́ сподо́бльшаяся би́ти Ма́терію Си́на Бо́жия, Го́спода на́шего Ісу́са Христа́, с Ни́мже ни́ні на небесі́ пребива́єши і і́маши ве́ліє дерзнове́ніє ко Пресвято́й Тро́йце, от Нея́же, я́ко Цари́ця, вінце́м ві́чнаго ца́рствованія уві́нчана єси́. Ті́мже смире́нно к Тебі́ прибіга́єм і про́сим: ісхода́тайствуй нам у Всеми́лостиваго Го́спода Бо́га проще́ніє всіх прегріше́ній на́ших во́льних і нево́льних; стра́ждущему оте́честву на́шему спасе́нія, ми́ра, тишини́ і благоче́стія возстановле́ніє, времена́ ми́рни і безм'яте́жни, крамо́л злих неприча́стни; ко ізоби́лію же плодо́в земни́х, возду́ха благорастворе́нія, дожді́ ми́рни і благовре́менни. І вся, я́же к житію́ і спасе́нію на́шему потре́бная, іспроси́ нам у Си́на Твоєго́, Христа́ Бо́га на́шего. Найпа́че же благопоспіши́ нам украси́тися благи́ми нра́ви і до́брими ді́ли, да, єли́ко мо́щно, подража́телі бу́дем свято́му Твоєму́ житію́, і́мже от ю́ности на землі́ украша́лася єси́, благоугожда́юще Го́споду; сего́ ра́ди яви́лася єси́ честні́йшая Херуви́м і сла́внійшая Серафи́м. Єй, Госпоже́ Пресвята́я, бу́ди нам во всем ско́рая Помо́щниця і прему́драя ко спасе́нію Наста́вниця, да Тебі́ послі́дствующи і Тобо́ю воспомоществу́ємі, сподо́бимся наслі́дници би́ти Небе́снаго Ца́рствія, страда́ніями Си́на Твоєго́ ісхода́тайственнаго, ісполни́телям же святи́х за́повідей Єго́ обіща́ннаго. Ти бо єси́, Госпоже́, єди́на на́ша по Бо́зі наде́жда і упова́ніє, і Тебі́ весь живо́т наш предає́м, ча́юще Твоєго́ ра́ди хода́тайства і заступле́нія не посра́млени би́ти в час ісхо́да на́шего от житія́ сего́, і на Стра́шном Суді́ Си́на Твоєго́, Христа́ Бо́га на́шего десна́го Єго́ стоя́нія сподо́битися, і та́мо ві́чно ра́доватися со всі́ми от ві́ка Єму́ благоугоди́вшими і немо́лчно сла́вити, хвали́ти, благодари́ти і благословля́ти Єго́ со Отце́м і Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Рождество́ Твоє́, Богоро́дице Ді́во, / ра́дость возвісти́ всей вселе́нній: / із Тебе́ бо возсія́ Со́лнце пра́вди Христо́с Бог наш, / і, разруши́в кля́тву, даде́ благослове́ніє, // і, упраздни́в смерть, дарова́ нам живо́т ві́чний."]},{"h":"Кондак, глас 4","ps":["Іоаки́м і А́нна поноше́нія безча́дства, / і Ада́м і Є́ва от тлі сме́ртния свободи́стася, Пречи́стая, / во святі́м рождестві́ Твоє́м. / То пра́зднують і лю́діє Твої́, / вини́ прегріше́ній ізба́вльшеся, / внегда́ зва́ти Ті: // непло́ди ражда́єть Богоро́дицю і пита́тельницю Жи́зні на́шея."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим святи́х Твої́х роди́телей, і всесла́вноє сла́вим Рождество́ Твоє́."]},{"h":"Задостойник","ps":["Велича́й, душе́ моя́, / пресла́вноє рождество́ Бо́жия Ма́тере.","Чу́жде ма́терем ді́вство / і стра́нно ді́вам діторожде́ніє; / на Тебі́, Богоро́дице, / обоя́ устро́їшася. / Тім Тя, вся племена́ земна́я, // непреста́нно велича́єм."]}],"notes":[]},{"u":"Акафіст Святій Пасхі","e":"Akathist to Holy Pascha","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от дній — сей нарече́нний і святи́й день, пра́здников Пра́здник і Торжество́ єсть торже́ств, во́ньже Христо́с воскре́се тридне́вен от гро́ба, ад пліни́вий і челові́ки воскреси́вий, Єго́ же прославля́юще да зове́м всі:","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Ікос 1","ps":["А́нгели, Христе́ Спа́се, днесь пою́ть на небесі́х Твоє́ із ме́ртвих Воскресе́ніє, і нас на землі́ сподо́би чи́стим се́рдцем Тебі́ с ра́достію сла́вити і пі́ти:","Христо́с воскре́се, — А́нгели ликовству́йте на небесі́.","Христо́с воскре́се, — лю́діє торжеству́йте на землі́.","Христо́с воскре́се, — воскли́кніте Го́сподеві вся земля́.","Христо́с воскре́се, — воспо́йте Бо́гу на́шему но́вую піснь.","Христо́с воскре́се, — пра́ведници днесь да возвеселя́ться.","Христо́с воскре́се, — врата́ а́дови днесь да расточа́ться.","Христо́с воскре́се, — смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 2","ps":["Ви́дівше воскре́сшаго Си́на Своєго́ і Бо́га, Богоблагода́тная Чи́стая, Єди́на до́брая в жена́х і Непоро́чная, і є́же ра́дуйся сли́шавши от Него́ пе́рвая, всіх ра́дость восприя́, Богома́ти Всенепоро́чная, і ра́дующеся, в се́рдці своє́м возгласи́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мно небеса́ да веселя́ться, земля́ же да ра́дується, да пра́зднуєть же мир весь, ви́димий же і неви́димий, воста́ніє Христо́во, пою́ще Єму́:","Христо́с воскре́се, — весе́ліє ві́чноє.","Христо́с воскре́се, — ско́рби уже́ да не бу́деть ктому́.","Христо́с воскре́се, — да пра́зднуєть у́бо вся твар.","Христо́с воскре́се, — вся поднебе́сная да ра́дується с на́ми.","Христо́с воскре́се, — днесь спасе́ніє ми́ру.","Христо́с воскре́се, — днесь Со́лнце кра́сноє із гро́ба всім возсія́.","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственною Ада́ма пра́отця спаси́й, сме́ртноє жили́ще Своє́ю сме́ртію днесь разори́, і вся Боже́ственними блиста́ньми Воскресе́нія озари́, возбуди́л єси́ ме́ртвия от ві́ка, Христе́ Спа́се наш, нача́ток усо́пшим бив, да сли́шить от всіх: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я безмі́рноє благоутро́біє, снисшедий с небесі́ і воплоти́вийся па́че ума́, Христо́с Бог наш сни́де в преіспо́дняя землі́, і воздви́же с Собо́ю Ада́ма, і всі а́довими у́зами содержи́мії зря́ще, к сві́ту ідя́ху, Христе́, весе́лими нога́ми, Па́сху хва́ляще ві́чную си́це:","Христо́с воскре́се, — гді твоя́, а́де, побі́да?","Христо́с воскре́се, — гді твоє́, сме́рте, жа́ло?","Христо́с воскре́се, — ме́ртвий ні єди́н во гро́бі.","Христо́с воскре́се, — жизнь да жи́тельствуєть ни́ні.","Христо́с воскре́се, — пліни́ся ад, дерза́йте ме́ртвії.","Христо́с воскре́се, — гро́би отверзо́шася, возстаніте от а́да.","Христо́с воскре́се, — смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 4","ps":["Бу́ря ско́рби уже́ ни́ні преста́, же́нський же лик со арома́ти притече́ зіло́ зау́тра ко гро́бу Жизнода́вця, взиску́юще пре́жде со́лнця Со́лнце заше́дшеє іногда́ во гроб, пречи́стаго же ті́ла Твоєго́, Христе́, не обріто́ша глаго́лаху: кто взят ме́ртва, на́га і погребе́нна? Світоно́снаго же А́нгела зря́ще на гро́бі седяша, со стра́хом возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаху от А́нгела мироно́сиці ді́ви: Что іщі́те Жива́го с ме́ртвими? Что пла́чіте Нетлі́ннаго во тлі? Ра́дующеся же, поклони́шася Живо́му Бо́гу, Па́сху та́йную уразумі́вше, і дру́га ко друзі́й вопія́ху ве́село:","Христо́с воскре́се, — Па́сха ве́лія нам днесь возсія́.","Христо́с воскре́се, — рида́нія вре́м'я нам ни́ні преста́.","Христо́с воскре́се, — днесь Є́вино осужде́ніє разріши́ся.","Христо́с воскре́се, — днесь плач наш, на ра́дость преложи́ся.","Христо́с воскре́се, — вмі́сто ми́ра піснь принесе́м Влади́ці.","Христо́с воскре́се, — вмі́сто слез — очи́стим чу́вствія і Єго́ у́зрим.","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 5","ps":["Боголі́пно воскре́сшу Христу́ із ме́ртвих, Магдали́на Марі́я притече́ ко гро́бу Жизнода́вця, ви́дів же, я́ко ка́мень отвале́н бі от гро́ба, с пла́чем глаго́ла сідя́щим А́нгелом: Гді у́бо скри́ся Ві́чний Живо́т? Іли́ Го́спода моєго́ даді́те, іли́ со мно́ю Єму́же всі с ві́рою возопи́йте: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше Христа́ Магдали́на у гро́ба, я́ко вертогра́даря, Того́ вопроси́ глаго́ля: Пові́ждь мі, гді положи́л єси́ Єго́, да аз возьму Єго́? Позна́вше же Воскресе́ніє Твоє́, Христе́, всему́ ми́ру та́ко благовісти́:","Христо́с воскре́се, — жени́ преста́ніте от слез.","Христо́с воскре́се, — ді́ви вни́діте в ра́дость Го́спода своєго́.","Христо́с воскре́се, — Апо́столи ра́достію Боже́ственною взигра́йте.","Христо́с воскре́се, — лю́діє всі насладі́теся сего́ до́браго торжества́.","Христо́с воскре́се, — пе́рвії і послі́днії день почті́те.","Христо́с воскре́се, бога́тії і убо́зії друг с друго́м лику́йте.","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 6","ps":["Пропові́дници ді́ви ді́вственнику благовісти́, я́ко Жизнода́вець Госпо́дь днесь от гро́ба возсія́. То́йже, ско́ро возста́в, притече́ ко гро́бу скорі́є Петра́ і прини́к внутр, ви́ді ри́зи єди́ни лежа́щия. І вни́де во гроб і ви́ді і ві́рова. І єще́ не ви́дів Христа́ тіле́снима очи́ма, уви́ді Єго́ серде́чною любо́вію і с ві́рою возопи́ Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ Христо́с із гро́ба, яви́ся пре́жде жена́м, я́ко те́плую любо́в яви́ша Єму́ у Креста́. Ви́дів же Петра́, в ско́рбі ко гро́бу прише́дша, яви́ся Єму́, я́ко милосе́рд, пре́жде други́х учени́к. Той же ра́дости неізрече́нния іспо́лнився, всему́ ми́ру та́ко благовісти́:","Христо́с воскре́се, — днесь падшим подаде́ся воскресе́ніє.","Христо́с воскре́се, — днесь всему́ ми́ру возвісти́ся спасе́ніє.","Христо́с воскре́се, — днесь о́вці заблу́ждшия ко Па́стирю возвраті́теся.","Христо́с воскре́се, — днесь лю́діє Бо́жії от печа́лі свободітеся.","Христо́с воскре́се, — ра́дуйтеся всі ра́достію неізрече́нною.","Христо́с воскре́се, — цілу́йте друг дру́га лобза́нієм святи́м.","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 7","ps":["Хотя́й Жизнода́вець Госпо́дь іспо́лнити весь мир ра́дости Воскресе́нія своєго́, посла́ жени́ возвісти́ти Апо́столом, я́ко возста́ умертви́вий смерть, ті́ї же А́нгели сві́тлостію душ удививше, весе́лими нога́ми ко Апо́столом теча́ху, глаго́люще: Воі́стину Христо́с воскре́се і живе́ть во ві́ки, с ра́достію воспо́йте Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вную ра́дость Воскресе́нія Твоєго́, Христе́, Апо́столи от святи́х жен с ра́достію восприя́вше, я́ко во́лею за всіх закла́н бил єси́, живо́є і же́ртвенноє заколе́ніє, я́ко єдинолі́тний а́гнець, Па́сха чисти́тельная, і та́ко всему́ ми́ру благовісти́ша:","Христо́с воскре́се, — Но́вая Па́сха.","Христо́с воскре́се, — Же́ртва жива́я.","Христо́с воскре́се, — А́гнець Бо́жий взе́мляй гріхи́ ми́ра.","Христо́с воскре́се, — я́звою Своє́ю всіх ісціли́вий.","Христо́с воскре́се, — днесь вся́ка твар весели́ться і ра́дується.","Христо́с воскре́се, — днесь Це́рков Бо́жия торжеству́єть і пра́зднуєть.","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 8","ps":["Стра́шноє та́їнство і пресла́вноє Воскресе́нія Твоєго́, Христе́, я́ко возста́в от ме́ртвих, не разруши́л єси́ печа́тей гро́ба, я́ко же врата́ Ді́ви не разве́рзл єси́ в Рождестві́ твоє́м. Ни́ні же во Воскресе́нії Своє́м отве́рзл єси́ нам ра́йськія врата́, да с разбо́йником вни́дем с Тобо́ю в Черто́г, пою́ще Тебі́, я́ко Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім ві́рним, Христе́, Па́сха Свяще́нная нам днесь возсія́, і всім отве́рзл єси́ нам ра́йськія врата́, да всі по́йдем к сві́ту Воскресе́нія Твоєго́, я́ко Богосві́тлая світи́ла, от за́пада, сі́вера і ю́га, і восто́ка ча́да Твоя́, Па́сху благослов'я́ще ві́чную та́ко:","Христо́с воскре́се, — проще́ніє от гро́ба нам всім возсія́.","Христо́с воскре́се, — ізбавле́ніє от ско́рби всім ві́рним наста́.","Христо́с воскре́се, — всі насладі́теся сего́ пи́ра ві́ри.","Христо́с воскре́се, — всі восприймі́те бога́тство благода́ті.","Христо́с воскре́се, — нікто́же да пла́четь прегріше́ній.","Христо́с воскре́се, — нікто́же да убої́ться сме́рті.","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 9","ps":["Вся ни́ні іспо́лнишася сві́та, не́бо же і земля́ і преіспо́дняя: не́бо, я́ко восхо́дить ко Отцю́ Жизнода́вець Госпо́дь, земля́-же, я́ко возсія́ із гро́ба Со́лнце кра́сноє днесь, преіспо́дняя-же, я́ко сни́де в та́мо су́щий мрак Єдиноро́дний Бо́жий Син, вся ісполня́яй неопи́санний. Да поклони́ться Єму́ вся земля́, да пра́зднуєть возста́ніє Єго́ вся твар, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я Боже́ственний Іса́їя да ста́неть с на́ми і пока́жеть, ка́ко предзре світоно́сний день Воскресе́нія Твоєго́, я́сно глаго́люще о Тебі́, Христе́: Поже́рта бу́деть смерть побі́дою і воскре́снуть ме́ртвії і возста́нуть, і́же во гробі́х. Ми же, образо́в сбитіє́ зря́ще, веселі́мся боже́ственні, пою́ще Тебі́:","Христо́с воскре́се, — днесь сме́рти пра́зднуєм умерщвле́ніє.","Христо́с воскре́се, — днесь ві́чнаго житія́ возвіща́єм нача́ло.","Христо́с воскре́се, — днесь весна́ благоуха́єть і но́вая твар лику́єть.","Христо́с воскре́се, — днесь отгна́ся мра́чная бу́ря гріха́ і новиє лю́діє церко́внії торжеству́ють.","Христо́с воскре́се, — дре́вняя мимоідо́ша, і се би́ша вся но́ва.","Христо́с воскре́се, — не́бо днесь отве́рсто і у́зрить вся́ка плоть Лице́ Єго́.","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й вся́чеськая, с на́ми нело́жно обіща́лся єси́ би́ти, Христе́, до сконча́нія ві́ка сего́. Сему́ Боже́ственному Твоєму́ гла́су вне́млюще, утвержде́ніє же наде́жди іму́ще, ра́дуємся Воскресе́нію Твоєму́, пою́ще Тебі́ я́ко Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Христа́ узрі́в із гро́ба я́ко Жениха́ проісходя́ща, жени́ с ми́ри богому́дрия вслід Тебе́ теча́ху. Ми же свіщи́ нося́ще, ізи́дем во срі́теніє Жениху́ і спра́зднуєм с любопра́зднственними чи́ньми Па́сху Бо́жию спаси́тельную, я́сно глаго́люще Єму́ си́це:","Христо́с воскре́се, — ісході́те, я́ко ді́ви, во срі́теніє Жениху́.","Христо́с воскре́се, — гряді́те свіщено́снії, со світи́льники ко Христу́.","Христо́с воскре́се, — іспо́лніте душі́ ва́ші Боже́ственния красоти́.","Христо́с воскре́се, — возжгите свіщи́ своя́ от єле́я чистоти́.","Христо́с воскре́се, — возвеселі́мся Боже́ственно я́ко с на́ми Жени́х.","Христо́с воскре́се, — возра́дуємся пресві́тло, я́ко угото́вися неві́сті Черто́г.","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 11","ps":["Пі́ніє всера́достноє вмі́сто ми́ра днесь принесе́м і всепра́зднственноє настоя́щеє торжество́ соверши́м в сію́ свяще́нную і спаси́тельную і світоза́рную нощ, в не́йже безлі́тний Світ із гро́ба пло́тськи всім возсія́, ю́же, я́ко провозвестницю світоно́снаго дне невече́рняго Ца́рствія Твоєго́, Христе́, ублажа́єм і поє́м, вопію́ще Тебі́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ неізмеримий всем во тьмі сидящим нам днесь возсія́ па́че со́лнця світлі́є із гро́ба Твоєго́, Христе́, вселе́нную всю просвіти́, сего́ ра́ди лику́ють ми́ра конці́, веселя́щеся же поє́ть Христо́ва Це́рков, прославля́юще Воскресе́ніє Твоє́:","Христо́с воскре́се, — воі́стину свяще́нна і світоза́рна сія́ спаси́тельная нощ!","Христо́с воскре́се, — воі́стину пра́здников пра́здник сей нарече́нний і святи́й день!","Христо́с воскре́се, — лику́й ни́ні і весели́ся Сіо́не Святи́й.","Христо́с воскре́се, — світи́ся і красу́йся ни́ні Це́рков Бо́жия.","Христо́с воскре́се, — сла́ва бо Госпо́дня на Тебі́ возсія́.","Христо́с воскре́се, — ра́дость ві́чная іспо́лни вся ча́да Твоя́.","Христо́с воскре́се, — смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 12","ps":["Благода́ть весе́лую Твою́, Христе́, всім ві́рним ту́не істочи́л єси́ днесь в нарочи́тий день Воскресе́нія Твоєго́, єго́же пресла́вно сотвори́л єси́. Прийді́те возра́дуємся і возвеселі́мся в онь, Боже́ственнаго весе́лія Ца́рствія Христо́ва приобщі́мся, пою́ще Єму́, я́ко Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще всесві́тлоє Твоє́, Христе́, Воскресе́ніє, поклоні́мся Тебі́ Воскре́сшему, і с ві́рою і любо́вію к Твої́м стопа́м припаде́м і єди́ними усти́ Тебі́, я́ко бра́тія, возопіє́м:","Христо́с воскре́се, — ра́достію друг дру́га оби́мем.","Христо́с воскре́се, — і ненавидящим нас прості́м.","Христо́с воскре́се, — вся чу́вствія внутр себі́ очи́стим.","Христо́с воскре́се, — лобза́єм друг дру́га лобза́нієм святи́м.","Христо́с воскре́се — во двори́ Твоя́ с пі́нієм вни́дем.","Христо́с воскре́се — в до́му Твоє́м во вся сві́тлия дні пребу́дем.","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 13","ps":["О, Па́сха Ве́лія і свяще́ннійшая, Христе́, о, Му́дросте і Сло́ве Бо́жий і Си́ло! Вмі́сто ми́ра піснь сію́ на́шу прийми́, і я́ко Бог Крі́пкий совозста́ви нас і обожи́, да сподо́бимся і́стіє Тебе́ причаща́тися в невече́рнім дні Ца́рствія Твоєго́ на небесі́ і та́мо со всі́ми святи́ми воспіва́ти Тебі́ бу́дем: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели, Христе́ Спа́се, днесь пою́ть на небесі́х Твоє́ із ме́ртвих Воскресе́ніє, і нас на землі́ сподо́би чи́стим се́рдцем Тебі́ с ра́достію сла́вити і пі́ти:","Христо́с воскре́се, — А́нгели ликовству́йте на небесі́.","Христо́с воскре́се, — лю́діє торжеству́йте на землі́.","Христо́с воскре́се, — воскли́кніте Го́сподеві вся земля́.","Христо́с воскре́се, — воспо́йте Бо́гу на́шему но́вую піснь.","Христо́с воскре́се, — пра́ведници днесь да возвеселя́ться.","Христо́с воскре́се, — врата́ а́дови днесь да расточа́ться.","Христо́с воскре́се, — смерть попра́вий, лю́діє веселі́теся."]},{"h":"Кондак 1","ps":["Ізбра́нний от дній — сей нарече́нний і святи́й день, пра́здников Пра́здник і Торжество́ єсть торже́ств, во́ньже Христо́с воскре́се тридне́вен от гро́ба, ад пліни́вий і челові́ки воскреси́вий, Єго́ же прославля́юще да зове́м всі:","Христо́с воскре́се, смерть попра́вий, лю́діє веселі́теся."]},{"h":"Молитва","ps":["О, Свяще́ннійший і Велича́йший Сві́ті Христе́, Возсія́вий всему́ ми́ру па́че со́лнця во Воскресе́нії Твоє́м! В сей пресві́тлий і пресла́вний і спаси́тельний день Святи́я Па́схи, лику́ють всі а́нгели на небесі́ і вся́ка твар весели́ться і ра́дується на землі́ і вся́коє диха́ніє прославля́єть Тя, Творця́ своєго́. Днесь отверзо́шася ра́йськия врата́, і свободи́шася умершія во ад соше́ствієм Твої́м. Ни́ні вся іспо́лнишася сві́та, не́бо же земля́ і преіспо́дняя. Да при́йдеть у́бо Твой світ і в на́ші мра́чния душі́ і се́рдця і да просвіти́ть на́шу та́мо су́щую нощ гріха́, да і ми сія́ти бу́дем сві́том пра́вди і чистоти́ в пресві́тлия дні Воскресе́нія Твоєго́, я́ко же но́вая твар о Тебі́. І та́ко просвіще́ннії Тобо́ю ізи́дем свіщено́снії во сретенії Твоє́, ісходя́щему Тебі́ із гро́ба, я́ко Жениху́. І я́ко возвесели́л єси́ в пресві́тлий день сей явле́нієм Свої́м святи́х дів зіло́ зау́тра с ми́ри ко гро́бу Твоєму́ прише́дших, та́ко і ни́ні просвіти́ нощ глубо́кую страсте́й на́ших і возсія́й нам у́тро безстра́стія і чистоти́, да у́зрим Тя серде́чними очеси́ кра́снаго па́че со́лнця Жениха́ своєго́ і да усли́шим па́ки вожделі́нний глас Твой: Ра́дуйтеся!"]},{"h":"Тропар, глас 5","ps":["Христо́с воскре́се із ме́ртвих, / сме́ртію смерть попра́в, // і су́щим во гробі́х живо́т дарова́в."]},{"h":"Кондак, глас 8","ps":["А́ще і во гроб снизше́л єси́ Безсме́ртне, / но а́дову разруши́л єси́ си́лу, і воскре́сл єси́ я́ко побіди́тель Христе́ Бо́же, / жена́м мироно́сицям віща́вий, ра́дуйтеся: / і Твої́м апо́столом мир да́руяй, // па́дшим подая́й воскресе́ніє."]},{"h":"Задостойник, глас 1","ps":["А́нгел вопія́ше Благода́тній: Чи́стая Ді́во, ра́дуйся! І па́ки реку́: ра́дуйся! Твой Син воскре́се тридне́вен от гро́ба, і ме́ртвия воздви́гнувий: лю́діє, веселі́теся.","Світи́ся, світи́ся, но́вий Ієрусали́ме: сла́ва бо Госпо́дня на тебі́ возсія́. Лику́й ни́ні і весели́ся, Сіо́не. Ти же, Чи́стая, красу́йся, Богоро́дице, о воста́нії Рождества́ Твоєго́."]}],"notes":[]},{"u":"Акафіст Святому Духу","e":"Akathist to the Holy Spirit","secs":[{"h":"Кондак 1","ps":["Прийді́те, ві́рнії, Ду́ха Свята́го просла́вим соше́ствіє, І́же от Оте́чеських нідр на апо́столов ізли́вся я́ко вода́ми, богові́дінієм покри́ зе́млю, і живоно́сния благода́ті богоусиновле́нія, і го́рнія сла́ви сподобля́єть чи́сті притека́ющих к Нему́, освяща́єть же і обожа́єть зову́щих:","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Ікос 1","ps":["А́нгели на небесі́ сві́тлими хора́ми Ду́ху Свято́му несмолка́ємо сла́ву пою́ть, я́ко Істо́чнику жи́зні і Сві́ту невеще́ственному, боже́ственними мо́лніями мир просвіща́ющему. С ни́ми же і ми прославля́єм Тя, Ду́ше непостижи́мий, за вся я́вния і та́йния ми́лості Твоя́, і смире́нно про́сим блаже́ннаго осіне́нія Твоєго́:","Прийди́, Сві́те і́стинний і Ра́досте духо́вная;","прийди́, росоно́сний О́блаче і Красото́ неізрече́нная.","Прийди́, і прийми́ я́ко куре́ніє благово́нноє хвалу́ на́шу;","прийди́, і даждь нам вкуси́ти ра́дость явле́нія Твоєго́.","Прийди́, і сотвори́ сей день днем милосе́рдія Твоєго́;","прийди́, і возвесели́ нас оби́лієм даро́в Твої́х.","Прийди́, Свя́тость безмі́рная, і вся́ку скве́рну дале́че от нас отжени́;","прийди́, ві́чноє со́лнце незаходи́моє, і оби́тель Твою́ в нас сотвори́.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 2","ps":["Виді́нієм о́гненних язи́ков, во сві́ті і диха́нії бу́рнім і радостотво́рнем сни́де Дух Святи́й на апо́столов. Пла́менем Єго́ об'я́тії, ри́бари мир весь в Це́рков Христо́ву призва́ша, бі́ди на су́ші і вода́х ра́достно те́рп'яще, лю́тих смерте́й не убоя́шася, і во всю зе́млю ізи́де віща́ніє їх: Аллилу́я."]},{"h":"Ікос 2","ps":["Ча́ша дождеро́дно огнеточи́вая, ізли́вшаяся на апо́столов в го́рниці Сіо́нстій: Тебі́ поє́м, Тебе́ благослови́м, Тебі́ благодари́м, Бо́же Ду́ше Святи́й, низпосли́ і на нас Прему́дрость Твою́:","Прийди́, Освяти́телю і Храни́телю Це́ркві;","прийди́, і даждь єди́но се́рдце і єди́ни уста́ ві́рним Твої́м.","Прийди́, і воспламени́ на́ше хла́дноє і безпло́дноє благоче́стіє;","прийди́, і разжени́ огустіва́ющий над земле́ю мрак безбо́жия і нече́стія.","Прийди́, і даждь нам вкуси́ти, я́ко Благ єси́;","прийди́, і наста́ви нас на вся́ку і́стину.","Прийди́, і вся помишле́нія на́ша поко́ри влади́честву Твоєму́;","прийди́, Му́дросте непостижи́мая, і Є́юже ві́си судьба́ми спаси́ нас.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 3","ps":["Та́йна глубоча́йшая, Бо́же Ду́ше непостижи́ме, со Отце́м і Сло́вом Созда́телю всіх! Ти укра́сил єси́ го́рнія чини́ а́нгелов во хра́мі непристу́пнаго сві́та, Ти воззва́л к битію́ хо́ри о́гненних світи́л с великолі́пієм сла́ви, Ти, плоть і дух в чу́дноє єди́нство согласу́я, сотвори́л єси́ род челові́чеський, і вся́коє диха́ніє поє́ть Тебі́ хвалу́: Аллилу́я."]},{"h":"Ікос 3","ps":["А́льфа і оме́га, нача́ло і коне́ць Ти, Ду́ше ві́чний, необ'я́тною си́лою паре́нія над вода́ми і стра́шним кругообстоя́нієм животвори́л єси́ всіх і вся. От живоно́снаго диха́нія Твоєго́ із безви́дния бе́здни возсія́ла єсть неізрече́нная красота́ первозда́ннаго ми́ра. Сего́ ра́ди взива́єм Ті:","Прийди́, Вели́кий і в ма́лом цветке́, і в небе́сній звізді́;","прийди́, вся́ким диха́нієм на небесі́ і на землі́ Хвали́мий.","Прийди́, Сокро́вище многообра́зних даро́в неісчерпа́ємоє і Красото́ ві́чная;","прийди́, і озари́ мра́чний ха́ос моєя́ душі́.","Прийди́, і благода́тію Твоє́ю сі́м'я жи́зні духо́вния оживи́ в нас;","прийди́, і ду́хом сві́та і крі́пости коле́блющеєся проізволе́ніє на́ше утверди́.","Прийди́, і в сві́тлий о́браз Твой устро́й мра́чноє безобра́зіє душі́ моєя́;","прийди́, і яви́ нас но́вою тва́рію во Христі́.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 4","ps":["Непостижи́мий і Всеблаги́й! Ти обле́кл єси́ Пречи́стую Ді́ву Марі́ю в ослепи́тельний і непристу́пний блеск Твоєго́ Божества́, соді́лав Ма́терію Бо́га, Цари́цею а́нгелов, спасе́нієм люде́й! Си́лою преми́рною Ти возно́сиши їх до тре́тіяго небесе́! Ти уязвля́єши їх сердца́ красото́ю Небе́сною, влага́я в їх рі́чі жгу́чеє стремле́ніє, влеку́щеє люде́й к Бо́гу. Ти обраща́єши послі́дніх грі́шников, і по́лниє го́рняго восто́рга, пою́ть они́ Тебі́: Аллилу́я."]},{"h":"Ікос 4","ps":["Святи́м Ду́хом вся́ка душа́ живи́ться, Єго́ си́лою возстано́в'яться к обще́нію воскресе́нія вся созда́нія в послі́дній час ни́нішняго ві́ка і в пе́рвий бу́дущаго. Тогда́ воздви́гни нас із гробо́в, не к осужде́нію, но к Боже́ственному блаже́нству со всі́ми святи́ми і с бли́зькими нам:","Прийди́, і ізба́ви нас от сме́рти духо́вния;","прийди́, і даждь нам всегда́ па́м'ять сме́ртную.","Прийди́, і пред кончи́ною наси́ти нас Ті́лом і Кро́вію Христа́;","прийди́, і даждь нам успе́ніє ти́хоє і с чи́стою со́вістію.","Прийди́, і сотвори́ сві́тлим на́ше пробужде́ніє от сме́ртнаго сна;","прийди́, і бу́ди с на́ми, єгда́ предста́нем о́ному Стра́шному Судії́.","Прийди́, і сподо́би нас уви́дити с ра́достію лику́ющеє У́тро ві́чності;","прийди́, і я́ко со́лнце просвіти́ тогда́ безсме́ртная тілеса́ на́ша.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 5","ps":["Усли́шав глас Твой: а́ще кто жа́ждеть, да гряде́ть ко Мні і да піє́ть, мо́лим Тя, Си́не Бо́жий, утоли́ на́шу духо́вную жа́жду, даждь нам во́ду живу́ю, ізле́й нам от Ду́ха Свята́го Твоєго́, да не возжа́ждем во ві́ки, со умиле́нієм пою́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Нетлі́нний і несотворе́нний, ві́чний і ще́дрий Ду́ше, пра́ведних храни́телю і грі́шних очище́ніє, свободи́ нас от вся́ких нечи́стих діл, да не пога́снеть в нас сія́ніє благода́тнаго сві́та Твоєго́, вопію́щих Ті:","Прийди́, Всеблаги́й, і даждь нам умиле́ніє і істо́чник слез;","прийди́, і научи́ нас покланя́тися Тебі́ Ду́хом і І́стиною.","Прийди́, І́стині ві́чная, і уясни́ недоумі́нія ума́ на́шего ску́днаго;","прийди́, Жизнь нестаре́ємая, і отжени́ от нас прельще́нія кра́ткаго ві́ка сего́.","Прийди́, Сві́те незаходи́мий, і разсі́й мрак страсте́й на́ших і уни́нія;","прийди́, ві́чно ю́ная Си́ло, освежи́ ізнемога́ющих чад Твої́х.","Прийди́, безконе́чная Ра́досте, і забу́дуться невзго́ди вре́менния;","прийди́, і ізсо́хшую зе́млю душ на́ших плодоно́сну покажи́.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 6","ps":["Лику́й, дщер Сві́та, свята́я Ма́ти Сіо́н, украша́йся, вели́кая Неві́сто, Небесі́ подо́бная сві́тло блиста́ющая вселе́нськая Це́рков Христо́ва, на Тебі́ почива́єть Дух Святи́й, немощна́я врачу́я, оскудіва́ющая восполня́я і ме́ртвия Ду́хом оживля́я, і к ві́чной жи́зні приводя́ всіх, досто́йно і пра́ведно о Тебі́ зову́щих: Аллилу́я."]},{"h":"Ікос 6","ps":["В ми́рі ско́рбни бу́дете, рече́ Госпо́дь. Гді обря́щем Отра́ду, і Кто уті́шить нас? Ду́ше Уті́шителю, Ти утоли́ на́ша печа́лі, хода́тайствуй о нас воздиха́нії неізрече́нними, облегчи́ сердця́ моля́щихся Тебі́:","Прийди́, сла́дкая Прохла́до тружда́ющихся і обремене́нних;","прийди́, Собесі́дниче у́зников і Спу́тниче гони́мих.","Прийди́, Пи́ще а́лчущих і нището́ю ізнуре́нних;","прийди́, Приста́нище си́рим і вдов Утіше́ніє.","Прийди́, і уврачу́й стра́сті душ і тіле́с на́ших;","прийди́, і посіти́ всіх жа́ждущих Твоєго́ озаре́нія.","Прийди́, і поддержи́ безпо́мощних і сла́бих;","прийди́, і научи́ нас в привре́менних ско́рбіх обріта́ти наде́жду ві́чния ра́дости.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 7","ps":["На Свята́го Ду́ха хули́вшему не прости́ться ні в сем ві́ці, ні в бу́дущем, рече́ Госпо́дь. Сли́шаще сіє́ трепе́щем, да не осу́димся с непослу́шними Тебі́ і богобо́рними; не уклони́ сердця́ на́ша в словеса́ лука́вствія, обрати́ от раско́лов, єресе́й і безбо́жия всіх заблу́ждших, і в Це́ркві Пе́рвенець сподо́би во ві́ки віко́во воспіва́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Єгда́ отступи́л Дух Святи́й от Сау́ла, тогда́ страх і уни́ніє пости́же єго́, і тьма отча́янія низве́рже єго́ в преіспо́днюю. Та́ко і аз в день уни́нія і ожесточе́нія моєго́ да разумі́ю, я́ко ність во мні Бо́га, но даждь мні неосла́бно зва́ти Тя, душі́ моєя́ Отра́до, до́ндеже світ Твой озаря́єть м'я малоду́шнаго:","Прийди́, і не отве́ржи мене́ за ропта́ніє і нетерпі́ніє моє́;","прийди́, і умиротвори́ лю́тую бу́рю см'яте́нія і раздраже́нія.","Прийди́, і успоко́й озло́бленних жите́йськими невзго́дами;","прийди́, і см'я́гчи се́рдце в день ожесточе́нія і гні́ва.","Прийди́, і обле́гчи со́гбенних тя́жестію креста́;","прийди́, і сокруши́ ко́зні смуще́нія і страхова́нія духо́в тьми.","Прийди́, і возсія́й нам Світ Твой благи́й;","прийди́, і вдохни́ в нас великоду́шіє, да терпі́нієм спасе́м ду́ші на́ша.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 8","ps":["Спаси́ нас, О́тче Небе́сний! Ми несча́стни і жа́лки, і слаби́, і на́ги духо́вно; да́руй нам зла́то Твоє́, огне́м очи́щенноє, покри́й нас от сра́ма оде́ждою бі́лою, ісціли́ пома́занієм Твої́м о́чі на́ша, благода́ть животворя́щаго Твоєго́ Ду́ха да сни́деть в нечи́стії сосу́ди душ на́ших, і возроди́ть пою́щих: Аллилу́я."]},{"h":"Ікос 8","ps":["Я́ко Вавило́нськая ба́шня ру́шиться сча́стье земно́є, жа́лки вся начина́нія челові́чеськія! Бла́го мні, я́ко смири́л м'я єси́, я́ко откри́л єси́ мні в согріше́ніїх і паде́ніїх мої́х всю сла́бость і нічто́жество моє́! Без Тебе́ не мо́жем твори́ти нічесо́же, но благода́тію Твоє́ю упова́єм спасти́ся:","Прийди́, Прему́дрий Строї́телю жи́зні;","прийди́, да разумі́єм і ми спаси́тельния путі́ Твоя́.","Прийди́, я́ко мо́лнія, і освіти́ ціль на́шего битія́;","прийди́, і благослови́ вся́коє благо́є начина́ніє.","Прийди́, і бу́ди Помо́щником в до́брих діла́х;","прийди́, озаря́я в час недоумі́нний.","Прийди́, да́руя дух покая́нія, да отвратя́ться тім гряду́щия на мир бі́ди;","прийди́, і научи́ нас при́сно твори́ти во́лю Твою́.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 9","ps":["Та́ко возлюби́ Бог мир, я́ко і Си́на Своєго́ Єдиноро́днаго дал єси́, І́же от Ду́ха Свята́го і Марі́ї Ді́ви вочелові́чився, кро́вію Своє́ю весь мир іскупи́л, на Кресті́ простира́я Зижди́тельния ру́ци до звізд; ті́мже всю твар свободи́, чад Бо́жиїх соді́ла. Сего́ ра́ди Отцю́ Возлю́бленному, Си́ну Іскупи́вшему і Ду́ху Освяща́ющему поє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Дух Животворя́щий, я́ко го́луб соше́дий на Христа́ во Іорда́ні, опочи́л єсть і на мні при купі́лі креще́нія, но помрачи́ся добро́та Єго́ от тьми гріхопаде́ній мої́х. Я́ко пу́тник заблу́ждшийся но́щію в лесу́ ожида́єть зари́, та́ко і аз жа́жду луче́й Твої́х, Бла́же, да не поги́бну до конця́:","Прийди́ ко мні, запечатле́нному стра́шним і великоле́пим і́менем Твої́м;","прийди́, і даждь мі зрі́ти моя́ прегріше́нія.","Прийди́, і обле́гчи со́вість му́чимую, неща́дно пали́мую;","прийди́, обнови́ омраче́нний Твой о́браз.","Прийди́, і разсі́й гріхо́вная виді́нія;","прийди́, і научи́ сострада́ти чужде́му го́рю.","Прийди́, і подви́гни м'я люби́ти вся́коє созда́ніє Твоє́;","прийди́, і возда́ждь мі Ра́дость Спасе́нія Твоєго́.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 10","ps":["Дух Святи́й возражда́єть в жизнь ві́чную, Дух Святи́й вдохновля́єть му́чеников, вінча́єть пра́ведников, связу́єть соста́в Церко́вний, хліб і вино́ соверша́єть Ті́лом і Кро́вію боже́ственними. О Глубино́ бога́тства і прему́дрости Бо́жієй! Да́руй нам Віне́ць Твої́х даро́в, всепроща́ющую ві́чную Любо́в, скорб'я́щую за враго́в, хотя́щую всім спасти́ся, да озаре́ннії Є́ю, я́ко ча́да Сві́та поє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Кто нас отлучи́ть от Любве́ Бо́жієй? Скорб ли, іли́ тіснота́, і́ли гоне́нія, і́ли глад, і́ли нагота́, і́ли бі́ди, іли́ меч? А́ще і всего́ лиші́мся на землі́, і́мами наслі́діє неув'яда́ємоє на небесі́. Но да́руй нам, Го́споди, люби́ти Тя не сло́вом і́ли язи́ком, но і́стинним ді́лом і по́двигом всея́ жи́зні:","Прийди́, Ду́ше всеси́льний, і умно́жи в нас всепобежда́ющую ві́ру;","прийди́, і даждь нам непреста́нноє горе́ніє моли́твенноє.","Прийди́, да не охладе́єть любо́в на́ша в среді́ беззако́нія;","прийди́, і не даждь нам отпа́сть во дні гоне́нія і посмія́нія ві́ри.","Прийди́, і сохрани́ нас от непоси́льних іскуше́ній і собла́знов;","прийди́, і оживи́ сердця́ на́ша кропле́нієм Роси́ Твоєя́.","Прийди́, і непости́дноє упова́ніє на ми́лость і по́мощ Бо́жию всели́ в нас;","прийди́, уврачу́й, освяти́ і возста́ви нас, Бла́же, Твоє́ю благода́тію.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 11","ps":["Та́ко глаго́леть Госпо́дь: ізлію́ от Ду́ха Моєго́ на вся́ку плоть, і прореку́ть си́нове і дще́рі ва́ші, і ю́ноши ва́ші виді́нія у́зрять, і ста́рці со́нія уви́дять. Ду́ше всежела́нний, даждь хотя́ єди́ную от крупи́ць с трапе́зи сино́в утіше́нія Твоєго́ і нам, пла́менно зову́щим: Аллилу́я."]},{"h":"Ікос 11","ps":["А́ще і на кра́ткоє мгнове́ніє, я́ко блиста́ніє мо́лнії Ти возсія́єши в тайникеі душі́, но незабве́нно єсть Світоли́тіє Открове́нія Твоєго́, от Него́ же стра́шним і боголі́пним ізміне́нієм преобража́ється бре́нноє єстество́. Сподо́би єще́ в земно́м житії́ чи́стим се́рдцем узрі́ти Тя і нам, моля́щимся Тебі́:","Прийди́, світопода́тельная Мо́лніє ві́чності;","прийди́, і озари́ нас невече́рнім Сія́нієм Твої́м.","Прийди́, Сокро́вище смиренному́дрих і Весе́ліє кро́тких;","прийди́, Водо́ жива́я і прохла́дная среди́ зно́я страсте́й.","Прийди́, і́бо вдали́ от Тебе́ ність ра́дости ні поко́я;","прийди́, і́бо с Тобо́ю всю́ду Небе́сноє Ца́рство.","Прийди́, і возгрі́й Любо́в Бо́жию в охладе́вших сердця́х на́ших;","прийди́, і напечатле́й в ду́ші Солнцеви́дний Лик Твой.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 12","ps":["Бла́гости Ріко́ неістощи́мая, Ду́ше, гріхо́в Разріши́телю, прийми́ моле́нія на́ша о всем ми́рі, о ві́рующих і неві́рующих, і о сина́х противле́нія, всіх приведи́ к ві́чному Ца́рствію Святи́я Тро́йці, да упраздни́ться Тобо́ю і послі́дній враг смерть, і мир, возрожде́нний очисти́тельним огне́м, воспоє́ть но́вую піснь безсме́ртія: Аллилу́я."]},{"h":"Ікос 12","ps":["Зрю Ду́хом Град Бо́жий, Ієрусали́м Небе́сний, я́ко Неві́ста украше́нний, солнцеви́дний, торжеству́ющий, сли́шу ликова́ніє пра́ведних на Трапе́зі Госпо́дней, і гла́си а́нгелов, і Пресві́тлаго Го́спода посреді́ ізбра́нних Свої́х! Се, отбіже́ болі́знь і печа́ль і воздиха́ніє. Цар Небе́сний, седьмери́цею даро́в Свої́х сподо́би нас Сія́ ві́чния Ра́дости в Бо́зі зову́щих Ті:","Прийди́, Царю́ Небе́сний, і седьмери́цею даро́в Твої́х нищету́ на́шу духо́вную покри́й;","прийди́, і Ду́хом ві́дінія і благоче́стія сердця́ на́ша умили́.","Прийди́, і возбуди́ в нас жа́жду загро́бнаго битія́;","прийди́, і запечатлі́й в ду́ші ча́яніє Жи́зні нетлі́ннаго ві́ка.","Прийди́, і откро́й нам Ра́дость гряду́щаго Ца́рствія;","прийди́, і даждь нам снегосве́тлую Ри́зу чистоти́.","Прийди́, і возьми́ нас на брак А́гнчий;","прийди́, і сподо́би во ві́чній сла́ві Твоє́й ца́рствовати.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 13","ps":["О Світоно́сная Пучи́но спаса́ющей Любве́, Ду́ше Животворя́щий, согрі́й Диха́нієм Божества́ Твоєго́ оледені́вший в беззако́ніїх род челові́чеський, Си́лою непостижи́мих су́деб Твої́х ускори́ поги́бель зла, і яви́ ві́чноє Торжество́ Боже́ственния Пра́вди, да бу́деть Бог вся́чеськая і во всіх, і вся́ко колі́но небе́сних і земни́х і преіспо́дніх да воспоє́ть: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели на небесі́ сві́тлими хора́ми Ду́ху Свято́му несмолка́ємо сла́ву пою́ть, я́ко Істо́чнику жи́зні і Сві́ту невеще́ственному, боже́ственними мо́лніями мир просвіща́ющему. С ни́ми же і ми прославля́єм Тя, Ду́ше непостижи́мий, за вся я́вния і та́йния ми́лості Твоя́, і смире́нно про́сим блаже́ннаго осіне́нія Твоєго́:","Прийди́, Сві́те і́стинний і Ра́досте духо́вная;","прийди́, росоно́сний О́блаче і Красото́ неізрече́нная.","Прийди́, і прийми́ я́ко куре́ніє благово́нноє хвалу́ на́шу;","прийди́, і даждь нам вкуси́ти ра́дость явле́нія Твоєго́.","Прийди́, і сотвори́ сей день днем милосе́рдія Твоєго́;","прийди́, і возвесели́ нас оби́лієм даро́в Твої́х.","Прийди́, Свя́тость безмі́рная, і вся́ку скве́рну дале́че от нас отжени́;","прийди́, ві́чноє со́лнце незаходи́моє, і оби́тель Твою́ в нас сотвори́.","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Кондак 1","ps":["Прийді́те, ві́рнії, Ду́ха Свята́го просла́вим соше́ствіє, І́же от Оте́чеських нідр на апо́столов ізли́вся я́ко вода́ми, богові́дінієм покри́ зе́млю, і живоно́сния благода́ті богоусиновле́нія, і го́рнія сла́ви сподобля́єть чи́сті притека́ющих к Нему́, освяща́єть же і обожа́єть зову́щих:","Прийди́, Уті́шителю Ду́ше Святи́й, і всели́ся в ни."]},{"h":"Молитва","ps":["Царю́ Небе́сний, Уті́шителю Всеблаги́й, Ду́ше І́стини, от Отця́ предві́чно ісходя́й і в Си́ні ви́ну почива́яй, незави́стний Істо́чниче дарова́ній боже́ственних, разділя́я їх коєму́ждо, я́коже хо́щеши, І́мже і ми недосто́йнії освяти́хомся і назна́менані єсьми́ в день креще́нія на́шего! При́зри на моли́тву раб Свої́х, прийди́ к нам, всели́ся в ни, і очи́сти ду́ші на́ша, да бу́дем угото́вани в жили́щі Пресвяти́я Тро́йці. Єй, о Всеблаги́й, не возгнуша́йся на́шея нечистоти́ і ран гріхо́вних, но ісціли́ я всеврачу́ющим Пома́занієм Твої́м. Просвіти́ наш ум, да разумі́єм суєту́ ми́ра і я́же в ми́рі, оживи́ на́шу со́вість, да немо́лчно возвіща́єть нам я́же подоба́єть твори́ти і я́же отмета́ти, іспра́ви і обнови́ се́рдце, да не істоча́єть день і нощ помишле́ній злих і жела́ній неподо́бних. Укроти́ плоть і угаси́ росоно́сним Диха́нієм Твої́м пла́мень страсте́й, і́мже помрача́ється в нас драгоці́нний О́браз Бо́жий. Ду́ха пра́здности, уни́нія, любонача́лія і праздносло́вія отжени́ от нас, пода́ждь же нам Ду́ха любве́ і терпі́нія, Ду́ха кро́тости і смире́нія, Ду́ха чистоти́ і пра́вди, да іспра́вив разсла́бленная сердця́ і колі́на, нелі́ностно тече́м по путі́ за́повідей святи́х, і та́ко ізбіга́я вся́каго гріха́ і ісполня́я вся́ку пра́вду, сподо́бимся улучи́ти кончи́ну ми́рну і непости́дну, вни́ти в Ієрусали́м Небе́сний, і Та́мо покланя́тися Тебі́ ку́пно со Отце́м і Си́ном, поя́ во ві́ки віко́в: Тро́йце Свята́я, сла́ва Тебі́. Амі́нь."]},{"h":"Інша молитва","ps":["Ду́ше Святи́й! Всю Вселе́нную Собо́ю наполня́яй, і всім Жизнь подава́яй, от скве́рних же челові́к удаля́яйся, смире́нно молю́ Тя: не гнуша́йся нечистоти́ душі́ моєя́, но прийди́ і всели́ся в м'я і очи́сти м'я от вся́кия гріхо́вния скве́рни. Да по́мощію Твоє́ю про́чеє вре́м'я живота́ моєго́ поживу́ в покая́нії і творе́нії діл благи́х, і та́ко просла́влю Тя со Отце́м і Си́ном во ві́ки віко́в. Амі́нь!"]},{"h":"Тропар, глас 8","ps":["Благослове́н єси́, Христе́ Бо́же наш, / І́же прему́дри ловці́ явле́й, / низпосла́в їм Ду́ха Свята́го, // і ті́ми уловле́й вселе́нную, Человіколю́бче, сла́ва Тебі́."]},{"h":"Кондак, глас 8","ps":["Єгда́ снизше́л язи́ки слія́, / разділя́ше язи́ки Ви́шній, / єгда́ же о́гненния язи́ки раздая́ше, / в соєдине́ніє вся призва́, // і согла́сно сла́вим Всесвята́го Ду́ха."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / і чтим Всесвята́го Ду́ха Твоєго́, / Єго́же от Отця́ посла́л єси́ // Боже́ственним ученико́м Твої́м."]}],"notes":[]},{"u":"Акафіст Святому і Пречесному Поясу Пресвятої Богородиці","e":"Akathist to the Holy and Most Honourable Belt of the Most Holy Theotokos","secs":[{"h":"Кондак 1","ps":["Ко пречестно́му Богоро́дице боже́ственному по́ясу Твоєму́, со благогові́нієм притека́юще, ісполня́ємся просвіще́нія і благоуха́нія преми́рнаго, но я́ко пучи́но су́щи Ді́во бла́гости, препоя́ши ни си́лою єго́ Непоро́чная, зову́щия:","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Ікос 1","ps":["А́нгели неви́димо по́яс Твой святи́й со стра́хом обстоя́ще Отрокови́це, ми же во пло́ті су́щия, с ві́рою припа́даєм к нему́, освяще́ніє приє́млюще, і во благогові́нії вопіє́м:","Ра́дуйся, по́ясі Богоро́диці;","ра́дуйся, сія́ніє всему́ ми́ру.","Ра́дуйся, Непоро́чния Ді́ви препоя́саніє;","ра́дуйся, Це́ркве всея́ сокро́вище.","Ра́дуйся, по́ясі многоці́нний Влади́чиці небе́с;","ра́дуйся, цві́те благоуха́нний благочести́вих христия́н.","Ра́дуйся, я́ко ті́ло Ді́вия препоя́саєши;","ра́дуйся, я́ко крі́пость льсти́ваго ослабля́єши.","Ра́дуйся, світи́льниче благода́ті всесві́тлий;","ра́дуйся, істо́чниче чуде́с неізсяка́ємий.","Ра́дуйся, і́мже ві́рнії светозаря́ються;","ра́дуйся, і́мже вразі́ упраздня́ються.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 2","ps":["Воззри́ Богороди́тельнице, о́ком благоутро́бним, ко і́же ві́рою ко свято́му Ті по́ясу, я́коже істо́чнику вод освяще́нних че́стно припа́дающих, і прося́щих благода́ті Твоєя́, необори́мую бо си́лу ті́мже пода́ждь вопію́щим: Аллилу́я."]},{"h":"Ікос 2","ps":["Бисть Богоро́дице честна́го Ті по́яса принесе́ніє во Ца́рський Град, істо́чник весе́лія і́стиннаго, цари́цю бо ско́ро ісціли́л єси́, нам же благода́ть оби́льную при́сно подає́ть вопію́щим:","Ра́дуйся, істо́чниче ра́дости ві́чния;","ра́дуйся, ча́ше душепи́щнаго бра́шна.","Ра́дуйся, і́мже Всечи́стая Ді́во препоя́сася;","ра́дуйся, і́же во Афо́ні я́ко світ возсія́.","Ра́дуйся, я́ко Зо́ю цари́цю ісціли́л єси́;","ра́дуйся, я́ко то́чиши всім весе́ліє у́мноє.","Ра́дуйся, плени́це всесвята́я Чи́стия Богоро́диці;","ра́дуйся, стрело́ огнено́сная на врага́ человікоуби́йцю.","Ра́дуйся, ра́дости вина́ і хода́таю;","ра́дуйся, ти́хоє душа́м приста́нище.","Ра́дуйся, Христу́ благоче́стно связу́ющий;","ра́дуйся, страсте́й стремле́нія упраздня́ющий.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 3","ps":["По́яс Твой Фомі́ предаде́ Богоро́дице, к Си́ну Твоєму́ восходя́ще, і чрез о́наго же я́ко че́стен дар і благ ісполне́ніє єго́ нам оста́вила єси́ Всепі́тая, пою́щим і вопію́щим Ті: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́єть свята́я Оби́тель Твоя́ Ватопе́дськая, я́ко неот'є́млемо бога́тство Отрокови́це, і я́ко столп Твоєго́ заступле́нія, миродохнове́нний і всечестни́й Твой по́яс, єму́же благоче́стно припа́дающе, во умиле́нії зове́ть:","Ра́дуйся, бога́тство нетлі́нія;","ра́дуйся, сто́лпе сострада́нія.","Ра́дуйся, пода́телю благ неісчерпа́ємий;","ра́дуйся, і́ноком водруже́ніє нези́блемоє.","Ра́дуйся, по́ясі всече́стне, А́нгелом ра́досте;","ра́дуйся, мона́хом утвержде́ніє і бід отринове́ніє.","Ра́дуйся, Ватопе́ду хвало́ многоці́нная;","ра́дуйся, благочести́вим побі́дноє пі́ніє.","Ра́дуйся, благово́нієм небе́сним диха́ющий;","ра́дуйся, крі́пость непобіди́мую подаю́щий.","Ра́дуйся, тобо́ю бо мона́шествующия укріпля́ються;","ра́дуйся, тобо́ю бо вражду́ющия упраздня́ються.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 4","ps":["Живоно́сний киво́т всечестна́го Ті по́яса, подає́ть благоуха́ніє Ді́во, і злосмра́діє страсте́й отгоня́єть при́сно от душ на́ших, ті́мже вели́чію Твоєму́ див'я́щеся вопіє́м: Аллилу́я."]},{"h":"Ікос 4","ps":["По́яс Твой святи́й Всесвята́я Ді́во, я́ко світ сія́єть на горі́ Афо́нстій, і лучи́ златови́дними, вся облиста́єть твоє́й благода́тію, ті́мже чудеса́ того́ почита́юще, ві́рою вопіє́м:","Ра́дуйся, чуде́с пода́телю;","ра́дуйся, благода́тей світоли́тіє.","Ра́дуйся, сокро́вищ сокро́вище свято́є;","ра́дуйся, свіще́ серде́ць богому́дрих.","Ра́дуйся, по́ясі, єго́же носи́ла єси́ Всенепоро́чная на землі́;","ра́дуйся, вся́кую подаю́щий благода́ть і мно́гую крі́пость.","Ра́дуйся, я́ко показу́єши Ді́вия сла́ву;","ра́дуйся, я́ко отвраща́єши де́монськия лу́ки.","Ра́дуйся, мно́гая ісціле́нія істоча́ющий;","ра́дуйся, душі́ страсте́й свобожда́ющий.","Ра́дуйся, ві́рним ликова́ніє боже́ственноє;","ра́дуйся, честна́я милосе́рдія кле́те.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 5","ps":["Богодарова́нний дар і небе́сноє бога́тство, по́яс Твой держа́ще Отрокови́це, на стра́сті си́лу непобіди́мую, є́юже препояса́ємся, благода́ть бо і ми́лость при́сно подає́ть вопію́щим: Аллилу́я."]},{"h":"Ікос 5","ps":["Ісціле́ніє істоча́єть по́яс Твой святи́й душі́ і ті́лу Отрокови́це, я́коже ро́су весне́ннюю, я́ко бо Іса́я глаго́леть Всенепоро́чная, і сла́дость небе́сную благогові́йно тому́ вопію́щим:","Ра́дуйся, істо́чниче вод невеще́ственних;","ра́дуйся, пото́че мно́гих даро́в.","Ра́дуйся, Всечи́стия по́яс всечестни́й;","ра́дуйся, Це́ркві ра́дость небе́сная.","Ра́дуйся, сокро́вище свято́є дарова́ній духо́вних;","ра́дуйся, ві́нче сла́вний христия́н благочести́вих.","Ра́дуйся, Ватопе́ду стіна́ неруши́мая;","ра́дуйся, всему́ ми́ру сто́лпе крі́пости боже́ственния.","Ра́дуйся, честно́є Ді́вия опоя́саніє;","ра́дуйся, Бо́гом нам да́нная ку́пля.","Ра́дуйся, Єди́ния Ді́вия по́ясі;","ра́дуйся, ві́рним богодарова́нная си́ло.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 6","ps":["Стяжа́ Оби́тель Твоя́ Ватопе́дськая, я́ко сокро́вище боже́ственноє Отрокови́це, по́яс Твой ди́вний, і чудеси́ того́ хва́литься, і благода́рственния пі́сні Тебі́ воспіва́єть глаго́люще: Аллилу́я."]},{"h":"Ікос 6","ps":["Світ сія́ющий зря́шеся по́яс Твой святи́й, внегда́ принесе́ся во о́стров Ти́ра, отону́дуже со благогові́нієм мно́гим во Оби́тель Твою́ сей принесо́ша, пою́ще Твоє́ промишле́ніє і ра́достію вопію́щи:","Ра́дуйся, по́ясі Богоро́диці;","ра́дуйся, Ватопе́ду сла́ва.","Ра́дуйся, єго́же осіня́єть благода́ть Ду́ха Свята́го;","ра́дуйся, єго́же похваля́єть наро́д христоімени́тий.","Ра́дуйся, чредо́ всечестна́я дарова́ній небе́сних;","ра́дуйся, піснопі́ніє непреста́нноє мона́хом і по́стником.","Ра́дуйся, я́ко струї́ ісціле́ній то́чиши;","ра́дуйся, я́ко пла́мень страсте́й угаша́єши.","Ра́дуйся, честно́є Чи́стия препоя́саніє;","ра́дуйся, всім ві́рним спасе́ніє.","Ра́дуйся, сві́та заре́ облиста́ющая;","ра́дуйся, страсте́й уставля́єши па́губу.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 7","ps":["Велича́єм всі, мно́гая вели́чія, є́же о нас Твоєго́ попече́нія, і по́яс Твой свяще́нний ві́рою обстоя́ще Всепі́тая, освяще́нія ісполня́ємся, і Си́ну Твоєму́ взива́єм: Аллилу́я."]},{"h":"Ікос 7","ps":["Я́ко о́блак ми́сленний, по́яс Твой святи́й, простри́ на ни Богоро́дице, і душа́ на́ша іспо́лни, освяще́нія і умиле́нія боже́ственнаго, к Тебі́ бо прибіга́єм, і по́ясу Твоєму́ взива́єм:","Ра́дуйся, жили́ще благода́ті боже́ственния;","ра́дуйся, сострада́нія кла́дязе.","Ра́дуйся, даро́в богода́нних сокро́вище;","ра́дуйся, Чи́стия Богоро́диці препоя́саніє.","Ра́дуйся, тве́рдий соу́зе і ми́ра пода́телю;","ра́дуйся, благочести́вим утвержде́ніє нези́блемо і сла́дость.","Ра́дуйся, я́ко чуде́с лучи́ іспуща́єши;","ра́дуйся, я́ко свирі́пства болі́зней разоря́єши.","Ра́дуйся, Бо́жієй бла́гости луче́;","ра́дуйся, крі́посте на́ша богодарова́нная.","Ра́дуйся, ра́дость і́стинную подаю́щий;","ра́дуйся, тлю душе́вную умерщвля́ющий.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 8","ps":["Стра́нна твоя́ чудеса́, о по́ясі пречестни́й Всецари́ці Ді́ви, пове́трія губи́тельнаго Ца́рський Град свободи́л єси́, чудя́хубося і дивля́хуся во умиле́нії вопію́щия: Аллилу́я."]},{"h":"Ікос 8","ps":["Приста́нище обурева́ємим, по́яс Твой святи́й показа́ся Богоро́дице Ді́во, благода́ть бо Твоя́ я́же на нем, ді́йствуєть бо чудеси́ приходя́щим, ті́мже к нему́ припа́дающе, с любо́вію взива́єм:","Ра́дуйся, ра́ко до́брих небе́сних;","ра́дуйся, чуде́с точе́ніє разли́чних.","Ра́дуйся, Ді́ви нам посіще́ніє;","ра́дуйся, скорб'я́щим душа́м засту́пниче.","Ра́дуйся, боже́ственноє жили́ще ді́йства боже́ственнаго;","ра́дуйся, благода́ті Ді́вия свято́є сокро́вище.","Ра́дуйся, я́ко холе́ри Град Ца́рський спаса́єши;","ра́дуйся, я́ко ско́роє всім заступле́ніє посила́єши.","Ра́дуйся, угль погаша́ющий стра́сті;","ра́дуйся, вся ни возвеселя́ющий.","Ра́дуйся, мно́гих даро́в пала́то;","ра́дуйся, сла́ви боже́ственния честно́є храни́лище.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 9","ps":["Іспо́лнь сла́ви святи́я ви́диться, по́яса Ті киво́т воі́стину святи́й, Богоро́дице Ді́во Чи́стая, ра́зум нам удивля́ющий, благоуха́нієм бо ди́шить преми́рним вопію́щим: Аллилу́я."]},{"h":"Ікос 9","ps":["Жезл крі́пости боже́ственния, по́яс Твой нам даде́ся, ди́вная Богома́тер, у́мним бо того́ соді́йствієм, от вся́кия біди́ ізбавля́ємся і благода́ті ісполня́ємся, во благогові́нії вопію́ще:","Ра́дуйся, сосу́де свята́го благоуха́нія;","ра́дуйся, дияди́ма нетлі́нія.","Ра́дуйся, мона́шествующим честно́є прибі́жище;","ра́дуйся, і́мже во Афо́ні дая́ніє препі́тоє.","Ра́дуйся, Чи́стия Ді́ви всечестно́є свяще́ніє;","ра́дуйся, Єя́ же воі́стину нам дар всесоверше́нний.","Ра́дуйся, Ватопе́ду весе́ліє і́стинноє;","ра́дуйся, вся́кому се́рдцю благоче́стному ра́досте.","Ра́дуйся, цвіто́в благода́ті благоуха́ніє;","ра́дуйся, го́рній красоти́ диха́ніє.","Ра́дуйся, фія́ло арома́тов боже́ственних;","ра́дуйся, святи́м боже́ственноє пі́ніє.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 10","ps":["Покро́в і предста́тельство, і Бо́жию по́мощ, при́сно плодя́ще Всесвята́я, от миродохнове́ннаго Ті по́яса, с ві́рою к нему́ приступа́єм, і благогові́йно припа́дающе, із Тебе́ Ро́ждшемуся вопіє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Благода́тію свята́го Ті по́яса Богоро́дице, си́лу нам препоя́ши на врага́ началозло́бнаго, я́ко лев на ни рика́ющаго, я́коже да одоле́єм зло́бу того́ вопію́щия:","Ра́дуйся, Чи́стия Ді́ви по́ясі;","ра́дуйся, ча́ше Госпо́днія крі́пости.","Ра́дуйся, связу́ющий ни і спаса́ющий;","ра́дуйся, у́зи страсте́й разреша́ющий.","Ра́дуйся, по́ясі драгоце́ннейший Ро́ждшия Христа́;","ра́дуйся, благоче́стному наро́ду дая́ніє свяще́ннійшеє.","Ра́дуйся, боже́ственния нам си́ли пода́телю;","ра́дуйся, вра́жиє неі́стовство отверга́ющий.","Ра́дуйся, о по́ясі Богома́тері;","ра́дуйся, о сла́ва нам і соу́зе.","Ра́дуйся, Це́ркві Христо́вой украше́ніє;","ра́дуйся, наро́ду правосла́вному утвержде́ніє.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 11","ps":["Благода́рственними пі́сньми, по́ясі всепрече́стне всіх Зижди́теля Ро́ждшия, твою́ благода́ть воспіва́єм при́сно, мно́гих чуде́с твої́х наслажда́ющеся, і сла́вим Чи́стую Всецари́цю, Христу́ вопію́ще: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́, по́яс Твой святи́й, іму́ще Оби́тель Ватопе́дськая, світле́ється Ді́во при́сно, і сла́вить є́же о ней Твоє́ промишле́ніє, я́ко той дарова́ся по́яс Твой ві́рно вопію́щей:","Ра́дуйся, по́ясі Богоро́диці;","ра́дуйся, світи́льниче сві́та трисві́тлаго.","Ра́дуйся, разділе́нним боже́ственноє сочета́ніє;","ра́дуйся, неду́гующим богода́нная си́ло.","Ра́дуйся, по́ясі боже́ственний держа́ву ві́рним подаю́щий;","ра́дуйся, всево́їнства велія́рова полки́ погубля́ющий.","Ра́дуйся, я́ко си́ли душа́м укріпля́єши;","ра́дуйся, я́ко к восхожде́ніям до́брим направля́єши.","Ра́дуйся, я́зви душ омива́ющий;","ра́дуйся, колесни́ци враго́в сокруша́ющий.","Ра́дуйся, і́стинноє нам весе́ліє;","ра́дуйся, ві́рним боже́ственноє утіше́ніє.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 12","ps":["Ра́дується, Богоро́дице, Оби́тель Ватопе́дськая, по́ясом боже́ственним Ті облада́юще, і ко славосло́вію вели́чий Твої́х оби́телі вся созива́єть, сла́в'яще сла́ву Твою́, Тро́йце же вопію́ще: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по до́лгу, Богоро́дице Ді́во, по́яса Ті благода́ть преоби́льную, і пропові́дуєм я́сно Чи́стая, є́же о нас бога́тноє Ті попече́ніє, і пресвято́му Ті по́ясу всеблагода́рно вопіє́м:","Ра́дуйся, Ді́вия честна́я плени́це;","ра́дуйся, Ватопе́ду ра́досте.","Ра́дуйся, ві́рних к Бо́гу возводя́щий;","ра́дуйся, ко і́стинній жи́зні влеку́щий.","Ра́дуйся, по́ясі всечестни́й; Це́ркві сокро́вище;","ра́дуйся, ми́ру весе́ліє і ми́ра пода́телю.","Ра́дуйся, благоче́ствующим прибі́жище спасе́нія;","ра́дуйся, мона́шествующим бога́тство утіше́нія.","Ра́дуйся, і́мже страсте́й очища́юся;","ра́дуйся, і́мже сві́та ісполня́юся.","Ра́дуйся, душі́ моєя́ ра́дость і́стинная;","ра́дуйся, жи́зні моєя́ приста́нище ві́рноє.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 13","ps":["О пречестни́й по́ясі Пречи́стия Богоро́диці, препоя́савий ті́ло непоро́чноє, подава́й нам от сокро́вища все́льшіяся в тя благода́ті боже́ственния, ді́йство животворя́щеє, я́ко да Христу́ при́сно вопіє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели неви́димо по́яс Твой святи́й со стра́хом обстоя́ще Отрокови́це, ми же во пло́ті су́щия, с ві́рою припа́даєм к нему́, освяще́ніє приє́млюще, і во благогові́нії вопіє́м:","Ра́дуйся, по́ясі Богоро́диці;","ра́дуйся, сія́ніє всему́ ми́ру.","Ра́дуйся, Непоро́чния Ді́ви препоя́саніє;","ра́дуйся, Це́ркве всея́ сокро́вище.","Ра́дуйся, по́ясі многоці́нний Влади́чиці небе́с;","ра́дуйся, цві́те благоуха́нний благочести́вих христия́н.","Ра́дуйся, я́ко ті́ло Ді́вия препоя́саєши;","ра́дуйся, я́ко крі́пость льсти́ваго ослабля́єши.","Ра́дуйся, світи́льниче благода́ті всесві́тлий;","ра́дуйся, істо́чниче чуде́с неізсяка́ємий.","Ра́дуйся, і́мже ві́рнії светозаря́ються;","ра́дуйся, і́мже вразі́ упраздня́ються.","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Кондак 1","ps":["Ко пречестно́му Богоро́дице боже́ственному по́ясу Твоєму́, со благогові́нієм притека́юще, ісполня́ємся просвіще́нія і благоуха́нія преми́рнаго, но я́ко пучи́но су́щи Ді́во бла́гости, препоя́ши ни си́лою єго́ Непоро́чная, зову́щия:","Ра́дуйся, по́ясі пречестни́й."]},{"h":"Молитва перша","ps":["О, Благода́тная Богома́ти, Пренепоро́чная і Обра́дованная, да ра́дуємся і ми, немощни́я лю́діє Твої́, я́ко Си́лою і Вла́стію Твоє́ю сокруши́ши всіх враго́в на́ших ви́димих і неви́димих, да просла́вим і возвели́чим Тя, я́ко Непобіди́мую Побі́ду Всеси́льную."]},{"h":"Молитва друга","ps":["Цари́це моя́ преблага́я, наде́ждо моя́ Богоро́дице, прия́телище си́рих і стра́нних предста́тельнице, скорб'я́щих ра́досте, оби́димих покрови́тельнице! Зри́ши мою́ біду́, зри́ши мою́ скорб, помози́ мі я́ко не́мощну, окорми́ м'я я́ко стра́нна. Оби́ду мою́ ві́си, разріши́ ту, я́ко во́лиши: я́ко не і́мам іни́я по́мощі ра́зві Тебе́, ні іни́я предста́тельниці, ні благи́я уті́шительниці, то́кмо Тебі́, о Богома́ти, я́ко да сохрани́ши м'я і покри́єши во ві́ки віко́в. Амі́нь."]},{"h":"Тропар положенню пояса, глас 8","ps":["Богоро́дице Присноді́во, челові́ков покро́ве, / ри́зу і по́яс пречи́стаго Твоєго́ тілесе́, / держа́вноє гра́ду Твоєму́ обложе́ніє дарова́ла єси́, / безсі́менним рождество́м Твої́м нетлі́нна пребива́ющи, / о Тебі́ бо і єстество́ обновля́ється і вре́м'я. / Ті́мже мо́лим Тя мир гра́ду Твоєму́ дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Інший тропар, глас 5","ps":["Я́ко некра́домо бога́тство, / по́яс Твой честни́й, Присноблаже́нная, / і благи́х подая́ніє іму́ще, / Оби́тель Ватопе́дськая взива́єть Ті, / препоя́ши со благогові́нієм, / притека́ющия ни к нему́, / си́лою єго́ боже́ственною, / і крі́пость льсти́ваго врага́ разруши́, // спасе́ніє ві́рним Чи́стая."]},{"h":"Кондак положенню пояса, глас 4","ps":["Честна́го по́яса Твоєго́ положе́ніє / пра́зднуєть днесь Твой, Препі́тая, храм, / і прилі́жно взива́єть Ті: / ра́дуйся, Ді́во, // христия́н похвало́."]},{"h":"Інший кондак, глас 2","ps":["Богоприя́тноє Твоє́ чре́во, Богоро́дице, / об'є́мшій по́яс Твой честни́й, / держа́ва гра́ду Твоєму́ необори́ма / і сокро́вище єсть благи́х неоску́дно, // єди́на ро́ждшая, Присноді́во."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтим По́яс Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притекающим."]}],"notes":[]},{"u":"Акафіст Стрітенню Господньому","e":"Akathist to the Meeting of the Lord","secs":[{"h":"Кондак 1","ps":["Ізбра́ннаго Царя́ Ізбра́нная Ма́ти зри́ться ни́ні от Вифлеє́ма в Ієрусали́м гряду́ща, Богомладе́нець же Ісу́с, я́ко на о́блаці ле́гці во об'я́тіях Тоя́ носи́м бива́єть. Ми же недосто́йнії, сріта́юще Царя́ Сла́ви і Пресвяту́ю Ма́тер Ді́ву, с Симео́ном ста́рцем вопіє́м Преблагослове́нній:","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Ікос 1","ps":["А́нгел небе́сних небе́сния ли́ки прини́кше на зе́млю, зрять Своєго́ Творця́ і Влади́ку Перворожде́нна всея́ тва́рі во об'я́тіях Діви́чеських от Ма́тері Неіскусому́жния, я́ко Младе́нця носи́ма і ко хра́му во Ієрусали́м гряду́ща, і ра́дующеся пою́ть Тому́ і Цари́ці Ді́ві хвалу́ пра́здничную:","Гряди́, Царю́ не́ба і землі́, во град Вели́каго Царя́, Сіо́н святи́й;","гряди́, Преви́шній Бо́же, от го́рних висо́т в рукотворе́нний храм земни́й.","Гряди́, Єдиноро́дний Си́не Бо́жий, всели́тися с челові́ки на землі́;","гряди́, Непоро́чний А́гнче Бо́жий, принести́ся ко Го́споду, живу́щему на небесі́.","Гряди́, Чи́стая Голуби́це, Свята́го Ду́ха Безму́жная Неві́сто;","гряди́, Нескве́рная А́гнице, А́гнця Христа́ Нетлі́нная Ма́ти.","Гряди́, Богоізбра́нная Отрокови́це, Бо́га Отця́ Превожделе́нная Дще́ре;","гряди́, Небе́сная Цари́це, всему́ ми́ру Блага́я Влади́чице.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 2","ps":["Ви́дящи Пресвята́я Ді́ва Себі́ в чистоті́ по Рождестві́ Христо́ві Су́щую і не тре́бующую очище́нія, зане́ Христо́с про́йде от Нея́, я́коже луча́ со́лнечная криста́лл прохо́дить, не повреди́в ді́вственния чистоти́ Пречи́стия Ма́тері Своєя́. Оба́че смире́нна су́щи, не гордя́шеся о нетлі́нной чистоті́ Своєя́, і єгда́ іспо́лнишася дні́є очище́нія Єя́ зако́ннаго, воста́вши со святи́м Іо́сифом Обру́чником от Вифлеє́ма, вознесо́ста Боже́ственна Младе́нця, да поста́в'ять Єго́ пред Го́сподом во Ієрусали́мі, с ра́достію пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в Тя іздале́ча, Ді́во, Бо́га Нося́щую Воплоще́нна на руку́ Твоє́ю, Іса́їя предвозвісти́: «Се Госпо́дь сіди́ть на о́блаці ле́гці». Ти же, о Богома́ти, в Ієрусали́м іду́ще і Боже́ственнаго Младе́нця во об'я́тіях нося́ще, помишля́ше, ка́ко Ма́тер соді́яся і Ді́ва преби́сть. Оба́че ві́дуще, я́ко па́че єстества́ рожде́ніє сіє́ бисть, со тре́петом глаго́лаше в Себі́: Ка́ко возимену́ю Тя, Си́не Мой? А́ще нареку́ Тя челові́ка, вім, я́ко преви́ше челові́ка єси́, ді́вство Моє́ соблюди́й нетлі́нно, я́ко Боже́ственно єсть зача́тіє Твоє́. А́ще нареку́ Тя Бо́га, ви́жду Тя во всем подо́бна челові́ку, кромі́ гріха́. Сего́ ра́ди пропові́дують Тя соверше́нна Бо́га і соверше́нна челові́ка су́ща. Ми же, сріта́юще прише́ствіє Тоя́, Чи́стую чи́сто почти́м, глаго́люще та́ко:","Гряди́, Чи́стая Ді́во, Чи́стаго Бо́га чи́сто роди́вшая;","гряди́, Безму́жная Ма́ти Емману́їлова, бра́ка не позна́вшая.","Гряди́, честні́йшая Херуви́м, Єя́же чистоті́ Гавриї́л удиви́ся;","гряди́, Сла́внійшая без сравне́нія Серафи́м, Є́йже все єстество́ А́нгельськоє поклони́ся.","Гряди́, Земле́ ненасі́янная, Я́же ізрасти́ нам Клас Живота́;","гряди́, Купино́ Неопали́мая, Ю́же в Рождестві́ не опали́ огнь Божества́.","Гряди́, Вмісти́лище невмісти́моє, на Ню́же шестокрила́тії і многоочи́тії взира́ти не мо́гуть;","гряди́, Престо́ле огнезра́чний, Ю́же земноро́днії по достоя́нію восхвали́ти недоумі́ють.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю, і Тобо́ю с на́ми."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственною Управля́єма, приї́де Пресвята́я Ді́ва во святи́й град Ієрусали́м, я́ко світоно́сний день, Со́лнце Пра́вди Христа́ всему́ ми́ру возсіява́ющи. Сія́ бо я́ві яви́ся Престо́л Херуви́мський, зіло́ висо́к сла́вою ді́вственною превознесе́н, Та бо на руку́ Своє́ю но́сить Царя́ Сла́ви, Єму́же незри́мо предстоя́ть шестокрила́тії Серафи́ми, со всі́ми небе́сними си́лами вопію́ще: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи богоприя́тную Ді́ва утро́бу, востече́ ко хра́му, держа́щи на руку́ Своє́ю Богомладе́нця Христа́, і приклони́в колі́на Своя́ пред Го́сподом, с весе́лієм і благогові́нієм глаго́ла: О, Преві́чний О́тче, се — Син Твой, Єго́же посла́л єси́ воплоти́тися от Мене́ спасе́нія ра́ди челові́чеськаго. Се — Плод утро́би Моєя́, Ду́хом Твої́м Святи́м во Мні зача́тий і неізрече́нно проізше́дий, Се — Пе́рвенець Мой. Прийми́ воплоще́нноє от Мене́ Твоє́ Сло́во, прийми́ Твоєго́ от Мене́ Си́на, Єго́же Тебі́ приношу́, да Того́ Пло́тію і Кро́вію от Мене́ прия́тою, іску́пиши род челові́ч. Ми же сему́ та́йному моле́нію Твоєму́, Пречи́стая, вне́млюще, вопіє́м Си́ну Твоєму́ і Бо́гу на́шему та́ко:","Гряди́, Пресла́дкий Ісу́се, я́ко дождь с небесе́ на Чи́стую Зе́млю кро́тко і ти́хо снизше́дий;","гряди́, Сладча́йший Животе́, я́ко ка́пля ка́плющая на зе́млю во воплоще́нії незри́мо Себе́ яви́вий.","Гряди́, Всеми́лостивий Спа́се, взиска́ти і спасти́ поги́бшія прише́дий;","гряди́, Па́стирю Предо́брий, заблу́ждшия о́вці понести́ на Себі́ восхоті́вий.","Гряди́, Врачу́ безнаде́жних, не́мощі і болі́зні на́ші на Себі́ носи́ти ізво́ливий;","гряди́, А́гнче Бо́жий, гріхи́ всего́ ми́ра взя́ти на Себі́ возжела́вий.","Гряди́, Го́споди Сла́ви, на о́блаці ле́гці носи́мий, пре́лести тьму отгна́ти імі́вий;","гряди́, Царю́ ми́ра, на престо́л Дави́дов прише́дий, Ца́рство не от ми́ра сего́ явля́яй.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́яй помишле́ній сумни́тельних, вели́кий Архієре́й Бо́жий Заха́рія смути́ся, зря Пресвяту́ю Ді́ву со Отроча́тем, на мі́сті нечи́стих жен пред две́рми хра́ма ста́вшую і зако́ннаго очище́нія проси́ти прише́дшую, ві́дуще бо Ю во Свята́я Святи́х воспита́нную, і уразумі́ ду́хом, я́ко сія́ Ма́тер і по рождестві́ єсть Ді́ва Чи́стая. Сего́ ра́ди поста́ви Ю на мі́сті діви́ць, іді́же жена́м іму́щим му́жа стоя́ти не подоба́ше, і сріта́юще Ю, со стра́хом і с ра́достію воспі́ я́вльшемуся Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Заха́рія ди́вния пред Бо́гом глаго́ли Твоя́, Пречи́стая, і ви́дів, я́ко хо́щеши возложи́ти возлю́бленноє ча́до Своє́ на ру́ці єго́, я́ко Архієре́ю Бо́жию, а́ки в руні́ Самому́ Бо́гу влага́ющи, і я́ко вку́пі принесла́ єси́ Бо́гу в же́ртву ни́щих, по рече́нному в зако́ні, два птенця́ голуби́ния, умили́ся се́рдцем і с ві́рою і со стра́хом Бо́жиїм прия́т Богомладе́нця, і я́ко зако́нну Творцю́ і Бо́гу, ізрече́ Єму́ та́ко:","Гряди́, Ве́тхий де́ньми, дре́вле на Сина́є Моїсе́єм зако́н дарова́вий;","гряди́, Отроча́ Мла́до, ни́ні зако́н іспо́лнити хотя́й ко хра́му прише́дий.","Гряди́, Престо́л імі́я і Не́бо, земни́й храм небе́сною сла́вою іспо́лнити восхоті́вий;","гряди́, воплоти́вийся от Ді́ви челові́чеськоє єстество́ обожи́ти возжела́вий.","Гряди́, да́же до ра́бія о́браза низше́дий, да нас рабо́в гріха́ в раби́ Пра́вди Бо́жієй сотвори́ши;","гряди́, сія́ніє Сий Іпоста́си О́тчія, да нас ча́дами Бо́жиїми Отця́ Небе́снаго яви́ши.","Гряди́, Зако́на Ісполни́телю, птенці́ голуби́ния Бо́гу принеси́й, да ми па́че голуби́ць чи́стих на небеса́ возлети́м;","гряди́, ми́лости Пода́телю, ми́лости, а не же́ртви восхоті́вий, да і ми с єле́єм ми́лованія Тебі́ усря́щем.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 5","ps":["Богосві́тлая звізда́ возсія́, єгда́ при́йде Ду́хом в Це́рков Святи́й ста́рець Симео́н. Той, ю́ношествуя ду́хом, престарі́в же ті́лом, пра́веден бі і благочести́в, ві́рою жив'я́, ча́я Уті́хи Ізра́їлеви, обіща́но бо бі єму́ Ду́хом Святи́м не ви́діти сме́рті, до́ндеже не ви́дить Христа́ Госпо́дня во пло́ті прише́дша. Той воззрі́в на Пречи́стую Ді́ву і на держи́моє Є́ю Отроча́, ви́ді благода́ть Бо́жию, і позна́в Ду́хом, я́ко Сей єсть ожида́ємий Мессі́я, приступи́ к Нему́ со тща́нієм, і возда́в Бо́гу благодаре́ніє ве́ліє, со стра́хом Бо́жиїм і с ра́достію серде́чною воспі́ Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів ста́рець Симео́н на руку́ Діви́чу созда́вшаго челові́ки, і Влади́ку разумі́в Єго́, а́ще і я́ко Младе́нець ви́дін бисть, весь іспо́лнися ра́дости неізрече́нния, і себі́ заби́в, глаго́леть ве́село: Тебі́ жела́ю, Бо́же отце́в і Го́споди ми́лости, на Тя взира́ю, об'є́млющаго вся Сло́вом Свої́м, Тебі́ сріта́ю, влади́чествующаго жи́знію і сме́ртію, Тебі́ ча́ю, соєдини́вшаго не́бо і зе́млю. Тебі́ алка́ю, ме́ртвия воскреша́ющаго. Тебі́ жа́ждаю, стра́ждущия утіша́ющаго і Тебі́ вопію́ си́це:","Гряди́, всі́ми проро́ки ча́ємий, посіти́ти нас Твої́м спасе́нієм;","гряди́, всі́ми язи́ки жела́ємий, просвіти́ти нас Твої́м открове́нієм.","Гряди́, от ю́га прише́дий Іскупи́телю наш, да ізба́виши Ада́ма і Є́ву от гріха́ і кля́тви дре́внія;","гряди́, на землі́ яви́вийся, Спаси́телю наш, да с челові́ки поживе́ши і ізведе́ши я із тьми і сі́ні сме́ртния.","Гряди́, Просвіти́телю наш, благовісти́ти лі́то Госпо́днє прия́тно;","гряди́, Свободи́телю наш, отпусти́ти сокруше́нния се́рдцем во отра́ду.","Гряди́, Па́стирю і Учи́телю, пропові́дати пліне́нним отпуще́ніє і сліпи́м прозрі́ніє;","гряди́, Тво́рче і Влади́ко, возвісти́ти ни́щим спасе́ніє і всім челові́ком проще́ніє.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 6","ps":["Пропові́дник ди́вний прише́ствія Христо́ва яви́ся Богоно́сець Симео́н, єгда́ па́че ісполня́яся Ду́ха, пе́рвий от челові́к позна́ Творця́ своєго́, во пло́ті прише́дша, і пе́рвий іспові́да Того́ Божество́, вопію́ще Єму́, я́ко от лиця́ всіх живу́щих на землі́: Тебі́ поклоня́ємся, я́ко Ти єси́ Бог наш; Тебі́ мо́лимся, я́ко Ти єси́ храм наш; Тебі́ слу́жим, я́ко Ти єси́ зако́на Творе́ць. Ти єси́ Бог Пе́рвий і ність іна́го Бо́га па́че Тебі́, і іна́го Си́на Єдиносу́щна Отцю́. Тобо́ю живе́м і дви́жемся і єсьми́. Ти красе́н єси́ па́че всіх сино́в челові́чеських, я́ко Бог і челові́к. Сего́ ра́ди весели́ся ни́ні не́бо, я́ко поми́лова Бог лю́ди Своя́ і лику́йте основа́нія землі́ і су́щия во а́ді, я́ко яви́ся ни́ні ме́ртвим Воскресе́ніє, уви́діх бо ни́ні Спаси́теля ми́ра, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ всему́ ми́ру просвіще́ніє І́стини, єгда́ Пресвята́я Ді́ва подаде́ ста́рцю Симео́ну пречи́стима рука́ма Свої́ма Боже́ственнаго Младе́нця, я́ко Угль Животворя́щ та́їнственно от же́ртвенника Бо́жия, глаго́люще: Прийми́, честни́й ста́рче, Го́спода Твоєго́, прийми́ Сокро́вище неісчерпа́ємоє і Си́лу непостижи́мую. Обими́ Нетлі́ніє і обнови́ся і просвіти́ся от Со́лнця Пра́вди. Не опаля́єть бо огнь благода́ті Го́спода Моєго́, но па́че просвіща́єть, Той бо очи́стить гріхи́ твоя́ і вся беззако́нія твоя́ очи́стить, да бу́деши нача́ток очище́нія всего́ ми́ра, і та́ко совлече́ши вся ве́тхая і во вся но́вая да облече́шися. Сему́ ми́лостивому веща́нію Пречи́стій вне́млюще, возопіє́м Єй такова́я:","Гряди́, небе́сною чистото́ю сія́ющая Діви́це, Світ Невече́рній нам просія́вшая;","гряди́, пречу́дная ми́ра го́рняго Цари́це, во го́рнія оби́телі нас возводя́щая.","Гряди́, Купино́ Та́їнственная, Є́юже огнь Божества́ от го́рних висо́т всему́ ми́ру возжже́ся;","гряди́, Світоно́сний о́блаче, Є́юже Богомладе́нець Христо́с во спасе́ніє всім принесе́ся.","Гряди́, О́гненний Престо́ле Неви́димаго Царя́;","гряди́, Небе́сний Киво́те, вмісти́вшая Христа́.","Гряди́, Пресвята́го Ду́ха Святі́йшая Пала́то;","гряди́, Безсме́ртнаго Царя́ Нескве́рная Неві́сто.","Гряди́, Пречи́стая, Госпо́дь с тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 7","ps":["Хотя́й святи́й ста́рець Симео́н но́воє очище́ніє получи́ти, я́коже дре́вле Іса́їя, поклони́ся Пречи́стій Богома́тері, прикосну́ся Боже́ственним стопа́м Єя́, глаго́люще: Огнь но́сиши, Чи́стая, бою́ся об'я́ти Младе́нця, ми́ром влади́чествующа. Ти бо, я́ко крила́ми а́нгельськими, рука́ма просвіща́єши м'я, пода́вши, Єго́же Херуви́ми крила́ми носи́ти трепе́щуть. Сего́ Симео́н, просте́р ру́ці, прия́т в честни́я об'я́тія своя́, і с ра́достію возопи́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє і пресла́вноє чу́до соверши́ся днесь: Симео́н ста́рець приє́млеть тле́ннима рука́ма Творця́, созда́вшаго челові́ка, да Бог с челові́ки поживе́ть і челові́ка небеса́ сотвори́ть. Приє́м же Жела́ємаго, і ви́дів обіща́ній сбитіє́, той, я́коже зрі́лая пшени́ця, прося́ще о разріше́нії тіле́снім, і я́коже ле́бедь бі́лий, сіди́нами украше́нний, на зака́ті житія́ своєго́ ве́село возопи́: ви́діста о́чі мої́ спасе́ніє Твоє́, є́же от ві́ка та́їнство сокрове́нноє. Ті́мже ни́ні отпусти́ м'я, Влади́ко, раба́ Твоєго́ по глаго́лу Твоєму́ с ми́ром от соу́за сея́ пло́ті к чу́дному і нестарі́ємому животу́ да отходя́ от зді́шніх, ра́достную вість принесу́ отце́м мої́м о Твоє́м в мир прише́ствії. Сего́ ра́ди вопіє́м Ті:","Гряди́, Ісу́се, жи́зні Пода́телю, жизнь і воскресе́ніє всім ві́рним Твої́м дарова́ти;","гряди́, Влади́ко, сме́рті Низложи́телю, от ві́чния сме́рти лю́ди Твоя́ свободи́.","Гряди́, Безсме́ртний Царю́, от тьми і сі́ні сме́ртния ві́чния у́зники разріши́ти;","гряди́, Сладча́йший Животе́, врата́ ра́йськия к чу́дному животу́ па́ки Ада́му отве́рсти.","Гряди́, Жела́ємий Женише́, я́ко жела́єть і скончава́ється душа́ моя́ во двори́ Госпо́дні;","гряди́, Превожделі́нний Сві́те, я́ко обрі́те се́рдце моє́ в юдо́лі пла́ча хра́мину о Бо́зі Жи́ві.","Гряди́, Предві́чний Бо́же, я́ко близ боя́щихся Тебі́ спасе́ніє Твоє́;","гряди́, Всеще́дрий Спа́се, я́ко мир мно́го лю́б'ящим Тя принесе́ Сло́во Твоє́.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 8","ps":["Стра́нния глаго́ли ди́внаго ста́рця о Отроча́те сли́шавше, Іо́сиф і Пречи́стая Ді́ва чудя́хуся о глаго́лемих о Нем: ви́діста бо Симео́на к Младе́нцю віща́юща, но не я́ко к Младе́нцю, но я́ко к Ве́тхому де́ньми і к Бо́гу моля́щагося, Живота́ і сме́рті власть Іму́щему і Могу́щему а́біє к іно́й Жи́зні отпусти́ти того́, і слага́юще вся глаго́ли сія́ в се́рдці своє́м, благода́рственно возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бив в Бо́зі, Святи́й ста́рець Симео́н, іспо́лнися ду́ха проро́чеськаго і мно́гая ізрече́ о Боже́ственном Младе́нце, я́ко да́же до а́да при́йдеть і пліне́нним пода́сть всім оставле́ніє і сліпи́м прозрі́ніє і я́ко і німи́м глаго́лати. І обраща́тися к Марі́ї Ма́тері Єго́, провозгласи́ Єй: Се лежи́ть Сей на паде́ніє непокори́вим і на воста́ніє ві́рним мно́гим во Ізра́їлі, і в зна́меніє преріка́ємоє. І Тебі́ Само́й, о Безсме́ртная Ма́ти, ду́шу про́йдеть ору́жіє печа́лі, єгда́ у́зриши Си́на Твоєго́ на Кресті́ пригвожде́нна, да откри́ються помишле́нія мно́гих серде́ць во спасе́ніє от гріх їх. Сему́ предрече́нію вне́млюще, вопіє́м Пречи́стій та́ко:","Гряди́, Ма́ти і Ді́во, в ді́вственнім рождестві́ Твоє́м болі́зней ма́терніх ізбі́гшая;","гряди́, А́гнця і Па́стиря Ма́ти, у Креста́ Си́на Твоєго́ болі́зні серде́чния понести́ іму́щая.","Гряди́, Ра́досте на́ша, приобщи́тися страсте́м Христо́вим, да в явле́нії Сла́ви Єго́ с Ним возра́дуєшися;","гряди́, в печа́ліх Утіше́ніє, іскуси́тися, я́ко зла́то в горни́лі, да і Сама́ іскуша́ємим помощі́ возмо́жеши.","Гряди́, Обра́дованная, печа́ль роди́вшую жена́м Є́ву возвесели́ти іму́щая;","гряди́, Препросла́вленная, весь мир скорб'я́ми Свої́ми от скорбе́й свободи́ти Хотя́щая.","Гряди́, Честні́йшая всея́ тва́рі Ді́во, всю ви́димую твар рождество́м Свої́м Обнови́вшая;","гряди́, Святі́йшая Святи́х всім Ма́ти, а́нгели і челові́ки во Сре́тенії Твоє́м об'єдини́вшая.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє удиви́ся вели́кому Бо́га на́шего к челові́ком низше́ствію, глаго́люще: чу́дная зрим ни́ні і пресла́вная, непостижи́мая і несказа́нная: Ада́ма бо Созда́вий в об'я́тіях ста́рчих вміща́ється. По́лни конці́ ми́ра бла́гости Єго́, полна́ вся твар хвале́нія Єго́, по́лно все челові́чество снисхожде́нія Єго́. Небе́сная, земна́я і преіспо́дняя по́лни суть благоутро́бія Єго́, по́лни ми́лости Єго́, по́лни щедро́т, по́лни даро́в, по́лни благодія́нія Єго́. Іспо́лнь не́бо і земля́ сла́ви Єго́! Сего́ ра́ди всі язи́ци восплещі́те рука́ми, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я Боже́ственний Богови́дець Симео́н, а́ще і мно́го ізрече́, хва́ляще і благодаря́ще Пренепоро́чную Ма́тер Бо́жию, ро́ждшую ми́ру Бо́га і челові́ка, Спа́са душ на́ших, оба́че не возмо́же благохвали́ти по достоя́нію, Ю́же і преми́рния уми́ недоуміва́ють воспіва́ти, оба́че любо́вію побіжда́ємий, велича́ше Ю, глаго́люще: Святі́йшеє і Ди́вноє Жили́ще Бо́жиє, Ти — єси́ нача́ло, среди́на і коне́ць на́шего пра́здника. Ти возсія́ла єси́ Світ Со́лнця, Ти отве́рзла єси́ істо́чник человіколю́бія Си́на Твоєго́, па́м'ять Твоя́ преви́ше вся́каго сло́ва і вели́чіє Твоє́ превосхо́дить не́мощ на́шу. Молю́ Тя: непреста́нно па́м'ятуй нас хва́лящих Тя і во восто́рзі духо́вном вопію́щих Тебі́ си́це:","Гряди́, ві́чно несконча́ємая Ра́досте на́ша, ра́дость Христа́ всему́ ми́ру яви́вшая;","гряди́, при́сно ублажа́ємая Сла́досте на́ша, Огнь Божества́ рука́ма неопа́льно держа́щая.","Гряди́, Заре́ присносія́тельная, от ве́тхаго ми́ра но́вою благода́тію храм просвіти́вшая;","гряди́, Свіще́ неугаса́ющая, во Срі́теніє Твоє́ ду́ші ві́рних Сві́том Христо́вим осія́вшая.","Гряди́ Огнь Небе́сний рука́ма носи́вшая, да Тобо́ю святи́ня і красота́ во Святи́лище возгори́ться;","гряди́, Світ Невече́рній нетлі́нно, я́ко Присноді́ва, роди́вшая, да Тобо́ю спасе́ніє всім конце́м землі́ возвісти́ться.","Гряди́, Одушевле́нний Киво́те Бо́жий, я́ко Тобо́ю но́вая благода́ть спаси́тельная всему́ ми́ру яви́ся;","гряди́, Ски́нія Бо́жия с челові́ки, я́ко Тобо́ю Бог бого́во в Сіо́ні над всі́ми людьми́ воцари́ся.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 10","ps":["Спасе́нія пропові́дниця яви́ся Богодухнове́нная А́нна проро́чеством сія́ющая і в зако́ні непоро́чная: не отхожда́ше бо от хра́ма Госпо́дня день і нощ в моли́твах і по́сте служа́щи. Та ізше́дши с пра́ведним Симео́ном во срі́теніє Богомладе́нцю Христу́, провеща́ше стра́шная, іспові́дующе Єго́ Творця́ не́бу і землі́. І об'є́мши Того́, приложи́ уста́ своя́ ко усто́м Єго́, і всели́ся Дух во уста́х єя́ і возопи́: Ти єси́ Бог і Син Челові́ч, Син Ца́рствія і унічиже́нія. Ти сли́шиши і безмо́лвствуєши, ви́диши і неви́дим єси́, всеве́дущ і сокрове́н. І та мно́гая проро́чеськи ізрече́ о принесе́нном Младе́нце всім ча́ющим ізбавле́нія во Ієрусали́мі, Богоро́дицю же пропові́дающе велича́ше. О, дщи Фану́їлева, прийди́ і ста́ни с на́ми, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Преві́чний і Сло́ве Бо́жий! Ти пло́тію ни́ні всему́ ми́ру яви́лся єси́ во хра́мі, от Ді́ви Ма́тері, я́ко Младе́нець руконоси́м, да с челові́ки поживе́ши і всім су́щим от Ада́ма, да возвісти́ши спасе́ніє. Дре́вняя ни́ні вся мимоідо́ша і се би́ша вся но́ва. Пра́вда Твоя́ с небесе́ прини́че, і ми́лость Твою́ посла́л єси́ нам, і благода́ть Твоя́ воцари́ся на землі́, я́ко прише́л єси́ взиска́ти і спасти́ поги́бшія. Сего́ ра́ди нікого́же отверга́єши, нікого́же отвраща́єшися, я́коже дре́вле О́зи, і́же прикосну́ся ко Киво́ту Заві́та Твоєго́ і пораже́н бисть сме́ртію. Ни́ні же блудни́ця припа́даєть к Тебі́ і уцелому́дрися, кровоточи́вая прикаса́ється к Тебі́ і очи́стися, митарі́ і грі́шници возлежа́ть с Тобо́ю і в дру́ги Твоя́ приє́млються, я́ко вся тружда́ющіяся і обремене́нния призва́л єси́ к Себі́. Сего́ ра́ди с ра́достію сріта́єм прише́ствіє Твоє́, вопію́ще та́ко:","Гряди́, о Христі́, всіх Царю́, і воста́ни на срі́теніє на́ше;","гряди́, Ісу́се, душ на́ших Врачу́, і ізи́ди на по́мощ і спасе́ніє на́ше.","Гряди́, Па́стирю наш До́брий, на взиска́ніє Прише́дий заблу́ждшаго овча́ти, взищи́ і нас заблу́ждших;","гряди́, Уті́шителю Благи́й, поги́бшую дра́хму взиска́вий і обріти́й, обря́щи ду́ші люде́й поги́бших.","Гряди́, Всеще́дре і Человіколю́бче, і прийми́ нас во оте́чеськия об'я́тія Своя́;","гряди́, Всеми́лостиве і Благоутро́бне, всели́ нас в ра́йськия оби́телі Твоя́.","Гряди́, Уті́шителю скорб'я́щих, защити́ і упра́ви нас в мо́ре жите́йськія суєти́ пливу́щих;","гряди́, Спаси́телю заблу́ждших, спаси́ і воздви́гни нас в бе́здні гріха́ утопа́ющих.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє приноша́ху о явле́нії Твоє́м, Христе́, Богоно́сець Симео́н і пра́ведная А́нна, ду́хом пламені́юще, усти́ же ра́достно пропові́дающе Твоє́ в мир прише́ствіє всім ча́ющим ізбавле́нія. Кни́жници же і фарисе́ї, сли́шаще такова́я о Отроча́те свиді́тельства, негодова́ху, найпа́че же осужда́ху, а́ки я́внаго законопресту́пника Заха́рію, я́ко Ма́тер на мі́сті діви́честім поста́ви, чесо́ ра́ди вско́рі уби́ша єго́ между́ же́ртвенником і алтаре́м. Богомладе́нець же Христо́с отнесе́н во Єги́пет, да бу́деть та́мо в зна́меніє ві́чноє і да ві́дом бу́деть Госпо́дь Єги́птяном і да сотворя́ть та́мо же́ртву і дар, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ во открове́ніє язи́ков, бил єси́, Со́лнце Пра́вди, Христе́, на о́блаці, ле́гці носи́м, я́коже Симео́н днесь проро́чеськи провозгласи́, да яви́ши нача́ло но́вия благода́ті, наче́н от Єги́пта і да́же до послі́дніх землі́, я́ко Ти єси́ Істо́чник Живота́ і Світ челові́ков, да світ во тьмі сві́титься, і тьма Єго́ не об'я́т. Се́ю заре́ю Божества́ Твоє́ю просвіти́ і на́шу душе́вную тьму, да всі возже́гши в се́рдці доброді́телей свіщи́, с Симео́ном і с А́нною, я́ко свіщено́сці но́вії с любо́вію усря́щем Тя, вопію́ще Тебі́ і Пречи́стій Ма́тері Твоє́й си́це:","Гряди́, Ісу́се, Сві́те ми́ра, да во сві́тлості Святи́х Твої́х нас просвіти́ши;","гряди́, Христе́ Спа́се, во Сві́ті Живи́й Непресту́пнем, да во сві́ті Лиця́ Твоєго́ нас обожи́ши.","Гряди́, Со́лнце Пра́вди, я́ко да возсія́єть во днех Твої́х пра́вда і мир на землі́;","гряди́, Сві́те Святи́й, я́ко да при́йдеть в сердця́ на́ша огнь любве́ і ві́ри с небесе́.","Гряди́, Небе́сний Царю́, я́ко да благослове́нно і пресві́тло бу́деть прише́ствіє Твоє́;","гряди́, Тво́рче і Влади́ко, я́ко да с горя́щими світи́льники чистоти́ ізи́дем во срі́теніє Твоє́.","Гряди́, Ти́хий і Невече́рній Сві́те, да в ти́хости і безмо́лвії поживе́м вся дні живота́ своєго́;","гряди́, Єдиноро́дний Си́не Бо́жий і Сло́ве, да с тре́петом і в ра́дості соверши́м спасе́ніє Твоє́.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 12","ps":["Благода́ть но́вая іспо́лнь днесь ве́тхий храм зако́нний, єгда́ прише́л єси́ в онь, Христе́, я́ко Младе́нець руконоси́м, да іспо́лниться Агге́я проро́ка Твоєго́ предрече́ніє: При́йдеть Жела́ємий всі́ми язи́ки і іспо́лню храм Сей сла́вою, зане́ ве́лія бу́деть сла́ва хра́ма сего́ послі́дняго, па́че пе́рваго і на мі́сті сем дам мир. Сего́ ра́ди да украси́ться неізрече́нною Божества́ Твоєго́ заре́ю і на́ша Це́рков но́вая гото́в'ящаяся Тя сві́тло, я́ко Жениха́, прия́ти, і на́ша душе́вния ру́ки просвіти́, да я́коже Симео́н простре́м я в чистоті́ на Срі́теніє Твоє́, с весе́лієм вопію́ще Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще, о Богома́ти, во храм Госпо́день с Боже́ственним Младе́нцем на срі́теніє всему́ ми́ру прише́ствіє Твоє́, восхваля́єм неізрече́нную па́че А́нгел ді́вственную Чистоту́ Твою́, поклоня́ємся Возсія́вшему от Тебе́ Со́лнцю Пра́вди Христу́, с Симео́ном усря́щем Єго́ і при́ймем во об'я́тія Своя́. С А́нною іспові́дуєм Божество́ Єго́, с Іо́сифом принесе́м Єму́ в дар, я́ко два птенця́ голуби́на, на́шу ду́шу і ті́ло, і я́ко с му́дрими ді́вами світи́льники душ на́ших сві́тло украси́м і горя́щия свіщи́ І́стинному Сві́ту Христу́ я́вльшемуся во открове́ніє ми́ра принесе́м, і іспле́тше днесь пі́сні, я́коже цві́ти, принесе́м Тебі́, я́ко віне́ць благодаре́нія сицеви́я похвали́:","Гряди́, Благода́тная Богоро́дице Ді́во, да под кро́вом ді́вства Своєго́ нас в ді́встві і чистоті́ сохрани́ши;","гряди́, Світоно́сная Влади́чня Пала́то, да благода́тію Своє́ю нас дом Ду́ха Свята́го сотвори́ши.","Гряди́, па́че у́тра Світлі́йшая Ді́во, да і нас си́ни дне до конця́ житія́ соблюде́ши;","гряди́, Со́лнце Нося́щая Ма́ти Сві́та, да і нас сві́том благода́ті Твоєя́ просвіти́ши.","Гряди́, вели́каго та́їнства Свята́я Служи́тельниця, да і нас Си́ну Твоєму́ і Бо́гу свя́то служи́ти научи́ши;","гряди́, всему́ ми́ру Блага́я Помо́щнице, да і нас от ми́ра, пло́ті і дия́вола невреди́мо защити́ши.","Гряди́, о, Діви́ці Марі́є, да просвіти́ши на́ші ду́ші помраче́нния страстьми́;","гряди́, о, Ди́вная Отрокови́це, да сохрани́ши лю́ди Твоя́ осліпле́нния гріхми́.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти і Ді́во, Прине́сшая во Святи́лище всіх святи́х Святі́йшеє Сло́во во срі́теніє на́ше і спасе́ніє ми́ру; пра́здничноє приє́мши сіє́ приноше́ніє на́ше, покри́й і соблюди́ нас от вся́кия ну́жди і печа́лі і ізба́ви нас от вся́кия гріхо́вния вра́жия сі́ті. Ти же, я́ко Двер Божества́ нетлі́нно би́вшая, отве́рзи всім спасти́ся жела́ющим врата́ небе́сная, да ізба́вльшеся Тобо́ю от ві́чния му́ки, воспоє́м во Сре́тенії Госпо́днє на возду́сі: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел небе́сних небе́сния ли́ки прини́кше на зе́млю, зрять Своєго́ Творця́ і Влади́ку Перворожде́нна всея́ тва́рі во об'я́тіях Діви́чеських от Ма́тері Неіскусому́жния, я́ко Младе́нця носи́ма і ко хра́му во Ієрусали́м гряду́ща, і ра́дующеся пою́ть Тому́ і Цари́ці Ді́ві хвалу́ пра́здничную:","Гряди́, Царю́ не́ба і землі́, во град Вели́каго Царя́, Сіо́н святи́й;","гряди́, Преви́шній Бо́же, от го́рних висо́т в рукотворе́нний храм земни́й.","Гряди́, Єдиноро́дний Си́не Бо́жий, всели́тися с челові́ки на землі́;","гряди́, Непоро́чний А́гнче Бо́жий, принести́ся ко Го́споду, живу́щему на небесі́.","Гряди́, Чи́стая Голуби́це, Свята́го Ду́ха Безму́жная Неві́сто;","гряди́, Нескве́рная А́гнице, А́гнця Христа́ Нетлі́нная Ма́ти.","Гряди́, Богоізбра́нная Отрокови́це, Бо́га Отця́ Превожделе́нная Дще́ре;","гряди́, Небе́сная Цари́це, всему́ ми́ру Блага́я Влади́чице.","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Кондак 1","ps":["Ізбра́ннаго Царя́ Ізбра́нная Ма́ти зри́ться ни́ні от Вифлеє́ма в Ієрусали́м гряду́ща, Богомладе́нець же Ісу́с, я́ко на о́блаці ле́гці во об'я́тіях Тоя́ носи́м бива́єть. Ми же недосто́йнії, сріта́юще Царя́ Сла́ви і Пресвяту́ю Ма́тер Ді́ву, с Симео́ном ста́рцем вопіє́м Преблагослове́нній:","Гряди́, Пречи́стая, Госпо́дь с Тобо́ю і Тобо́ю с на́ми."]},{"h":"Молитва","ps":["Го́споди Ісу́се Христе́, Єдиноро́дний Си́не і Сло́ве Бо́жий, дре́вле во проро́ціх ви́дінний, я́коже зерца́лом в гада́ній, в послі́док же дній сих пло́тію от Пресвяти́я Ді́ви Марі́ї нетлі́нно рожде́нний і в четиредеся́тний день сей во Святи́лище во срі́теніє всему́ ми́ру от Тоя́, я́ко Младе́нець руконоси́м, явле́нний і во об'я́тіях пра́веднаго Симео́на во спасе́ніє всім су́щим от Ада́ма носи́мий! Коль пресла́вно і пресві́тло Твоє́ на руку́ Богома́тері во храм Госпо́день принесе́ніє і от свята́го ста́рця Боже́ственноє срі́теніє Твоє́! Днесь небеса́ веселя́ться і ра́дується земля́, я́ко ви́діна би́ша ше́ствія Твоя́, Бо́же, ше́ствія Бо́га на́шего Царя́, І́же во Святі́м. Дре́вле Мойсе́й восхо́дить ви́діти сла́ву Твою́, но не возмо́же уви́діти лиця́ Твоєго́, зане́ яви́л єси́ єму́ то́чію за́дняя Своя́. В пресві́тлий же день сей срі́тенія Твоєго́ Ти яви́л єси́ Себе́ челові́ком во святи́лище, сія́я неізрече́нним Сві́том Божества́, да вку́пі с Симео́ном ви́дять Тя лице́м к лицю́ і рука́ми да ося́жуть Тя, і восприє́мши во об'я́тія своя́, да позна́ють Ті Бо́га во пло́ті прише́дша. Сего́ ра́ди прославля́єм неізрече́нноє снисхожде́ніє і ве́ліє человіколю́біє Твоє́, я́ко прише́ствієм Твої́м дарова́л єси́ ни́ні небе́сную ра́дость па́дшему дре́вле ро́ду челові́чу: Ти бо пра́ведним судо́м Свої́м ізгна́л єси́ прароди́телі на́ші із рая́ сла́дости в мир сей, ни́ні же поми́ловал єси́ нас і па́ки отве́рзл нам ра́йськія оби́телі і обрати́л єси́ плач наш на ра́дость, да па́дший Ада́м к тому́ уже́ да не стиди́ться Тебі́ за преслуша́ніє і да не бу́деть скрива́тися Лиця́ Твоєго́, Тобо́ю призива́ємий, я́ко Ти прише́л єси́ ни́ні, да во́зьмеши на Себі́ гріх єго́, да оми́єши єго́ Своє́ю кро́вію і да облече́ши єго́ на́га су́ща в ри́зу спасе́нія і оде́жду весе́лія і украси́ши єго́, я́ко неві́сту красото́ю. Нам же всім Боже́ственноє Твоє́ срі́теніє воспомина́ющим, сподо́би с му́дрими ді́вами ізи́ти на срі́теніє Твоє́, Небе́сному Жениху́ на́шему, с горя́щими свети́льниками ві́ри, любві́ і чистоти́, да улицезри́м оча́ми ві́ри Боже́ственноє Лице́ Твоє́, да воспри́ймем Тя в душе́вния об'я́тія своя́, і да понесе́м Тя в се́рдці своє́м во вся дні Живота́ своєго́, да бу́деши нам в Бо́га і ми в лю́діє Твої́. В послі́дній же і Стра́шний день прише́ствія Твоєго́, єгда́ всі святі́ї ізи́дуть на послі́днєє і вели́коє срі́теніє Твоє́ на возду́сі, сподо́би і нам усрі́сти Тя, да та́ко всегда́ с Го́сподом бу́дем. Сла́ва милосе́рдію Твоєму́, Сла́ва Ца́рствію Твоєму́, Сла́ва смотре́нію Твоєму́, Єди́не Человіколю́бче, я́ко Твоє́ єсть Ца́рство, і Си́ла, і Сла́ва со Безнача́льним Твої́м Отце́м і Пресвяти́м і Благи́м і Животворя́щим Твої́м Ду́хом ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Ра́дуйся, Благода́тная Богоро́дице Ді́во, / із Тебе́ бо возсія́ Со́лнце Пра́вди - Христо́с, Бог наш, / просвіща́яй су́щия во тьмі. / Весели́ся і ти, ста́рче пра́ведний, / приє́мий во об'я́тія Свободи́теля душ на́ших, // да́рующаго нам воскресе́ніє."]},{"h":"Кондак, глас 1","ps":["Утро́бу Діви́чу освяти́вий Рождество́м Твої́м, / і ру́ці Симео́ні благослови́вий, / я́коже подоба́ше, предвари́в, / і ни́ні спасл єси́ нас, Христе́ Бо́же, / но умири́ во бранеіх жи́тельство // і укріпи́ лю́ди, ї́хже возлюби́л єси́, Єди́не Человіколю́бче."]},{"h":"Величання","ps":["Велича́єм Тя, Живода́вче Христе́, і чтим Пречи́стую Ма́тер Твою́, Є́юже по зако́ну ни́ні прине́слся єси́ в храм Госпо́день."]},{"h":"Задостойник","ps":["Богоро́дице Ді́во, / упова́ніє христия́ном, / покри́й, соблюди́ і спаси́ на Тя упова́ющих.","В зако́ні сі́ні і писа́ній / о́браз ви́дим, ві́рнії: / всяк му́жеський пол, ложесна́ разверза́я, свят Бо́гу. / Тім Перворожде́нноє Сло́во Отця́ Безнача́льна, / Си́на, Первородя́щася Ма́терію неіскусому́жно, / велича́єм."]}],"notes":[]},{"u":"Акафіст Воздвиженню Хреста Господнього","e":"Akathist to the Exaltation of the Cross of the Lord","secs":[{"h":"Кондак 1","ps":["Прийді́те, христоимени́тії лю́діє, соста́вим похвалу́ Честно́му Кресту́, на нем же Христо́с, Цар сла́ви, ру́ці распросте́р, возведе́ нас на пе́рвоє блаже́нство, із него́же низпадо́хом пре́лестію змі́євою. Ти же, о пресвяти́й Кре́сте, я́ко імі́яй прису́щую тебі́ си́лу Расп'я́таго Христа́, спаса́й і сохраня́й от вся́ких бід любо́вно зову́щия ті:","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци, я́ко Бо́жії служи́теліє, Крест обстоя́ще, во́льную страсть Христа́ Жизнода́вця прославля́ють. Ми же страда́ньми Того́ ві́чния сме́рти ізба́вльшеся, подража́я го́рнім си́лам, ра́достно взива́єм:","Ра́дуйся, Кре́сте, я́ко на тебі́ Христо́с Бог наш, во́лею ру́ці распросте́р, спасе́ніє на́ше соді́ла;","ра́дуйся, я́ко распросте́ршимся на тебі́ Христо́м преступле́ніє Ада́ма і Є́ви, просте́рших ру́ці ко дре́ву запреще́нному, упраздни́ся.","Ра́дуйся, я́ко воздви́жену би́вшу на тебі́, а́ки престу́пну, Законода́вцю, дре́вняя кля́тва, я́же на нас би́вшая, потреби́ся;","ра́дуйся, я́ко соде́явшимся на тебі́ стра́нним та́їнством род челові́чеський от тлі сме́ртния свободи́ся.","Ра́дуйся, я́ко Пострада́вшим і Уме́ршим на тебі́ жа́ло сме́рти сокруши́ся;","ра́дуйся, того́ ра́ди страда́нія Бог с челові́ки примири́ся.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 2","ps":["Ви́дя па́дших челові́ков, Го́споди, Ти вочелові́чився, крест і смерть во́льно пло́тію претерпі́л єси́ за род наш, да от сме́рти ві́чния ізба́виши іспове́дающия Тя, Си́на Бо́жия і вопію́щия Ті: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челове́ч ізнемога́єть в постиже́нії ве́лія та́йни Твоєго́, Христе́, воплоще́нія і во́льнаго за ни страда́нія: ка́ко Ти, Бог сий безстра́стний, страсть кре́стную, я́ко челові́к, претерпі́л єси́ і сіє́ ору́діє сме́рті Твоєя́ соді́лал єси́ істо́чником жи́зні і спасе́нія всім благоче́стно в Тя ві́рующим і хвале́бно воспіва́ющим:","Ра́дуйся, Кре́сте, на не́мже соді́яся та́їнство, от ві́ка предопреділе́нноє;","ра́дуйся, я́ко на тебі́ соверши́ся на́ше іскупле́ніє, многообра́зні во о́бразіх і сі́ніх пред'явле́нноє.","Ра́дуйся, я́ко уме́рий на тебі́ Жизнода́вець, кров і во́ду істочи́, і́миже гріхи́ на́ша омива́ються;","ра́дуйся, я́ко ка́плями святе́йшей кро́ве Єго́ гріхо́вния стру́пи душ на́ших очища́ються.","Ра́дуйся, Кре́сте, я́коже дре́во живо́тноє, є́же єсть посреді́ рая́ Бо́жия, христия́ном вожделі́нний;","ра́дуйся, плода́ми безсме́ртія у́мно нас пита́ющий і наде́ждою жи́зні ві́чния малоду́шіє на́ше ободря́ющий.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 3","ps":["Крест Твой, а́ще і дре́во ви́димо єсть существо́м, но Боже́ственною оді́яно єсть си́лою, і чу́вственноє ми́ра виявля́ємо у́мно на́ше чудотвори́ть спасе́ніє, подвиза́я пі́ти Тебі́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще пред очи́ма на́шима Крест пресвяти́й, святолі́пним поклоне́нієм той почита́єм распе́ншагося ра́ди на нем Спа́са Христа́, і лобиза́юще взива́єм:","Ра́дуйся, Кре́сте, просла́вленний послуша́нієм і страда́нієм Христо́вим;","ра́дуйся, возвели́ченний возвише́нієм на тебі́ Си́на Бо́жия, І́же весь мир от паде́нія Ада́мля воздви́же.","Ра́дуйся, я́ко сби́вшагося на тебі́ ужа́снаго та́їнства землі́ ужасе́ся і вострепета́, а́ки би хотя́щи поглоти́ти законопресту́пния;","ра́дуйся, я́ко закла́вшуся на тебі́ А́гнцю Бо́жию заві́са хра́ма раздра́ся і же́ртва ветхозаве́тная упраздни́ся.","Ра́дуйся, Кре́сте, я́ко распа́дшуся под тобо́ю ка́мню, каменносерде́чнії ро́ди євре́йстії неві́рієм от Бо́га отпадо́ша, благода́ті же свяще́нства і ца́рства лиши́шася;","ра́дуйся, я́ко омрачи́вшуся со́лнцю в стра́сті Христо́вой нощ многобо́жія пре́йде і світ ві́ри возсія́.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 4","ps":["Бу́рею зло́би ди́шуще і за́вистію дви́жими, первосвяще́нници іуде́йстії скри́ша в зе́млю Крест Твой, Христе́ Бо́же, да не бу́деть обличе́нієм безу́міє їх; но той, я́ко сокро́вище драго́є, із нідр землі́ возсія́, тща́нієм благочести́вия цари́ці Єле́ни обрете́нний і на ра́дость всему́ ми́ру явле́нний, с богокра́сною пі́снію: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́дівше тогда́ христия́нстії лю́діє честна́го Креста́ обрі́теніє, прославля́ху распе́ншагося на нем Христа́ Бо́га, «Го́споди, поми́луй» взива́юще. Ми же ни́ні, подража́юще їм, прославля́єм Крест Єго́ святи́й хвале́ньми сицеви́ми:","Ра́дуйся, Кре́сте, в зе́млю сокрове́нний і оскверне́нноє гріха́ми на́ше єстество́ земно́є освяти́вий;","ра́дуйся, явле́нієм свої́м із нідр земни́х хули́телей воплоще́нія і Божества́ Христо́ва посрами́вий.","Ра́дуйся, я́ко Пострада́вий на тебі́ пло́тію прия́ вся́ку власть на Небесі́ і на землі́, да всіх і вся к Бо́гу Отцю́ приведе́ть;","ра́дуйся, я́ко Уме́рий на тебі́ я́ко челові́к си́лою Божества́ Своєго́ сокруши́ закле́пи а́да і ізведе́ отту́да душі́ пра́ведних.","Ра́дуйся, Кре́сте, я́ко разбо́йник благоразу́мний, Христу́ сраспя́вийся, Того́ іспові́давий, тобо́ю, а́ки лі́ствицею, на Небеса́ взи́де;","ра́дуйся, я́ко і всіх отсіче́нієм страсте́й Христу́ сраспина́ющихся возво́диши в Ца́рствіє Небе́сноє.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 5","ps":["Го́споди, при Мойсе́є іногда́ проро́ці то́чію о́браз Креста́ Твоєго́ явля́єм побіжда́ше вразі́ Твоя́, ни́ні же са́мий Крест Твой іму́ще, по́мощі про́сим: укріпи́ Це́рков Твою́ і да́руй єй побі́ди на враги́, да расточа́ться всі вразі́ Твої́, не вопію́щії Ті: Аллилу́я."]},{"h":"Ікос 5","ps":["Честна́го Креста́, Христе́, ді́йство прообрази́в Мойсе́й, побіди́ Амали́ка в пусти́ні Сина́йстій: єгда́ бо простира́ше ру́ці, креста́ о́браз творя́, укріпля́хуся лю́діє; ни́ні же все веще́й сбитіє́ в нас іспо́лнися: днесь Крест воздвиза́ється, і де́мони бі́гають, днесь твар вся от тлі свободи́ся, я́ко вся Креста́ ра́ди возсія́ша нам дарова́нія. Ті́мже, ра́дующеся, вопіє́м:","Ра́дуйся, Кре́сте, ору́жіє Христо́во стра́шноє, єго́же де́мони трепе́щуть;","ра́дуйся, я́ко си́лою на тебі́ Расп'я́таго Христа́ бісо́встії по́лчища дале́че прогоня́ються.","Ра́дуйся, я́ко си́лою ді́йствующия в тебі́ Боже́ственния благода́ті побі́ди на сопроти́вния христолюби́вим лю́дем да́руються;","ра́дуйся, я́ко от тебе́, я́ко високоро́сленнаго і многоплодови́таго дре́ва Христо́ва на тебі́ страда́нія, плоди́ жи́зні і спасе́нія нам проізраста́ють.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 6","ps":["Пропові́дником си́ли і Божества́ Христо́ва яви́ся іногда́ животворя́щеє дре́во Кре́стноє, єгда́ прикоснове́нієм свої́м воскреси́ ме́ртваго і к жи́зні возведе́ єго́, є́же ви́дівше, мно́зі от іуде́й і язи́к позна́ша ве́лію благоче́стія та́йну: я́ко спасе́нія ра́ди челові́чеськаго, Бог во пло́ті яви́ся і страсть кре́стную претерпі́, да спасе́ть вопію́щия Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Я́коже дре́во ра́йськоє преве́ліє, возви́сися на Голго́фі честни́й Крест Христо́в, отону́дуже во всю вселе́нную распростре́ ми́сленния ві́тві благода́ті і Распе́ншагося на нем: под єго́же сі́нію обріта́ють прохла́ду пали́мії зно́єм страсте́й і хотя́щії благоче́стно жи́ти о Христі́ Ісу́се. Ті́мже і ми, благода́ті Того́ прича́стници, ве́село взива́єм:","Ра́дуйся, святи́й Кре́сте, дре́вом жи́зні, Ада́ма ра́ди в Єде́мі насажде́нним, проображе́нний;","ра́дуйся, но́вим Ада́мом, ру́ці на тебі́ распросте́ршим, ми́ру явле́нний.","Ра́дуйся, я́ко под сінь благода́тнаго защище́нія твоєго́ всі ві́рнії прибіга́ють;","ра́дуйся, я́ко милосе́рдієм Дарова́вшаго нам тебе́ ка́ющіїся грі́шници огня́ геє́нськаго ізбіга́ють.","Ра́дуйся, Кре́сте, утіше́ніє на́ше в ско́рбіх і печа́ліх;","ра́дуйся, живи́тельная отра́до і по́мощ ізнемога́ющим в борбі́ с прило́гами страсте́й, ми́ра і дия́вола.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 7","ps":["Хотя́ яви́ти ро́ду челові́чеському бла́гості і милосе́рдія Своєго́ неізслі́димую пучи́ну, Крест Твой, Го́споди, дал єси́ нам тве́рда блюсти́теля і прогони́теля де́монов. Ті́мже всі ми, і́же в Тя ві́рующії, прославля́єм вели́чіє стра́сті Твоєя́, благода́рно пою́ще Тебі́: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вни діла́ яви́л єси́, Го́споди, Кресто́м Твої́м честни́м: распе́ншуся бо Ті на том пло́тію, вся твар ізміни́ся: со́лнце лучи́ своя́ сокри́, основа́нія землі́ восколеба́хуся, ад сокруши́ся держа́вою вла́сті Твоєя́ і ізведе́ ю́зники, я́же от ві́ка содержа́л єсть. Сего́ ра́ди ув'яза́єм той си́ми пі́сненними цві́ти:","Ра́дуйся, Кре́сте, я́ко пострада́вшему на Тебі́ вся твар сострада́ше, я́ко Творцю́ своєму́ і Влади́ці;","ра́дуйся, я́ко си́лу Того́ і Божество́ свиді́тельствоваху со́лнце помраче́нієм і земля́ колеба́нієм.","Ра́дуйся, я́ко Уме́рий на тебі́ не удержа́н бисть в ме́ртвих, но, разруши́в держа́ву сме́рті, в тре́тій день воскре́се;","ра́дуйся, я́ко воскре́сшу Тому́ про́повідь єва́нгельськая, от ли́ка апо́стольськаго наче́ншаяся, во вся конці́ землі́ ізи́де.","Ра́дуйся, Кре́сте, я́ко тобо́ю кумирослуже́ніє і многобо́жіє язи́чеськоє упраздни́ся;","ра́дуйся, я́ко тебе́ ра́ди пра́вая ві́ра во Єди́наго Бо́га, в Тро́йці сла́вимаго, по всей землі́ утверди́ся.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 8","ps":["Стра́нно Бо́га вочелові́чшася і на Кресті́ ра́сп'ята би́вша ми́сленно ви́дяще, устрані́мся су́єтнаго ми́ра, ум на Небеса́ прело́жше. Сего́ ра́ди Бог на зе́млю сни́де і на Крест взи́де, да тім, а́ки лі́ствицею, на Небеса́ возведе́ть вопію́щия Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Днесь Ада́м со Є́вою весели́ться, предлежа́щий ви́дяще Крест, і́мже пораже́н бисть супоста́ть, і́же дре́вле в раї́ вкуше́нієм запреще́ннаго пло́да тіх прельсти́вий і плі́нники себі́ сотвори́вий. Ті́мже і ми, сра́дующеся пра́отцем на́шим о ізбавле́нії от пліне́нія на́шего душе́внаго, благогові́йно воспіва́єм:","Ра́дуйся, Кре́сте, я́ко на тебі́ Па́стир до́брий ду́шу Свою́ положи́ за о́вці Своя́ і да́же до а́да сни́де, іща́ заблу́дших;","ра́дуйся, я́ко Той не презрі́ ді́ло руку́ Своє́ю, Ада́ма со Є́вою, но со іни́ми пра́ведники ісхити́ я із а́да, я́ко із че́люстей зві́ря крі́пкаго, і в рай всели́ їх.","Ра́дуйся, я́ко на тебі́ пригвожде́нному Христу́ пла́менноє ору́жіє плещи́ даде́ і Херуви́м, Єде́м храня́щий, отступи́ от дре́ва жи́зні;","ра́дуйся, я́ко ми, ни́ні Креще́нієм возрожде́ннії, во Христі́ но́виє лю́діє, невозбра́нно причаща́ємся ра́йськия пи́щі.","Ра́дуйся, Кре́сте, же́зле си́ли Христо́ви, от Сіо́на по́сланний, і́мже ми пасе́мся на па́житіх єва́нгельських уче́ній;","ра́дуйся, я́ко тобо́ю невреди́ми сохраня́ємся от волко́в душегу́бних, я́ко льво́ве рика́ющих і і́щущих, кого́ поглоти́ти.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 9","ps":["Вся́ких бід і ко́зней вра́жиїх ізба́ви ни, Кре́сте треблаже́нний, я́ко приє́мий благода́ть і си́лу от пригвожде́ннаго на тебі́ Христа́, Єму́же я́ко Бо́гу і Ізба́вителю на́шему благода́рственно і хвале́бно поє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство вся́коє земноро́дних не довлі́єть к прославле́нію Креста́ Твоєго́, Го́споди, на не́мже спасе́ніє на́ше соді́лал єси́; ті́мже, недоуміва́юще восхвали́ти той по достоя́нію, взива́єм си́це:","Ра́дуйся, Кре́сте, я́ко вознесе́нний на тебі́ Спас ми́ра мно́зі лю́ди в позна́ніє Своє́ призва́ і до ни́ні призива́єть;","ра́дуйся, я́ко возсія́вий на тебі́, а́ки на сві́щниці, Світ і́стинний вся конці́ землі́ сві́том богові́дінія озаря́єть.","Ра́дуйся, я́ко ни́ні Восто́к і За́пад Пострада́вшаго на тебі́ прославля́ють;","ра́дуйся, я́ко і тя, я́ко подно́жіє Христо́во, всі ві́рнії, вознося́ще, прославля́ють.","Ра́дуйся, я́ко от тебе́, я́ко от неізсяка́ємаго істо́чника, христоимени́тії лю́діє оби́ліє благ ві́чних почерпа́ють.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щим нам і под сінь защище́нія твоєго́ прибега́ющим, бу́ди помо́щник, пресвяти́й Кре́сте, сохраня́я ни от всіх зол си́лою на тебі́ Расп'я́таго Христа́, Єму́же я́ко Бо́гу і Ізба́вителю на́шему благода́рственно і хвале́бно поє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́, огражда́ющая нас от бід і напа́стей, Кре́сте всечестни́й, і столп крі́пкий проти́ву лиця́ вра́жия, к нему́же неви́димії бори́теліє приступи́ти не смі́ють, боя́щеся взира́ти на си́лу Твою́. Сего́ ра́ди с ві́рою огражда́ємся святи́м твої́м зна́менієм і ве́село воспіва́єм:","Ра́дуйся, пречестни́й Кре́сте Христо́в, от нападе́нія духо́в зло́би нас защища́яй;","ра́дуйся, от разли́чних стріл їх невреди́ми ни сохраня́яй.","Ра́дуйся, я́ко от зна́менія твоєго́, с ві́рою благоче́стно твори́маго, вся си́ли а́да, я́ко дим от ві́тра, ісчеза́ють;","ра́дуйся, я́ко тобо́ю вся крі́пость їх, я́ко воск от лиця́ огня́, істаява́єть.","Ра́дуйся, я́ко святі́ї му́ченици, зна́менієм твої́м огражда́шеся і і́м'я Христо́во призва́вше, вся́кий, вид муче́ній му́жественно претерпі́ша;","ра́дуйся, я́ко преподо́бнії отці́ по́мощію си́ли Божества́, зна́менію твоєму́ прису́щия, бісо́вськая страхова́нія і страсте́й возста́нія побіди́ша.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим Ті, всечестни́й Кре́сте, і смире́нно мо́лимся расп'я́тому на тебі́ Христу́ Бо́гу на́шему, І́же дарова́ нам тебі́ во отра́ду і утіше́ніє в ско́рбіх, да стра́стію Своє́ю ізба́вить нас от страсте́й душевре́дних і научи́ть благові́рно воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том благода́ті Бо́жієй, та́їнственні ті прису́щия, просвіти́ на́ша душе́вная чу́вствія, Кре́сте пресвяти́й, да то́ю озаря́ємі і наставля́ємі, не по́ткнемся о ка́мень собла́зна, но да возмо́жем путе́м за́повідей Бо́жиїх пра́во ше́ствовати во всей жи́зні на́шей, воспіва́юще ті си́це:","Ра́дуйся, непрестаю́щих чуде́с Христо́вих ве́стниче і милосе́рдія Єго́ к ро́ду челові́чеському пропові́дниче;","ра́дуйся. Кре́сте, ро́да челові́ча обновле́ніє і Но́ваго Заві́та Христо́ва печа́ть і утвержде́ніє.","Ра́дуйся, торжество́ ві́ри христия́нськия і благонаде́жний я́корю упова́нія на́шего;","ра́дуйся, святи́х хра́мов Бо́жиїх украше́ніє і домо́в благочести́вих огражде́ніє.","Ра́дуйся, поле́й і вертогра́дов благослове́ніє; ра́дуйся всіх стихі́й освяще́ніє.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 12","ps":["Благода́ть Твою́ всемо́щную пода́ждь нам, Го́споди, да послі́дуєм Тебі́, Влади́ці на́шему, взе́мше крест наш, не гвоздьми́ пригвожда́ющеся тому́, но труда́ми, воздержа́нієм і смире́нієм, да та́ко прича́стници бу́дем страда́ній Твої́х, от ни́хже істека́ють пото́ци Жи́зні Ві́чния, напая́ющия вся правові́рния, благоче́стно пою́щия Ті: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще вели́чіє твоє́, всечестни́й Кре́сте, восхваля́єм тя всі, я́ко побідоно́сний ски́петр Царя́ Небе́снаго, на́шего же спасе́нія всера́достноє зна́меніє, ті́мже і вопіє́м:","Ра́дуйся, Кре́сте, правосла́вних христия́н держа́во і несокруши́моє їх огражде́ніє;","ра́дуйся, святи́телей украше́ніє і всіх подви́жников ві́ри і благоче́стія си́ла і подкріпле́ніє.","Ра́дуйся, Кре́сте, от колибе́лі і до гро́ба на всіх путеіх жи́зні нас огражда́яй і по сме́рті на возду́шних мита́рствах от духо́в зло́би нас защища́яй;","ра́дуйся, я́ко под зна́менієм твої́м почива́ющії, уме́ршії во ві́рі і благоче́стії, в послі́дній день воскре́снуть в жизнь ві́чную.","Ра́дуйся, Кре́сте, явле́нієм свої́м на Небесі́ предвари́ти іми́й сла́вноє Второ́є прише́ствіє Христо́во;","ра́дуйся, я́ко распе́ншії Христа́ і всі неві́рнії у́зрять тя тогда́ і го́рці возрида́ють, лю́б'ящії же Го́спода, зря́ще тя, вельми́ возра́дуються.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 13","ps":["О Пречестни́й і Животворя́щий Кре́сте Госпо́день, всіх христия́н утіше́ніє! Тя ни́ні предлежа́ща ви́дяще, возво́димся ми́слію к расп'я́тому на тебі́ Христу́, Єму́же і мо́лимся смире́нно, да тебе́ ра́ди поми́луєть нас, грі́шних, і сподо́бит в селе́ніїх ра́йських воспіва́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци, я́ко Бо́жії служи́теліє, Крест обстоя́ще, во́льную страсть Христа́ Жизнода́вця прославля́ють. Ми же страда́ньми Того́ ві́чния сме́рти ізба́вльшеся, подража́я го́рнім си́лам, ра́достно взива́єм:","Ра́дуйся, Кре́сте, я́ко на тебі́ Христо́с Бог наш, во́лею ру́ці распросте́р, спасе́ніє на́ше соді́ла;","ра́дуйся, я́ко распросте́ршимся на тебі́ Христо́м преступле́ніє Ада́ма і Є́ви, просте́рших ру́ці ко дре́ву запреще́нному, упраздни́ся.","Ра́дуйся, я́ко воздви́жену би́вшу на тебі́, а́ки престу́пну, Законода́вцю, дре́вняя кля́тва, я́же на нас би́вшая, потреби́ся;","ра́дуйся, я́ко соде́явшимся на тебі́ стра́нним та́їнством род челові́чеський от тлі сме́ртния свободи́ся.","Ра́дуйся, я́ко Пострада́вшим і Уме́ршим на тебі́ жа́ло сме́рти сокруши́ся;","ра́дуйся, того́ ра́ди страда́нія Бог с челові́ки примири́ся.","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Кондак 1","ps":["Прийді́те, христоимени́тії лю́діє, соста́вим похвалу́ Честно́му Кресту́, на нем же Христо́с, Цар сла́ви, ру́ці распросте́р, возведе́ нас на пе́рвоє блаже́нство, із него́же низпадо́хом пре́лестію змі́євою. Ти же, о пресвяти́й Кре́сте, я́ко імі́яй прису́щую тебі́ си́лу Расп'я́таго Христа́, спаса́й і сохраня́й от вся́ких бід любо́вно зову́щия ті:","Ра́дуйся, Честни́й Кре́сте, всера́достноє зна́меніє на́шего іскупле́нія."]},{"h":"Молитва","ps":["Кре́сте честни́й, храни́тель душі́ і ті́лу бу́ди мі: о́бразом свої́м бі́си низлага́я, враги́ отгоня́я, стра́сті упраздня́я і благогові́ніє да́руя мі, і жизнь, і си́лу, соді́йствієм Свята́го Ду́ха і честни́ми Пречи́стия Богоро́диці мольба́ми. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Спаси́, Го́споди, лю́ди Твоя́ / і благослови́ достоя́ніє Твоє́, / побі́ди на сопроти́вния да́руя // і Твоє́ сохраня́я Кресто́м Твої́м жи́тельство."]},{"h":"Кондак, глас 4","ps":["Вознеси́йся на Крест во́лею, / тезоімени́тому Твоєму́ но́вому жи́тельству, / щедро́ти Твоя́ да́руй, Христе́ Бо́же, / возвесели́ нас си́лою Твоє́ю, / побі́ди дая́ нам на сопоста́ти, / посо́біє іму́щим Твоє́ ору́жіє ми́ра, // непобіди́мую побі́ду."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / і чтим Крест Твой святи́й, / і́мже нас спасл єси́ // от рабо́ти вра́жия."]},{"h":"Задостойник","ps":["Велича́й, душе́ моя́, / пречестни́й Крест Госпо́день.","Та́їн єси́, Богоро́дице, рай, / невозді́ланно возрасти́вший Христа́, / І́мже кре́стноє живоно́сноє на землі́ насади́ся Дре́во; / тім ни́ні возноси́му, // поклоня́ющеся Єму́, Тя велича́єм."]}],"notes":[]},{"u":"Акафіст на Зішестя Святого Духа","e":"Akathist to the Descent of the Holy Spirit","secs":[{"h":"Кондак 1","ps":["Возбра́нний Пара́кліте, Царю́ не́ба і землі́, Животворя́щий, Спаси́тельний і Всесвяти́й Душе́, ви́ну от Отця́ ісходяяй і в Си́ні почива́яй, соше́ствієм же во ви́ді о́гненних язи́ков Апо́столи просвіти́вий, снизойди́ і ни́ні с го́рних висо́т на ни недосто́йния раби́ Твоя́, і породи́ нас к но́вой благодатной жи́зні, да воспоє́м Тебі́:","Прийди́, Уті́шитель Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь Сил с небесе́ соше́д і плотсько́є восприє́м єстество́ на́ше, при́йде на зе́млю, да спасе́ть Кресто́м і Воскресе́нієм Свої́м па́дший дре́вле род челові́ч, і па́ки восше́д на не́бо, сі́де одесну́ю Бо́га і Отця́, да совознесеть і обожи́ть єстество́ на́ше, і да сози́ждеть на землі́ Ца́рство пра́вди і ми́ра о Ду́сі Свя́те, єго́же нікто́же мо́жеть ви́діти, а́ще кто не роди́ться сви́ше Ті́мже Ду́хом. Сего́ ра́ди Госпо́дь наш, ко Отцю́ отходя́, не оста́ви нас си́рих, но обітова́ грі́шником свої́м, глаго́люще: Аз умолю́ Отця́ і іна́го Уті́шителя дасть вам, да бу́деть с ва́ми во вік, Дух І́стини, Єго́же мир не мо́жеть прия́ти, ніже́ зна́єть Єго́, і́же от Отця́ ісхо́дить, Той свиді́тельствуєть о Мні. Уті́шитель, Дух Святи́й, Той ви научи́ть всему́ і воспом'яне́ть, я́же рек вам. Сему́ обітова́нію вне́млюще, апо́столи моля́ху Тебі́, Святи́й Уті́шителю, да ско́ро сни́деши, вопію́ще Тебі́ си́це:","Прийди́, Уті́шителю Благи́й, ви́ну от Отця́ ісходяяй.","Прийди́, Небе́сній Пара́кліте, при́сно в Си́ні почива́яй.","Прийди́, Пода́телю жи́зні, приклони́ небеса́ і сни́ди.","Прийди́, Небе́сний Царю́, прикосни́ся гора́м і воздим'я́ться.","Прийди́, Всесвяти́й Душе́, і наста́ви нас сві́том і́стини Твоєя́.","Прийди́, кристаловидний Животі́, і просвіти́ мир огне́м благода́ті Твоєя́.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 2","ps":["Ви́дів Госпо́дь по Воскресе́нії Своє́м ученики́ Своя́ єще́ плотська́я му́дрствующих і земно́є ца́рство ча́ющих, яви́ся, їм две́рем затворе́нним, ду́ну і преподаде́ їм Ду́ха Свята́го благода́ть просвіща́ющую помишле́нія їх і уготовляющую їх к прия́тію суще́ственному та́їнства Боже́ственнаго, глаго́люще: Приймі́те Дух Свят, І́мже отпустіте́ гріхи́, отпу́стяться їм, і і́мже держіте́, держа́ться. Ті́мже, приє́мше такову́ю власть духо́вную, укріпи́шася ду́хом, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний о гряду́щем Ца́рствії Бо́жії открива́я, Госпо́дь наш собра́ ученики́ Своя́ вся вку́пі на горі́ Єлео́нстій, і повелі́ їм по Вознесе́нії Єго́ на не́бо от Ієрусали́ма не отлуча́тися, но жда́ти обітова́нія О́тча, до́ндеже облеку́ться си́лою сви́ше, я́ко не по мно́зіх днех і́муть крести́тися Ду́хом Святи́м. І та́ко запові́дав, рече́ їм: наше́дшу Свято́му Ду́ху на ви, приймі́те си́лу і бу́дете Мі свиді́телі во Ієрусали́мі і во всей Іуде́ї і Самарі́ї і да́же до послі́дніх землі́. І сія́ рек, вознесе́ся на не́бо. Ученици́ же, возврати́вшеся во Ієрусали́м, взидо́ша в го́рницю і бя́ху всі терп'я́ще єдиноду́шно в моли́тві і моле́нії і поще́нії с женамії Марі́єю Ма́терію Ісу́совою і с бра́тією Єго́, ча́юще соше́ствіє Уті́шителя і пою́ще Єму́ си́це:","Прийди́, Душе́ Господствуяй і Животворяяй, Отцю́ Собезнача́льний і Соприсносу́щний.","Прийди́, Душе́ І́стинний і Всеблаги́й, с Сино́м Купносущний і Равноче́стний.","Прийди́, Душе́ Влади́чний, от Оте́чеськаго соста́ва і от Боже́ственних і Безнача́льних уст Єго́ несказа́нно Ісходяяй.","Прийди́, Душе́ Христо́в, Соіпостасноє Диха́ніє і Прему́дрости Си́ло, в Си́ні неразді́льно пребива́яй.","Прийди́, Непостижи́мий Просвіти́телю, открове́ніє та́йни Пресвяти́я Тро́йці лю́дем дарова́ти восхоті́вий.","Прийди́, Прему́дрий Всепосіти́телю, весь мир благода́тними дарованіями іспо́лнити возжела́вий.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственною облече́н Святи́й Петр, воста́в посреди́ учени́к, рече́ к ним: Му́жіє бра́тіє, прекло́ньше колі́на, се́рдця же го́ре возве́дше, помо́лимся ко Го́споду на́шему, обетовавшему Уті́шителя іна́го, да сози́ждеть чи́сти се́рдця на́ша і да обнови́ть дух прав во утро́бах на́ших і да сотвори́ть го́рницю сію́ Це́рков Бо́жию і ско́ро да ниспо́шлеть нам Ду́ха Всеблага́го Своєго́, Єму́же всі да воспої́м єди́ними усти́ і єди́ним се́рдцем: Алиллуя."]},{"h":"Ікос 3","ps":["Іму́ще страх ве́лій, Апо́столи в смуще́нії би́ша, ка́ко немощни́м їм су́щим, я́коже агнцям без Па́стиря, пропові́дати Єва́нгеліє всей тва́рі, сего́ ра́ди, єгда́ скончава́хуся дні́є П'ятьдеся́тници, би́ша всі вку́пі на моли́тві і вознесо́ша те́плі моле́ніє ко Па́стирю Своєму́, глаго́люще: Царю́ А́нгелов, управля́яй всі́ми на землі́ і на мо́рі! Раби́ Твої́ вопію́ть к Тебі́: ско́ро посли́ нам Всесвята́го Ду́ха Твоєго́. Госпо́дь же їх пло́тію на небесі́х Отцю́ сосідя́й, усли́шав моле́ніє сіє́ рече́: Самовла́стний Уті́шителю, снизойди́, ча́ють бо Тя ученици́ Мої́, ї́хже собра́х к Тебі́ і ко Отцю́, те́плі бо вопію́ть к Тебі́, глаго́люще:","Прийди́, Душе́ Благи́й і наста́ви нас на зе́млю пра́ву.","Прийди́, Сві́те Святи́й, і напра́ви стопи́ на́ші на стезю́ ми́рну.","Прийди́, Влади́ко Непостижи́ме, всім хотя́щим спасти́ся несумні́нноє упова́ніє.","Прийди́, Неізслі́димий Царю́, всім жа́ждущим пра́вди благода́тноє насище́ніє.","Прийди́, Душе́ Живи́й і Животворя́й, Твоє́ю бо благода́тію живе́м і дви́жемся і єсьми́.","Прийди́, Сві́те Святи́й і Светоносяй, Твоє́ю бо чистото́ю возвиша́ємся, светлеємся і храни́ми.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 4","ps":["Бу́рноє диха́ніє ве́ліє внеза́пу пронесе́ся, ученико́м в Сіо́ні со́бранним і в го́рниці об часі́ третьем дне молящимся, і бисть шум, я́ко гром с небесе́, тишині́ ве́лієй о́крест су́щей, і іспо́лни весь дом, іді́же бя́ху сідя́ще. І колеба́шеся хра́мина, я́ко лодія, і убоя́шеся апо́столи мня́ще, я́ко от диха́нія бу́рна паде́ться го́рниця, і всі в стра́сі возопи́ша: О, Влади́ко, утиши́ колеба́ніє і посли́ Всесвята́го Ду́ха Твоєго́, Єму́же согла́сно да воспоє́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще шум с небесе́ і колеба́ніє возду́шноє ви́дяще, боголюби́вії Апо́столи і всі су́щії с ни́ми іспо́лнишася у́жаса, зане́ в диха́нії бу́рні соше́ствіє Уті́шителево уразумі́ша і в шу́мі небе́снім глас Госпо́день ощути́ша, в себі́ поми́сливше: се глас Госпо́день возгремі́ в крі́пості. Се глас Го́спода Істоча́ющаго пла́мень огня́, я́коже Дави́д предрече́. Се бу́ря от Го́спода, я́коже Ієремия возвісти́. В сіє́ вре́м'я Госпо́дь наш восхоті́ посла́ти Уті́шителя іна́го і дарова́ти Зако́н нов, я́коже дре́вле на Сина́ї. Та́мо от гла́са Єго́ колеба́шеся гора́, здісь же от диха́нія Уті́шителева потрясе́ся го́рниця, та́мо би́ша гро́ми і мо́лнія, здісь же пронесе́ся шум с небесе́. Оба́че приступихом не ко горі́ осязаємой і огне́м пилающей, но к Сіо́нстій горі́, к Ієрусали́му Небе́сному, ко Хода́таю Заві́та Но́ваго, да при́ймем Ца́рство Непоколеби́мо, і да воспри́ймем благода́ть Ду́ха, є́ю же послу́жим благоуго́дно, вопію́ще Єму́ си́це:","Прийди́, Душе́ Стра́ха Бо́жия, не во огні́ і бу́рі, но во гла́сі хла́да тонка́, да нас от ду́ха боя́зні ра́бськия свободи́ши.","Прийди́, Душе́ Синоположе́нія, апо́столи во єди́но ста́до совокупи́вий, да і нас ча́да Бо́жия сотвори́ши.","Прийди́, Душе́ Прему́дрості і Открове́нія, да воспом'яне́ши нам вся словеса́ Христо́ви в позна́ніє Єго́.","Прийди́, Душе́ ві́дінія і благоче́стія, да просвіти́ши о́чі серде́чний сві́том за́повідей Єго́.","Прийди́, Душе́ Бо́жия Святи́ні, да облече́ши нас си́лою сви́ше от Свої́х небе́сних висо́т.","Прийди́, Душе́ вся́кия благости́ні, да окропи́ши нас росо́ю благода́ті по мно́жеству Свої́х щедро́т.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 5","ps":["Богоно́снії Апо́столи єще́ па́че іспо́лнишася стра́ха, єгда́ по гла́се шу́ма се бисть їм виді́ніє но́воє па́че пе́рваго і яви́шася о́гненнії язи́ци, разделяющіяся сю́ду і сю́ду, і сідо́ша по єди́ному на ко́ємждо от них над глава́ми їх, да іспо́лниться Дави́да пра́отця предрече́ніє: Бог я́ві при́йдеть і не умолчи́ть, огнь пред Ним возгори́ться і о́крест Єго́ бу́ря зі́льна. Сим духоно́сним огне́м Уті́шителя просвіща́ємії, апо́столи со стра́хом і с ра́достію возопи́ша, сріта́юще прише́ствіє Єго́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше соше́ствіє Уті́шителя во ви́ді о́гненних язи́к, Апо́столи удиви́шася, ка́ко диха́ніє бу́рно с пла́менем совокупи́ся, і ка́ко с ві́три видени би́ша світи́льници, с росо́ю же і́скри. Найпа́че же об'яша їх страх Боже́ственний, єгда́ о́гненнії язи́ци, сі́дше над глава́ми їх, не опалиша власи́, но па́че просвещаху ми́слі їх, і та́ко огнедохнове́нним озаре́нієм Свята́го Ду́ха просвіща́ємі, уразумі́ша прорече́ніє Дави́дово: Огнь от Лиця́ Єго́ воспла́мениться: у́гліє возгорі́ся от него́. І приклони́ небеса́ і сни́де. І просла́виша Бо́га, я́ко при́йде обетованний Уті́шитель, да о́гненноє креще́ніє восприя́вше от Него́, благода́рственно возопію́ть єму́ си́це:","Прийди́, Огнено́сний Душе́, да о́гненним креще́нієм весь мир просвіти́ши.","Прийди́, огнь подая́й, Бо́же, да те́рніє на́ших прегріше́ній попалиши.","Прийди́, огнь Боже́ственний на зе́млю низводя́й, Го́споди, да угасшия світи́льници душ на́ших па́ки возжеши.","Прийди́, о́гненния ріки́ апо́столом ороша́яй, Влади́ко, да ті́ми весь мир огне́м благода́ті Твоєя́ обнови́ши.","Прийди́, во о́гненних язи́ціх всему́ ми́ру на моли́тві возглаголавий Душе́, воздиха́нії неізглаго́ланними научи́ нас о чесо́м моли́тися Небе́сному Отцю́.","Прийди́, во огні́ і бу́рі Божество́ Пресвяти́я Тро́йці Откри́вий, Царю́, огнедохнове́нним диха́нієм воспламени́ огнь Боже́ственния любве́ і в на́ші хла́дния се́рдця.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 6","ps":["Пропові́дник ди́вний, боже́ственний Петр, ви́дів, я́ко о́гненноє виді́ніє іспо́лни стра́ха ученики́, возопи́: не бо́йтеся, огнь сей нежегомий єсть, я́коже дре́вле неопали́мая купина́, іли́ я́коже пла́мень Вавило́нськия пе́щі, і́же не опали́ три о́троки. Сего́ ра́ди ки́йждо от нас да отри́неть страх із душі́, і да не убої́ться неопальнаго пла́мені, огнь бо сей да разумі́єм, я́коже ро́зі, я́ко цві́ти на глава́х на́ших, і́миже увінча́, украси́ і озари́ нас Всесвяти́й Дух, Єму́же всі с ра́достію да воспої́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ ве́ліє просвіще́ніє благода́ті Бо́жієй всій Це́ркві Христо́вой во вели́кий сей П'ятидесятний день, єгда́ во о́гненних язи́ціх Ти Сам суще́ственно снисшел єси́ на апо́столи і на вся верующия, Святи́й Животворя́щий і Всеси́льний Душе́, Єди́н Сий от Пресвяти́я Тро́йці, і бога́тно ізли́л єси́ не ні́кия Отчії да́ри, я́коже пре́жде, но от всея́ полноти́ Божества́ ізли́л єси́ от Ду́ха Твоєго́ на вся́ку плоть, не в мі́ру бо пода́сть Бог Ду́ха, і потеко́ша ріки́ води́ живи́я благода́ті Твоєя́ от Ієрусали́ма во всю вселе́нную, і та́ко завершишася тіле́сния діла́ Христо́ви і прия́ша нача́ло діла́ Твоя́, Душе́, да сози́ждеться Ца́рствіє Твоє́ в челові́ціх і да преобразиться Тобо́ю ме́ртвенная плотська́я жизнь на́ша на живу́ю і духо́вную. Сего́ ра́ди всі води́мії Тобо́ю да воспоє́м Тебі́ си́це:","Прийди́, Уті́шительний Душе́, с небе́сних висо́т соше́дий, да безкни́жния ученики́ Христо́ви неботаї́нники сотвори́ши.","Прийди́, Небе́сний Царю́, везді́ сий і вся ісполня́яй, да во Христа́ верующия духо́вния жи́зні сопричте́ши.","Прийди́, неумаля́ємоє Сокро́вище благода́ті, да приобщиши нас даро́в Твої́х, і райською ра́достію возвеселі́мся.","Прийди́, Неув'яда́ємий Цві́те чистоти́, да окропи́ши нас іссо́пом Твої́м і па́че сні́га убелимся.","Прийди́, Зижди́телю всея́ Тва́рі, да ца́рствуєши і господствуєши над всі́ми си́лами душі́ моєя́.","Прийди́, Влади́ко Не́ба і Землі́, да властвуєши і управля́єши над всі́ми движеніями се́рдця моєго́.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 7","ps":["Хотя́ спасти́ вся язи́ки, Го́споди, дарова́л єси́ ученико́м Твої́м во о́гненних язи́ціх Ду́ха Твоєго́, да по обітова́нію Твоєму́ возглаго́лють но́вими язи́ки, і всі іспо́лнишася Ду́ха Свя́та і нача́ша глаго́лати іни́ми язи́ки, я́коже Дух дая́ше їм провещевати, да всі наро́ди от всіх язи́к на пра́здник прише́дшия, усли́шать їх проповедующия свої́ми їх язи́ки. Во Вавило́ні іногда́ разміси́шася язи́ци де́рзости ра́ди столпотворе́нія, да разділя́ться язи́ки, ни́ні же богові́дінія ра́ди умудри́шася язи́ци, в соєдине́ніє бо всіх призва́ Ви́шній, да согла́сно сла́в'ять всесвята́го Ду́ха, пою́ще Єму́ єди́ними усти́ і єди́нім се́рдцем: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до Твоє́, Уті́шителю, бисть во зна́меніє всім, і іспо́лни у́жаса язи́ков собра́нія на пра́здник прише́дших: ви́дяху бо ученико́в Спасових о́гненними язи́ки глаго́лющих і ки́йждо от них свою́ бесі́ду сли́шаше. І дивля́хуся всі, друг дру́гу глаго́люще: не всі ли сі́ї глаго́лющії галилеяне суть, і ка́ко ми сли́шим ки́йждо свой язи́к, в не́мже роди́хомся? Ка́ко сотвори́шася соотечественници всім язи́ком? Ви́діл ли єсть Петр Єги́пет? Жив'я́ше ли когда́ Андре́й в Месопота́мії? Ви́діша ли когда́ Памфилі́ю си́ни Заведеови? Ка́ко яви́шася сі́ї Ри́мляном, я́ко не ва́рвари, Парф'яном, я́ко їм подо́бнії, Мидяном же, я́ко свої́. Оба́че єли́ці благогові́йнії би́ша, ті́ї просла́виша Бо́га, вопію́ще Уті́шителю си́це:","Прийди́, во проро́ціх глаго́лавий Боже́ственний Душе́, возглаго́ли ми́рная і блага́я в сердця́х на́ших.","Прийди́, во Апо́століх пропові́давий о́гненними язи́ки Безсме́ртний Царю́, возсія́й мо́лніями Божества́ в душа́х на́ших.","Прийди́, Животе́ Безнача́льний, разділе́нния язи́ки в соєдине́ніє призва́вий, і в нас дух вра́жия разділе́нія всеконе́чно потреби́.","Прийди́, Люби́ Безконе́чная, Апо́столи на ве́чері сою́зом любве́ связа́вий, і в нас дух бра́тськия любве́ наві́ки насади́.","Прийди́, с небесе́ снисшедий Уті́шителю наш, да на стезі́ небе́сния наста́виши нас, Тебе́ пою́щих.","Прийди́, от земни́х го́ре возвиша́яй Бо́же наш да от сла́дости мирськи́х красо́т ізба́виши нас Тебі́ вопію́щих.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 8","ps":["Стра́нними глаго́ли віща́юще, возглаго́лаша святі́ї Апо́столи стра́нния уче́нія і стра́нния велі́нія Святи́я Тро́йці, от Ду́ха Свята́го просвіща́ємі. Високоглаго́ливими же пропові́дующе язи́ки, не челові́ком глаго́лаху пе́рвіє, но Бо́гу, та́йни віща́юще ду́хом, я́коже боже́ственний Па́вел глаго́леть, би́ша бо во восто́рзі духо́вном, неізглаго́ланними воздиха́нії Свята́го Ду́ха наставля́ємі. Неверующим же от язи́к сіє́ Ду́ха ді́йство пянство непщева́шеся би́ти. Оба́че мно́зі благоговейни би́вше, ужаса́хуся, і недоумевающеся, друг дру́га вопроша́ху: что у́бо хо́щеть сіє́ би́ти? І с ві́рою просла́виша Бо́га, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь іспо́лнен бив огнено́сния благода́ті Ду́ха Бо́жия, святи́й Петр, воста́в с єдинона́десятьми, воздви́же глас свой і нача́ проповедовати со́бранним от язи́к вели́чія Бо́жия і стра́шноє Твоє́, Святи́й Уті́шителю, во о́гненних язи́ціх схожде́ніє, є́же проро́к Іої́ль дре́вле предрече́, глаго́ля о сем вели́ком і просвещенном дне Госпо́днем: “Ізолью от Ду́ха Моєго́ на вся́ку плоть, на раби́ Моя́ і на раби́ні Моя́, і прореку́ть си́нове ва́ші і дще́рі ва́ші і ю́ноши ва́ші виді́нія у́зрять”. Сим Святи́м Ду́хом іспо́лненнії би́вше, Апо́столи не вино́м упи́шася, но упоє́нієм Ду́ха, но́ваго виногра́да рожде́нія Боже́ственнаго весе́лія приобщи́вшеся, вопію́ще і глаго́люще си́це:","Прийди́, Боже́ственний Уті́шителю, во Іорда́ні на Спа́са на́шего во ви́ді голуби́ні снисшедий, да́руй нам крилі́ голуби́ні кро́тости і чистоти́, да полетим і почі́єм.","Прийди́, Сладча́йший Душепосетителю, в Сіо́ні ко апо́столом во о́гненних язи́ціх прише́дий, ороси́ нас огне́м благода́ті Твоєя́, да ві́рою і любо́вію воспламенеєм.","Прийди́, Святи́й Живонача́льний Душе́, дре́вле в челові́ціх плоть су́щих пребива́ти не восхоті́вий, свободи́ нас зако́ном ду́ха от зако́на пло́ті, да па́ки живе́ши в нас.","Прийди́, Вели́кий Непостижи́мий Бо́же, в послі́док дній сих от Ду́ха Твоєго́ на вся́ку плоть ізливий, сподо́би нам не по пло́ті жи́ти, но по ду́ху, да всегда́ пребу́деши в нас.","Прийди́, Душе́ вся́кия чистоти́, помози́ нам, да плоть не похотству́єть на дух наш, і да Тобо́ю води́ми бу́дем.","Прийди́, При́сний наш Животе́, спобори нам, да не сі́єм в плоть і тлі́ніє, но в дух, да от Ду́ха Твоєго́ жизнь ві́чную по́жнем.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ челові́чеськоє возвесели́ся днесь о соше́ствії Твоє́м, Уті́шителю Благи́й, зане́ во ве́тхую П'ятидесятницю при Синає би́вшую, всі лю́діє іздале́че стоя́ху в стра́хі і в у́жасі, всей го́ре дим'ящейся і во огні́ би́вшей, єди́н бо то́чію Мойсе́й взи́де на верх єя́ во мрак, іді́же бя́ше Бог. Ни́ні же, всі сли́шавшії Петра́ умили́шася се́рдцем, уві́роваша і крести́шася, і приложи́ся в день той душ, я́ко три ти́сящи, і та́ко в сей вели́кий день П'ятидеся́тници положи́ся нача́ло Це́ркві Христо́вой на землі́ і всі іспо́лнишася Ду́ха Свята́го і ду́хом взидо́ша на го́ру Госпо́дню благода́ті Бо́жия, всі оча́ми ві́ри Го́спода узрі́ша і с ра́достію возопи́ша Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї Боже́ственния святі́ї Апо́столи, пре́жде безкнижнії ри́баріє, ни́ні же му́дрії богосло́вці яви́шася, пре́жде починяху мре́жі своя́, ни́ні же облече́ннії си́лою сви́ше от Ду́ха Свята́го, нача́ша про́повідь Сло́ва Бо́жия, пре́жде то́чію риб уловляху, ни́ні же сотвори́шася ловці́ челові́ков і лю́ди безчи́сленнії із глубо́кия тьми нача́ху ізимати. Пре́жде боя́щіїся, ни́ні же дерзнове́ніє приявшії і ра́дости іспо́лненнії от Тебе́, Святи́й Уті́шителю, ті́ї уразумі́ша, я́ко но́ва твар ни́ні суть і какови́й ве́лій дар получи́ша по обітова́нію Госпо́дню, сего́ ра́ди ни́ні отбіже́ от них страх і дух не́мощі і ті́ї ощути́ша, я́ко уже́ і́муть си́лу по повелі́нію Госпо́дню пройти́ да́же до коне́ць вселе́нния, уча́ще вся язи́ки і крестя́ще їх во і́м'я Отця́ і Си́на і Свята́го Ду́ха. Сего́ ра́ди во весе́лії ду́ха возопи́ша си́це:","Прийди́, Сві́те Живонача́льний, да вся язи́ки сві́том богові́дінія просвіти́ши.","Прийди́, Животе́ Безнача́льний, да вся челові́ки к но́вой жи́зні во Христі́ приобщиши.","Прийди́, Теплото́ Живительная, да ду́хом любве́ Твоєя́ хла́дния се́рдця неві́рних язи́ков воспламениши.","Прийди́, Сла́досте Неізрече́нная, да благода́тію Твоє́ю всіх вкуси́вших ю па́че ме́да і со́та усладиши.","Прийди́, Ра́дованіє на́ше непреста́нноє, да нас ско́рбних і печа́льних очище́нієм со́вісти возвесели́ши.","Прийди́, Сокро́вище на́ше превожделі́нноє, да нас ни́щих і убо́гих мно́жеством дарова́ній духо́вних обогати́ши.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 10","ps":["Спасе́нія день — сей вели́кий П'ятидеся́тници пра́здник, в о́ньже, Уті́шителю Благи́й, Це́рков Христо́ву до сконча́нія ві́ка облагодатил єси́ і всю твар Твої́м Живоно́сним диха́нієм обнови́л єси́, Везді́ сий і вся ісполня́яй, Ти іді́же хо́щеши дишиши, вся живи́ши і повсю́ду в ми́рі разлива́єши свою́ живонача́льную си́лу: Тебе́ поє́ть со́лнце, Тебе́ сла́вить луна́, Тебі́ слу́жить світ, Тебе́ рабо́тають істо́чници, Тобо́ю єди́н дождь напоя́єть зе́млю і бива́єть біл в кри́ніх, і красе́н в розах, багря́н же во фіялках, та́ко многообра́зна благода́ть Твоя́: єди́ному у́бо дає́ши сло́во прему́дрости, друго́му — дар проро́чества, іно́му — сказа́ніє Боже́ственних Писа́ній: єди́наго укріпля́єши на целому́дріє, друга́го учи́ши пости́тися і подвиза́тися, о́ваго же уготовля́єши на му́ченичество. Вся же сія́ ді́йствуєши Ти, єди́ний Душе́, разділя́я коєму́ждо хо́щеши, да вся́коє диха́ніє поє́ть Тебі́: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Небе́сний і жи́зні Пода́телю! Ца́рство Твоє́ — Ца́рство всіх віко́в і Влади́чество Твоє́ во вся́ком ро́ді і ро́ді. Соше́д же на апо́столи. Ти яви́л єси́ і́ми Ца́рство не от ми́ра сего́ — Це́рков Христо́ву, ю́же іспо́лнил єси́ безчи́сленними да́ри благода́ті Твоєя́, і́миже, я́ко фі́нікс процвіте́ і я́ко кедр, і́же в Лива́ні умно́жися. І та́ко Твоє́ю благода́тію напоя́єма, Це́рков процвіте́ многочи́сленними со́нми ді́вственник, учи́телей, му́чеников, іспові́дников, преподо́бних, пустинников, да іспо́лниться Осі́ї проро́ка предрече́ніє: процвіте́ть, я́ко цвіт і простре́ть коре́ніє, я́ко дубра́ва і я́ко ма́слина плодови́та бу́деть. Зря́ще у́бо сі́ї со́нми духоно́сних отце́в, Тобо́ю, Святи́й Душе́, возращенних, воззове́м Тебі́ такова́я:","Прийди́, Істо́чниче Боже́ственних сокро́вищ, вдохни́ нам світоно́сний Твоя́ дарова́нія.","Прийди́, Пода́телю і Соверши́телю на́шего освяще́нія, освяти́ ум, се́рдце і вся на́ша помишле́нія.","Прийди́, благості і милосе́рдія Неізнуря́ємоє Храни́лище, сохрани́ в нас жизнь духо́вную под кро́вом Твоєя́ бла́гости.","Прийди́, настоя́щих і гряду́щих благ Несконча́ємоє Сокро́вище, соблюди́ нас в чистоті́ со́вісти в предначатіє ві́чния ра́дости.","Прийди́, па́дших Всенаде́жноє Воста́ніє, Тобо́ю бо істоча́ються благода́тния струї́ напояющия вся́ку твар ко оживле́нію.","Прийди́, ме́ртвих ду́хом і ті́лом Благо́є Воздвиже́ніє, Тобо́ю бо подаю́ться вся си́ли к животу́ і благоче́стію, воздвизающіявсяку плоть к Воскрешенію.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 11","ps":["Пі́ніє духо́вноє воспоє́м Тебі́, Святи́й Уті́шителю, Твоє́ во о́гненних язи́ціх на Апо́столи Соше́ствіє пра́зднующе і сим Па́вловим глаго́лом послі́дующе: “помолю́ся ду́хом, помолю́ся і умо́м, воспою́ ду́хом, воспою́ і умо́м”. І та́ко ду́хом на моли́тві і в служе́нії пламені́юще, да не угаси́м плотоугодієм Ду́ха Твоєго́, во свято́м креще́нії восприятаго, но при́сно да взира́єм на уві́ровавших в день Соше́ствія Твоєго́: ті́ї бо внима́юще сло́ву Петро́ву: “спаса́йтеся от ро́да сего́ развраще́ннаго”, ви́ну бя́ху в уче́нії апо́стол, в обще́нії і преломле́нії Хлі́ба Жи́зні і в моли́твах, і бисть на вся́кой душе́ страх Бо́жий, і бя́ху всі вку́пі єдиноду́шно, іму́ще вся о́бща, і с ра́достію в простоті́ се́рдця воспіва́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́та со́лнечнаго світлі́є яви́ся благода́ть Твоя́, Світоно́сний Душе́, вся бо просветляєши, очища́єши і освіща́єши Твої́м огнено́сним осія́нієм. Ти бо соше́л на Пресвяту́ю Ді́ву Марі́ю, соді́лал єси́ Ю Пресві́тлий храм ді́вства і Пречи́стий дом Божества́ Си́ну Бо́жию. В явле́нії же Твоє́м во Іорда́ні при Креще́нії Госпо́днем во ви́ді голуби́ні Ти отве́рзл єси́ небеса́ гріхопаде́нієм Ада́мовим заключе́нная і обожи́л єси́ Пречи́стую плоть Христо́ву. В Соше́ствії же Твоє́м на Апо́столи іспо́лнил єси́ Боже́ственнаго присутствія Своєго́ всю Це́рков, Неві́сту Христо́ву, да бу́деть непоро́чна і свя́та. Сего́ ра́ди то́чиши в Ней проро́чествія, і свяще́нники соверша́єши, собира́єши весь собо́р церко́вний, і сходиши, я́ко огнь с небесе́ в Боже́ственную Литургі́ю і во всіх та́їнствах, і та́ко вся Це́рков одіва́ється сві́том благода́ті Твоєя́, я́ко ри́зою, да во Сві́ті Твоє́м у́зрим Світ, і да воспоє́м Тебі́ си́це:","Прийди́, чистото́ю Сія́ющий Душе́, Святу́ю Ді́ву Чи́сту в рождестві́ сохрани́вий, да і нам благода́ть ді́вства і чистоти́ преподаси.","Прийди́, небеса́ разверзший Небе́сний Царю́, на Спа́са Христа́ при Креще́нії низшедий, да і всім ві́рующим в Него́ путь на не́бо отве́рзеши.","Прийди́, Со́лнце Незаходи́моє і Несокрива́ємоє, да світ возсіяши пра́ведним і пра́вим се́рдцем весе́ліє.","Прийди́, Сія́ніє Присносіяющеє і Немерцающеє, да внутр нас возсія́єши Це́рков Бо́жия Ду́ха в Твоє́ Боже́ственноє посіще́ніє.","Прийди́, Сві́те Святи́й і Животворя́й, просвіти́ мир Твої́м Боже́ственним осія́нієм.","Прийди́, огню́ от огня́ Проісходя́й і Боготворя́й, озари́ нас Твої́м огнено́сним вдохнове́нієм.","Прийди́, Уті́шителю Благи́й, всели́ся в ни і спаси́ душі́ на́ша."]},{"h":"Кондак 12","ps":["Благода́ть духоносную дарова́л єси́, Уті́шителю Святи́й, всій Це́ркві Христо́вой во вели́кий день Святи́я П'ятидеся́тници, я́коже і пре́жде ви́ну спребивал єси́ Владике Христу́ во днех Єго́ пло́ті, я́ко же вели́кий в богословіх святи́й Григо́рій вити́йствуєть: “Рожда́ється Христо́с і Дух предворяєть. Креща́ється Христо́с і Дух свиді́тельствуєть. Іскуша́ється Христо́с і Дух возво́дить (в пусти́ню). Соверша́єть си́ли Христо́с і Дух сопу́тствуєть. Возно́ситься Христо́с і Дух преємствуєть”. Сего́ ра́ди і нача́тки Божества́ подає́ши ни́ні, Святи́й Душе́, єстеству́ пе́рстному, да па́ки возведе́ши є к пе́рвому ра́йському благоро́дію і да обожи́ши є во о́браз Вознесе́ннаго на небеса́ єстества́ Христо́ва. Ми же ісчести́ не могу́ще многочи́сленная па́че піска́ морська́го благодія́нія дарова́ній Твої́х, вопіє́м Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще, Боже́ственний Душе́, Твою́ Живонача́льную благода́ть, обновля́ющую лице́ землі́ дохнове́нієм Твої́м, поклоня́ємся Твоєму́ во о́гненних язи́ціх на Апо́столи соше́ствію, і ві́руєм, я́ко по обітова́нію Христо́ву ви́ну Твоя́ благода́ть во Святі́й Це́ркві пребу́деть, до́ндеже па́ки при́йдеши в послі́дній день во о́бщеє Воскресе́ніє во є́же воздви́гнути вся от ві́ка умершія, я́ко же святи́й Ієзекі́їль предрече́ глаго́ля: “от чети́ріх ві́тров при́йде, Душе́, і вду́ни в ме́ртвия ко́сті сія́ і да оживу́ть. І вни́де в них Дух Жи́зні і ожи́ша і ста́ша на нога́х свої́х собо́р мног зіло́”. Тогда́ не посрами́ нас вопію́щих Тебі́ си́це:","Прийди́, Утіше́ніє і Ра́досте моя́, усли́ши м'я в день ско́рби і печа́лі моєя́.","Прийди́, Диха́ніє і Жизнь моя́, бу́ди мі єди́н дух со мно́ю до са́мия сме́рти моєя́.","Прийди́, Блестящеєся одія́ніє душі́ моєя́, покри́й вну́треннюю наготу́ і безобра́зіє гріхопаде́нія моєго́.","Прийди́, Теплі́йшеє очище́ніє со́вісти моєя́, отми́й скве́рну душі́ і ті́ла моєго́ чи́стими слеза́ми прише́ствія Твоєго́.","Прийди́, Пи́ще Неізрече́нная і Нетлі́нная, напита́й а́лчущий дух мой в жизнь ві́чную безсме́ртія плода́ми.","Прийди́, Питіє́ Боже́ственноє і превожделі́нноє, напо́й жа́ждущую ду́шу мою́ благоче́стія вода́ми.","Прийди́, Уті́шителю Благи́й, всели́ся в ни і спаси́ душі́ на́ша."]},{"h":"Кондак 13","ps":["О, Небе́сний Пара́кліте і Душе́ Всесвяти́й, от Отця́ Ісходя́й і Сино́м Прише́дий! Прийми́ ма́лоє сіє́ от всея́ душі́ приноси́моє Тебі́ благодаре́ніє. Прийди́ к нам і пребу́ди ви́ну в Це́ркві, да не уга́снеть в нас Боже́ственний пла́мень Тобо́ю возже́нний. І сподо́би нам ду́хом пламенети і плотоугодія не твори́ти в по́хотіх, да нікогда́же уга́снеть дух наш і да ви́ну прославля́ти бу́дем Тя в душа́х і тілесі́х на́ших, і та́ко возрожденнії Тобо́ю, чи́стим ду́хом і чи́стими усти́ воспоє́м Єди́ному Бо́гу во Святі́й Тро́йці: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь Сил с небесе́ соше́д і плотсько́є восприє́м єстество́ на́ше, при́йде на зе́млю, да спасе́ть Кресто́м і Воскресе́нієм Свої́м па́дший дре́вле род челові́ч, і па́ки восше́д на не́бо, сі́де одесну́ю Бо́га і Отця́, да совознесеть і обожи́ть єстество́ на́ше, і да сози́ждеть на землі́ Ца́рство пра́вди і ми́ра о Ду́сі Свя́те, єго́же нікто́же мо́жеть ви́діти, а́ще кто не роди́ться сви́ше Ті́мже Ду́хом. Сего́ ра́ди Госпо́дь наш, ко Отцю́ отходя́, не оста́ви нас си́рих, но обітова́ грі́шником свої́м, глаго́люще: Аз умолю́ Отця́ і іна́го Уті́шителя дасть вам, да бу́деть с ва́ми во вік, Дух І́стини, Єго́же мир не мо́жеть прия́ти, ніже́ зна́єть Єго́, і́же от Отця́ ісхо́дить, Той свиді́тельствуєть о Мні. Уті́шитель, Дух Святи́й, Той ви научи́ть всему́ і воспом'яне́ть, я́же рек вам. Сему́ обітова́нію вне́млюще, апо́столи моля́ху Тебі́, Святи́й Уті́шителю, да ско́ро сни́деши, вопію́ще Тебі́ си́це:","Прийди́, Уті́шителю Благи́й, ви́ну от Отця́ ісходяяй.","Прийди́, Небе́сній Пара́кліте, при́сно в Си́ні почива́яй.","Прийди́, Пода́телю жи́зні, приклони́ небеса́ і сни́ди.","Прийди́, Небе́сний Царю́, прикосни́ся гора́м і воздим'я́ться.","Прийди́, Всесвяти́й Душе́, і наста́ви нас сві́том і́стини Твоєя́.","Прийди́, кристаловидний Животі́, і просвіти́ мир огне́м благода́ті Твоєя́.","Прийди́, Уті́шителю Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Кондак 1","ps":["Возбра́нний Пара́кліте, Царю́ не́ба і землі́, Животворя́щий, Спаси́тельний і Всесвяти́й Душе́, ви́ну от Отця́ ісходяяй і в Си́ні почива́яй, соше́ствієм же во ви́ді о́гненних язи́ков Апо́столи просвіти́вий, снизойди́ і ни́ні с го́рних висо́т на ни недосто́йния раби́ Твоя́, і породи́ нас к но́вой благодатной жи́зні, да воспоє́м Тебі́:","Прийди́, Уті́шитель Благи́й, всели́ся в ни, і спаси́ душі́ на́ша."]},{"h":"Молитва на Зішестя Святого Духа","ps":["О, Небе́сний Царю́, Уті́шителю Святи́й, Душе́ І́стини, везді́ сий і вся ісполня́яй, нікогда́же начинаємий, ніже́ престая́й, но со Отце́м і Сино́м при́сно Су́щий, пе́рвіє во А́нгельських Во́їнствах действовавий, свяще́ніє да́руя; і при миробитії в нача́лі верху́ води́ носивийся, я́ко жи́зні Пода́тель, в рай же первозда́нния лю́ди диха́нієм жи́зні воодушевивий і сла́дким обще́нієм Боже́ственним утешавий я, по гріхопаде́нії же прароди́телей на́ших не восхоті́вий с па́дшими сина́ми челові́чеськими пребива́ти, зане́ плоть би́ша, но то́чію во ізбранніх патріа́рсіх і проро́ціх дре́вле отце́м глаго́лавий, в послі́док же дній сих, восхоті́в ізлити от Ду́ха Своєго́ на вся́ку плоть, пе́рвіє на Честні́йшую Го́рніх Сил Пресвяту́ю Ді́ву Марі́ю низшедий і ве́ліє та́їнство Воплоще́нія Си́на Бо́жия То́ю неізрече́нно соверши́вий, і па́ки на Том же Си́не Бо́жиєм, во пло́ті на Іорда́н пришедшем, во ви́ді голуби́ні почи́вий, по сем же во вели́кий день П'ятидеся́тници суще́ственно во виді́нії о́гненних язи́к на Апо́столи соше́дий і си́ми всю вселе́нную просвіти́вий і Святу́ю Це́рков до сконча́нія ві́ка Своє́ю Боже́ственною благода́тію ізоби́льно іспо́лнивий, во є́же па́дшеє єстество́ на́ше обожи́ти і па́ки к ра́йському блаже́нству возврати́ти! При́зри у́бо в сей вели́кий, соверше́нний і коне́чний П'ятидесятний пра́здник на моле́нія рабо́в Твої́х колінопреклоне́нно Тебі́ возноси́мий, і очи́сти нас свяще́нним на́йтієм Твої́м от мно́жества согріше́ній на́ших во всем житії́ на́ми соді́янних. Єди́не Чи́стий і Пресвяти́й Душе́, очи́сти нас от мно́гія нечистоти́ на́шея, да не па́ки оста́виши нас, а́ще по пло́ті жи́ти бу́дем, я́ко не і́мать обита́ти Дух Твой в челові́ціх плоть су́щих, зане́ плоть і кров Ца́рствія Бо́жия наслі́дити не мо́гуть. Сего́ ра́ди мо́лим Тя: угаси́ живоно́сним диха́нієм Твої́м весь пла́мень страсте́й на́ших, да не твори́м плотоугодія в по́хотіх, но води́мії Тобо́ю, да бу́дем прославля́ти Тя в душа́х і тілесі́х на́ших. І ізба́ви нас от ду́ха пра́здности, уни́нія, печа́лі і го́рдості і да́руй нам дух кро́тости і чистоти́, дух смире́нія і цілому́дрія, дух терпі́нія і любве́, да при́йдеши во вну́треннюю хра́мину душ на́ших і воцари́шися та́мо над страстями на́шими, во є́же сі́яти нам ктому́ уже́ не в плоть і тлі́ніє, но в дух, да от Ду́ха Твоєго́ по́жнем живо́т ві́чний в послі́днєє Воскресе́ніє і просла́вим Тя с ли́ки святи́х со Отце́м і Сино́м во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Благослове́н єси́, Христе́ Бо́же наш, / І́же прему́дри ловці́ явле́й, / низпосла́в їм Ду́ха Свята́го, // і ті́ми уловле́й вселе́нную, Человіколю́бче, сла́ва Тебі́."]},{"h":"Кондак, глас 8","ps":["Єгда́ снизше́л язи́ки слія́, / разділя́ше язи́ки Ви́шній, / єгда́ же о́гненния язи́ки раздая́ше, / в соєдине́ніє вся призва́, // і согла́сно сла́вим Всесвята́го Ду́ха."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / і чтим Всесвята́го Ду́ха Твоєго́, / Єго́же от Отця́ посла́л єси́ // Боже́ственним ученико́м Твої́м."]}],"notes":[]},{"u":"Акафіст Чесному і Животворящому Хресту Господньому","e":"Akathist to the Precious and Life-giving Cross of the Lord","secs":[{"h":"Кондак 1","ps":["Ізбра́нному Царе́м Сла́ви, і освяще́нному кре́стною сме́ртію Іскупи́теля ми́ра, чудодейственную си́лу і́мущему дре́ву, соста́вим ві́рнії похвалу́ і ра́достно возопії́м:","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всемирного іскупле́нія."]},{"h":"Ікос 1","ps":["А́нгельськія си́ли, я́ко Бо́жії служи́теліє о́крест Креста́ Госпо́дня неви́димо предстоя́ще, ужаса́шася, і поно́сную на землі́ смерть Ісу́сову на небесі́ воспеваша; ми же недосто́йнії, зна́менієм честна́го Креста́ Госпо́дня освяща́яся, ра́достно взива́єм:","Ра́дуйся, честно́є Дре́во, кро́вію Богочелові́ка освяще́нноє;","Ра́дуйся, честно́є Дре́во, прославльшеєся послуша́нієм Христо́вим.","Ра́дуйся, честно́є Дре́во, свободившеє нас от а́да.","Ра́дуйся, честно́є Дре́во, низложе́ніє дия́вола.","Ра́дуйся, честно́є Дре́во, возглаше́ніє си́ли Ісу́совой.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 2","ps":["Ви́дящи Тя на Кресті́ ви́сяща, вся си́ли небе́сния лиця́ закрива́юще, воспева́ша Твоє́ вели́чіє, Жизнода́вче Христе́; ми же на землі́ со стра́хом і тре́петом пред святи́м Твої́м Кресто́м предстоя́ще, воспіва́єм ра́достно піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум пре́жде недоразуміва́ємий, зна́менієм Честна́го і Животворящего Креста́ Госпо́дня ди́вно просвещающийся, со стра́хом і любо́вію покланя́ється свято́му Дре́ву і непреста́нно воспіва́єть си́це:","Ра́дуйся, честни́й Кре́сте Христо́в, із ме́ртвих воскрешающий.","Ра́дуйся, честни́й Кре́сте Христо́в, проявляющий і́стину,","Ра́дуйся, честни́й Кре́сте Христо́в, на нем бо Ісу́с во́лею расп'я́ся і гвозьдми́ бисть пригвожде́н.","Ра́дуйся, честни́й Кре́сте Христо́в, на нем бо свята́я же́ртва принесе́ся.","Ра́дуйся, честни́й Кре́сте Христо́в, Дре́во всеси́льноє.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всемирного іскупле́нія."]},{"h":"Кондак 3","ps":["Си́лою Честна́го і Животворящего Креста́ Госпо́дня бі́си низлага́ються, очища́ється нечи́стоє житіє́ на́ше, гріхо́вния по́мисли отгоня́ються, се́рдце озаря́ється чистото́ю; сего́ ра́ди с ві́рою творя́ Кре́стноє зна́меніє і с благогові́нієм взира́я на ізображе́ніє страда́ній Христо́вих, поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я всегда́ пред очи́ма на́шима Крест святи́й, осіня́ющий святи́я хра́ми Христия́нськия, охраняющий святи́ню Госпо́дню, со слеза́ми благодаре́нія воспіва́єм си́це:","Ра́дуйся, честно́є Дре́во, істо́чниче благ ві́чних.","Ра́дуйся, честно́є Дре́во, освяще́нноє пло́тію і кро́вію Богочелові́ка.","Ра́дуйся, честно́є Дре́во, Дре́во чудодейственноє.","Ра́дуйся, честно́є Дре́во, Дре́во треблаже́нноє.","Ра́дуйся, честно́є Дре́во, Дре́во жи́зні і спасе́нія.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 4","ps":["Бу́рю страсте́й лю́тих си́лен угаси́ти Святи́й і Всечестни́й Крест Христо́в, той бо меч духо́вний, щит ві́рних, ору́жіє всеси́льноє і зна́меніє всепобежда́ющеє; сего́ ра́ди і ми недосто́йнії во весе́лії взива́єм к Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша уче́ніє Христо́во, ві́руєм в та́йну спаси́тельнаго іскупле́нія, покланя́ємся страсте́м Христо́вим, лобиза́єм Крест всеси́льний і ра́достно взива́єм си́це:","Ра́дуйся, честни́й Кре́сте Христо́в, угасивший я́рости пла́м'я.","Ра́дуйся, честни́й Кре́сте Христо́в, порази́вший богоотступников.","Ра́дуйся, честни́й Кре́сте Христо́в, побіди́вший по́лчища вра́жия.","Ра́дуйся, честни́й Кре́сте Христо́в, отсекший главу́ змі́єву.","Ра́дуйся, честни́й Кре́сте Христо́в, торжество́ ві́ри і наде́жди христия́н.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 5","ps":["Богото́чний істо́чник ісціле́ній бисть нам Крест Чудоді́йственний, на нем бо Христо́с во́лею пострада́ на́шего ра́ди спасе́нія, і Боже́ственнії дла́ни своя́ распросте́рши, любо́вію О́тчею с Голго́фи об'я всю вселе́нную, сего́ ра́ди вопіє́м Єму́, Бо́гу на́шему піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши всі язи́ци вели́чіє сла́ви Креста́ Госпо́дня і чудодейственную си́лу і ізображе́нія і зна́менія Єго́, уві́роваша во Святу́ю Живонача́льную і Неразді́льную Тро́йцю, і поклони́шася Кресту́ всечестно́му, ра́достно взива́я:","Ра́дуйся, честно́є Дре́во, си́лою своє́ю на добро́ нас вразумляющеє.","Ра́дуйся, честно́є Дре́во, си́лою своє́ю нас от болі́зней ісціля́ющеє.","Ра́дуйся, честно́є Дре́во, сла́вою своє́ю вся вра́жія си́ли в бі́гство обраща́ющеє.","Ра́дуйся, честно́є Дре́во, сла́вою своє́ю вінцено́сних царе́й прославляющеє.","Ра́дуйся, честно́є Дре́во, вели́чієм свої́м їх ца́рство возвишающеє.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 6","ps":["Пропові́дником Богоно́сним яви́ся честно́є дре́во, із него́ бо бі сооружен Крест Христо́в, трисоста́вний, єго́ бо земля́ чудоді́йственно ізрасти́ нетлі́нним і зіло́ благоухающим, на нем бо Христо́с во́лею закла́н бисть: Єму́ бо, Спаси́телю ми́ра, прино́сим піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ я́ко со́лнце пра́вди, Всечестни́й Крест Христо́в, в ні́драх землі́ сокрове́нний, безду́шними камня́ми я́ко сокро́вище сберега́ємий, і на ра́дость всему́ ми́ру обрете́нний, Єму́ бо велегла́сно вопіє́м:","Ра́дуйся, честни́й Кре́сте Христо́в, моли́твами і усе́рдієм благочести́вия цари́ці Єле́ни на́йденний.","Ра́дуйся, честни́й Кре́сте Христо́в, на висоту́ Патріа́рхом Мака́рієм воздви́гнутий для поклоне́нія всім язи́ком.","Ра́дуйся, честни́й Кре́сте Христо́в, посрамивший ідолопокло́нство і неві́ріє.","Ра́дуйся, честни́й Кре́сте Христо́в, призвавший хули́телей к покая́нію.","Ра́дуйся, честни́й Кре́сте Христо́в, я́ко ти єси́ дре́во чудодейственноє і Христоносноє.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 7","ps":["Хотя́й прояви́ти милосе́рдіє своє́ Спаси́тель ми́ра к ро́ду челові́чеському, во́лею приє́млеть поноше́ніє, присуждається к позорной сме́рті, ко Кресту́ пригвожда́ється і Кре́стною сме́ртію смерть попира́єть, тім бо і ми поє́м Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вноє зрі́лище явля́ється ми́рові: Богочелові́к распина́ється, ру́ці і но́зі пригвожда́ються, ре́бра Єго́ пробода́ються, страданіями Єго́ і уничиже́нієм очища́ються ра́ни гріхо́вния челові́чества. Крест Христо́в побідоно́сним зна́менієм Сла́ви Бо́жия явля́ється, сего́ ра́ди взива́єм си́це:","Ра́дуйся, честно́є Дре́во, смире́нія о́бразе.","Ра́дуйся, честно́є Дре́во, апо́столов похвало́.","Ра́дуйся, честно́є Дре́во, преподо́бних утвержде́ніє.","Ра́дуйся, честно́є Дре́во, му́чеников крі́посте.","Ра́дуйся, честно́є Дре́во, пустинножи́телей огражде́ніє.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до Позорний Крест преврати́ся в дре́во жи́зні і спасе́нія, той бо вразумля́єть, освяща́єть, і от болі́зней душе́вних і тіле́сних ісціля́єть с ві́рою і любо́вію непреста́нно вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Все гріхо́вноє житіє́ на́ше очища́ється чудоді́йственним Кресто́м Спаси́теля ми́ра, послужившим к примире́нію преступнаго челові́чества с Божество́м, сего́ ра́ди благода́рственно вопіє́м:","Ра́дуйся, честни́й Кре́сте Христо́в, явля́ющий нам любо́в і долготерпі́ніє Бо́жиє.","Ра́дуйся, честни́й Кре́сте Христо́в, їм бо соверши́ся призва́ніє язи́ков.","Ра́дуйся, честни́й Кре́сте Христо́в, явле́ніє бла́гости благоуповающим.","Ра́дуйся, честни́й Кре́сте Христо́в, глубино́ упова́нія душ, лю́б'ящих Го́спода.","Ра́дуйся, честни́й Кре́сте Христо́в, си́ло і ра́досте всіх христия́н.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 9","ps":["Вся́кая жите́йськая бу́ря сокруша́ється си́лою Крестних страда́ній Богочелові́ка Ісу́са, іскупивших весь мир, тім бо і ми честву́я Всечестна́го Креста́ Госпо́дня Свято́є зна́меніє, смире́нно прино́сим Бо́гу любві́ і сла́ви ра́достну піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствующий не мо́жеть язи́к ізрещи́ досто́йния похвали́ дре́ву всечестно́му, із него́ бо соста́влен бисть чудоді́йственний Крест Христо́в, благоуха́ющий любо́вію Страда́льця Ісу́са Христа́, сего́ ра́ди і ми недоумі́я досто́йно восхвали́ти Тя, со слеза́ми вопіє́м:","Ра́дуйся, честно́є Дре́во, торжество́ це́ркві Христо́вой.","Ра́дуйся, честно́є Дре́во, вра́чевство на́ше і ра́дость.","Ра́дуйся, честно́є Дре́во, освяще́ніє всіх путе́й жи́зні на́шея.","Ра́дуйся, честно́є Дре́во, всім христия́нам вспоможе́ніє.","Ра́дуйся, честно́є Дре́во, всіх не́мощних си́ло і подкріпле́ніє.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, дла́ни своя́ пречи́стия Христо́с на дре́во вознесе́ і дре́во преслуша́нія бисть дре́во сино́вняго к Бо́гу Отцю́ послуша́нія: рука́, невоздержа́ніє Ада́мово низвергшая, распросте́ртима рука́ма Богочелові́ка соєдиня́єть своє́ю любо́вію всі конці́ ми́ра; тім бо і ми торже́ственно взива́єм побі́дную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́, огражда́ющая от всіх бід і напа́стей, Кре́сте Всечестни́й, Цільбоно́сний істо́чниче всіх язи́ков, осеняющихся святи́м Твої́м зна́менієм во І́м'я Отця́, і Си́на, і Свята́го Ду́ха, сего́ ра́ди с весе́лієм взива́єм:","Ра́дуйся, честни́й Кре́сте Христо́в, Кро́вію Богочелові́ка обагре́нний.","Ра́дуйся, честни́й Кре́сте Христо́в, цвіта́ми ра́йськими благоуха́ющий.","Ра́дуйся, честни́й Кре́сте Христо́в, луча́ми ві́ри нас озаря́ющий.","Ра́дуйся, честни́й Кре́сте Христо́в, луча́ми наде́жди нас подкрепляющий.","Ра́дуйся, честни́й Кре́сте Христо́в, луча́ми любві́ нас обогащающий.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 11","ps":["Пі́ніє похва́льноє прино́сим Ті, Боже́ственноє животворя́щеє Дре́во Креста́ Госпо́дня, ві́рних осіня́ющеє, неві́рних облича́ющеє, і всіх нас ограждающеє от всякого врага́ і супоста́та; сего́ ра́ди вопіє́м піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Пою́ще твоя́ чудеса́, Всеси́льний Кре́сте Христо́в, с ві́рою і благодаре́нієм преклоня́єм колі́на се́рдця на́шего, со слеза́ми лобиза́єм святеї но́зі Страда́льця Ісу́са, покланя́ємся страсте́м Христо́вим, і та́ко вопіє́м:","Ра́дуйся, честно́є Дре́во, ски́птре царе́й христия́нських неприложний.","Ра́дуйся, честно́є Дре́во, держа́во всея́ вселе́нния.","Ра́дуйся, честно́є Дре́во, основа́ніє благоче́стія.","Ра́дуйся, честно́є Дре́во, вода́м освіще́ніє.","Ра́дуйся, честно́є Дре́во, поля́м і садам плодоно́сіє.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 12","ps":["Благода́ть Твою́ Всеси́льную, Го́споди, явля́єть нам Дре́во Треблаже́нноє, осіня́єть ум наш, вразумля́єть і науча́єть пі́ти непреста́нно піснь побі́дную: Аллилу́я."]},{"h":"Ікос 12","ps":["На го́ру Голгофськую водруже́н бисть Крест честни́й, і Ти Созда́тель ми́ра вознесе́н бисть на нем я́ко в позо́р ми́рові; ми же ві́рнії лобиза́єм пречи́стия я́зви Твоя́, покланя́ємся честно́му Кресту́ Твоєму́, си́це взива́я:","Ра́дуйся, честни́й Кре́сте Христо́в, предназначенний Бо́гом для та́їнства іскупле́нія.","Ра́дуйся, честни́й Кре́сте Христо́в, я́ко Ти єси́ ра́достноє зна́меніє на́шего спасе́нія.","Ра́дуйся, честни́й Кре́сте Христо́в, зна́меніє на́шего освобожденія.","Ра́дуйся, честни́й Кре́сте Христо́в, страсте́й на́ших умерщвле́ніє.","Ра́дуйся, честни́й Кре́сте Христо́в, со́вісти на́шея успокоє́ніє.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 13","ps":["О Пречестно́є, Боже́ственноє і Животворя́щеє Дре́во Креста́ Госпо́дня чудоді́йственною Твоє́ю си́лою огради́ м'я, грі́шнаго, осеняющего с ві́рою чело́ моє́ і пе́рси моя́ і вся соста́ви і у́ди моя́ святи́м Твої́м зна́менієм, во і́м'я Отця́, і Си́на, і Свята́го Ду́ха, во Сла́ву Святи́я Тро́йці, во Єди́ниці прославляємей і благода́рственно воспевающего піснь побі́дную: Аллилу́я. Аллилуя. Аллилуя","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськія си́ли, я́ко Бо́жії служи́теліє о́крест Креста́ Госпо́дня неви́димо предстоя́ще, ужаса́шася, і поно́сную на землі́ смерть Ісу́сову на небесі́ воспеваша; ми же недосто́йнії, зна́менієм честна́го Креста́ Госпо́дня освяща́яся, ра́достно взива́єм:","Ра́дуйся, честно́є Дре́во, кро́вію Богочелові́ка освяще́нноє;","Ра́дуйся, честно́є Дре́во, прославльшеєся послуша́нієм Христо́вим.","Ра́дуйся, честно́є Дре́во, свободившеє нас от а́да.","Ра́дуйся, честно́є Дре́во, низложе́ніє дия́вола.","Ра́дуйся, честно́є Дре́во, возглаше́ніє си́ли Ісу́совой.","Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всеми́рнаго іскупле́нія."]},{"h":"Кондак 1","ps":["Ізбра́нному Царе́м Сла́ви, і освяще́нному кре́стною сме́ртію Іскупи́теля ми́ра, чудодейственную си́лу і́мущему дре́ву, соста́вим ві́рнії похвалу́ і ра́достно возопії́м: Ра́дуйся, честно́є Дре́во, на нем бо соверши́ся та́їнство всемирного іскупле́нія."]},{"h":"Молитва","ps":["Ди́вний чудоді́йственною си́лою четвероконе́чний і трисоста́вний Кре́сте Христо́в у подно́жія Твоєго́ во прах распростертий, покланя́юся Ті, честно́є Дре́во, отгоня́ющеє вся́коє де́монськоє стріля́ніє і свобождающеє от всіх бід, скорбе́й і напа́стей. Ти бо єси́ Дре́во жи́зні, Ти бо єси́ очище́ніє возду́ха, освяще́ніє Свята́го Хра́ма, огражде́ніє жили́ща, охране́ніє одра́ моєго́, просві́щеніє ума́ моєго́, се́рдця і всіх мої́х чувств. Твоє́ свято́є зна́меніє огражда́єть м'я со дня моєго́ рожде́нія, просвіща́єть м'я со дня моєго́ креще́нія; о́но со мно́ю і на мні во вся дні живота́ моєго́ на суші́ і на вода́х; о́но же сопровождати м'я бу́деть до могили, осіни́ть і прах мой; о́но бо, свято́є зна́меніє чудодейственнаго Креста́ Госпо́дня, возвісти́ть всей вселе́нній о ча́сі всео́бщаго воскресе́нія ме́ртвих і послі́дняго стра́шнаго і пра́веднаго суда́ Бо́жия.","О Кресті́ Всечестни́й осіне́нієм Твої́м вразуми́, научи́ і благослови́ м'я, недосто́йнаго, всегда́ несомні́нно ві́рующаго в непобіди́мую си́лу Твою́, огради́ м'я от вся́каго врага́ і супоста́та, ісціли́ вся неду́ги моя́ душе́вния і тіле́сния.","Го́споди, Ісу́се Христе́ Си́не Бо́жий! Си́лою Честна́го і Животворящего Креста́ Твоєго́, поми́луй і спаси́ м'я грі́шнаго. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Спаси́, Го́споди, лю́ди Твоя́ / і благослови́ достоя́ніє твоє́, / побі́ди правосла́вним христия́ном / на сопроти́вния да́руя / і Твоє́ сохраня́я // Кресто́м Твої́м жи́тельство."]},{"h":"Кондак, глас 8","ps":["Вознеси́йся на Крест Во́лею, / тезоімени́тому Твоєму́ но́вому жи́тельству / щедро́ти Твоя́, да́руя, Христе́ Бо́же, / возвесели́ нас си́лою Твоє́ю, / побі́ди дая́ нам на супоста́ти, / посо́біє іму́щему Твоє́ ору́жіє ми́ра, // непобіди́мую побі́ду."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / і чтим Крест Твой святи́й, / і́мже нас спасл єси́, // от рабо́ти вра́жия."]}],"notes":[]}];
export default D;
